window.CHAPTERS=window.CHAPTERS||{};window.CHAPTERS["ch06"]={"id":"ch06","title":"第四章 细胞骨架 · 第一节 微管","sub":"翟中和《细胞生物学》第4版 · 教师课件逐页详解","sub2":"微管结构 · 装配 · 马达蛋白 · 功能","modules":[{"i":0,"name":"第一节 微管 · 绪论 · 概览","slides":[{"i":0,"sec":"","title":"第四章 细胞骨架(cytoskeleton)与细胞运动","notes":"【但原核细胞中也存在类似细胞骨架的蛋白和结构，如细菌\nFtsZ, BtubA/B蛋白→tubulin;\nMreB, ParM蛋白→actin;\ncrescentin→中间纤维蛋白】\n学习目的与要求：\n1 细胞骨架及其功能\n2 掌握细胞骨架组装和解聚的动态特点与条件\n3 掌握马达蛋白(motor proteins)的种类和作用原理\n●肌球蛋白(myosin)\n●驱动蛋白(kinesin)、动力蛋白(dynein)","page":1,"level":"掌握","img":"assets/img/ch06/p001.jpg","anim":null,"fig":null,"points":["真核细胞中的蛋白纤维网架体系"],"check":{"q":"关于「第四章 细胞骨架(cytoskeleton)与细…」，下列说法正确的是（　）","o":["A. 真核细胞中的蛋白纤维网架体系","B. 不稳定微管，如纺锤体微管","C. The force-generating heads bind to the MTs；","D. 长春花碱(vinblastine)、除草剂(植物细胞微管研究)"],"a":"A","e":"本页要点：真核细胞中的蛋白纤维网架体系"},"cards":null},{"i":1,"sec":"","title":"什么维持了细胞形态各异的形状?","notes":"一个神经细胞正在伸     小肠上皮    人血红细胞的\n长的轴突部分的荧光照片   细胞微绒毛   电镜扫描照片\n(红色荧光显示的是细胞   突起的电镜\n骨架成分之一微管)\n照片","page":2,"level":"掌握","img":"assets/img/ch06/p002.jpg","anim":null,"fig":null,"points":["细胞骨架"],"check":{"q":"关于「什么维持了细胞形态各异的形状?」，下列说法正确的是（　）","o":["A. 长春花碱(vinblastine)、除草剂(植物细胞微管研究)","B. 细胞骨架","C. A purified GFP-kinesin molecule is seen","D. 基部同A管相连"],"a":"B","e":"本页要点：细胞骨架"},"cards":null}],"mcq":[{"id":"ch06_mcq_6","mod":"绪论 · 概览","modI":0,"q":"凝胶与溶胶的互变与（       ）的变化有关。","o":["A．微丝","B．微管","C．中间丝","D．胶原纤维"],"a":"A","e":"微丝与细胞伪足的形成与迁移运动有关。","kp":"ch06_s0_0"}],"judge":[{"id":"ch06_judge_6","modI":0,"q":"肌肉的收缩是细肌丝收缩的结果。              （      ）","a":"错","e":"肌肉的收缩是粗肌丝和细肌丝相对滑动的结果。","kp":"ch06_s0_0"}],"fill":[{"id":"ch06_fill_10","modI":0,"q":"广义的核骨架成分包括______、______和______。","a":"核基质核纤层；核孔复合体；染色体骨架","kp":"ch06_s0_1"},{"id":"ch06_fill_16","modI":0,"q":"细胞骨架是指存在于真核细胞中的蛋白纤维网架体系，狭义的骨架系统主要是指细胞质 骨架，包括 ______、______和______。","a":"微丝；微管；中间纤维","kp":"ch06_s0_0"}],"short":[{"id":"ch06_short_4","modI":0,"q":"如何用荧光显微镜研究细胞骨架?其基本原理是什么？","a":"用荧光显微镜研究细胞骨架主要是基于两方面的原理。 （1）组成细胞骨架的蛋白亚基能够同小分子的荧光染料共价结合，使细胞骨架带上荧光标 记，发出荧光。 （2）可以制备细胞骨架的荧光抗体，然后用荧光抗体进行细胞骨架的研究。借助于这两方 面原理，可用荧光显微镜研究细胞骨架的动力学。例如，用小分子的荧光染料标记细胞骨架 的蛋白亚基，就可以追踪细胞骨架蛋白在细胞活动中的作用，包括组装、去组装、物质运输 等。这种方法还有一个好处，就是在活细胞时就可以观察。 可用荧光抗体研究以很低浓度存在的蛋白质在细胞内的位置，因为标记的荧光抗体同特异的 蛋白质具有很高的亲和性，只要有相应的蛋白质存在，就一定会有反应。这种反应是特异的， 通过荧光显微镜观察就可确定。荧光抗体既可以直接注射活细胞进行反应，也可以加到固定 的细胞或组织切片中进行反应和分析。用这种方法可对微管、肌动蛋白纤维、中间纤维进行 定位。","kp":"ch06_s0_1"},{"id":"ch06_short_12","modI":0,"q":"何谓细胞骨架？如何理解细胞骨架是细胞内的一种动态结构？","a":"（1）细胞骨架的概念 细胞骨架是指由细胞内蛋白质成分组成的一个复合的网架系统，包括微管、微丝和中间丝。 与其他细胞结构相比，细胞骨架在形态结构上具有弥散性、整体性和变动性等特点，这些都 是与它们的功能相适应的。细胞骨架为真核细胞所特有，它不仅是活细胞的支撑结构，决定 了细胞的形状并赋予其强度，而且在细胞多种多样的生理活动（如细胞运动、膜泡运输和细 胞分裂等）中发挥着重要作用。 （2）细胞骨架是一种动态结构的理解 由于细胞骨架与细胞运动有关，在不同的功能状态、不同的细胞周期，细胞骨架是不断地组 装或去组装，因此细胞骨架是细胞内的一种动态结构。","kp":"ch06_s0_1"},{"id":"ch06_short_14","modI":0,"q":"通过本章的学习，你对生命体的自组装原则有何认识？","a":"我对生命体自组装原则的认识如下： （1）细胞内的复杂结构可由简单的分子组装而成，其组装过程受到细胞本身的调节，这样 便于细胞在不同生理状态下调节细胞结构的组织形式，执行特定的功能。 （2）多种结构相互联系，共同完成细胞的生命活动。 （3）生命体在装配过程中受到多种因素影响。如影响微管组装的因素有秋水仙素、紫杉醇、 长春花碱；影响微丝组装的因素有细胞松弛素、鬼笔环肽。 （4）生命体自组装具有高度的时空顺序性。","kp":"ch06_s0_0"}],"calc":[{"id":"ch06_calc_1","modI":0,"q":"什么是分子马达？举例说明（至少 3 个）。","a":"分子马达（molecular motor），主要是指依赖于微管的驱动蛋白、动力蛋白和依赖于微 丝的肌球蛋白这三类蛋白超家族的成员。它们既能与微管或者微丝结合，又能与一些细胞器 或膜状小泡特异性结合，并利用水解 ATP 所产生的能量有规则地沿微管或微丝等细胞骨架 纤维运输所携带的“货物”。 （1）肌球蛋白是与微丝相关的一类分子马达。其共同特征是都含有一个作为马达结构域的 头部。其马达结构域包含一个微丝结合位点和一个具有 ATP 酶活性的 ATP 结合位点。 ①Ⅱ型肌球蛋白存在于多种细胞，包含 2 条重链和 4 条轻链。头部即马达结构域，尾部主要 起结构作用。Ⅱ型肌球蛋白尾尾相接所构成的双极纤维能介导相邻的微丝相互滑动。 ②Ⅰ型肌球蛋白头部亦为马达结构域，在 ATP 存在时可沿微丝运动。其尾部结构域具有多 样性，能与多种细胞组分结合，通过头部驱动或细胞质膜作相对于微丝的运动。V 型肌球蛋 白是二聚体马达蛋白，具有两个头部，交替与微丝结合可以确保整个分子以及所运载的“货 物”始终不与微丝脱离。 （2）驱动蛋白是一类蛋白质超家族，与微管相关。通常由 2 条重链和 2 条轻链组成，它们 共有保守的“马达”域，内有 ATP 结合位点和微管结合位点。马达结构域在重链的 N 端，介 导物质向微管的正极运动；而另一些少数驱动蛋白的马达结构域在重链的 C 端，介导物质 向微管的负极运动。 驱动蛋白的马达结构域具有两个重要的功能位点： ①ATP 结合位点； ②微管结合位点。 有关驱动蛋白沿微管运动的分子模型有两种：步行模型和尺蠖爬行模型。大多数学者承认步 行模型：驱动蛋白的两个球状头部交替向前，每水解一分子 ATP，落在后面的那个马达结 构域将移动两部的距离，即 16nm，并循环该过程。 （3）动力蛋白是马达蛋白中最大、移动速度最快的成员： ①轴丝动力蛋白，在纤毛与鞭毛中发现，与纤毛和鞭毛的运动相关； ②胞质动力蛋白，在真核细胞胞质内发现，与细胞内介导微管从正极向负极端的膜泡运输以 及有丝分裂动粒和纺锤体的共定位有关。 动力蛋白由 2 条或 3 条重链，多条轻链及中间链组成。其马达结构域位于重链 C 端，轴丝 动力蛋白有 3 个马达结构域，胞质动力蛋白有 2 个马达结构域。","kp":"ch06_s0_0"},{"id":"ch06_calc_4","modI":0,"q":"细胞中同时存在几种骨架体系有什么意义？是否是物质和能量的一种浪费？","a":"（1）细胞骨架是指细胞内以蛋白质纤维为主要成分的网络结构，细胞中同时存在的骨 架体系为微丝、微管和中间丝，这三种细胞骨架的意义在于它们在细胞的生命活动中各自的 功能。 ①微丝的功能主要有：肌细胞中参与肌原纤维收缩；非肌细胞中参与胞质分裂、胞质环流、 吞噬作用、细胞变形运动、膜泡运输、细胞黏着与连接（黏着带与黏着斑）、微绒毛的支撑 结构等。 ②微管的功能主要包括：支架作用，维持细胞形态、定位细胞器，作为细胞内物质运输通道， 作为纤毛、鞭毛的运动元件，构成纺锤体参与细胞分裂等。 ③中间丝的功能有：为细胞提供机械强度支持，参与细胞连接（桥粒与半桥粒），维持核膜 稳定等。 （2）三种骨架成分在细胞中同时存在不是物质和能量的一种浪费，理由如下： 三种骨架成分在细胞中同时存在，自成系统，但又互相联系，互不重合。微丝分布在靠近细 胞膜的部位，微管、中间丝从细胞核向细胞周缘放射状延伸。它们在功能上相互配合、相互 协调，缺乏任何一种骨架成分都会引起细胞生命活动的异常。因此细胞中同时存在几种骨架 体系并不是物质和能量的浪费。","kp":"ch06_s0_0"}],"term":[]},{"i":1,"name":"第一节 微管 · I 细胞骨架的基本组成及其结构","slides":[{"i":2,"sec":"","title":"I 细胞骨架的基本组成及其结构","notes":"●微管 (microtuble, MT)\n中空的管状纤维, 最粗(外径24nm);\n有极性(正极、负极)\n细胞骨架    ●微丝 (microfilament, MF)\n实心丝状纤维，最细(直径7nm);\n有极性(正极、负极)\n●中间纤维(intermediate filament, IF)\n实心线状，粗细居中(直径10nm), 无极性","page":3,"level":"掌握","img":"assets/img/ch06/p003.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":3,"sec":"","title":"Each filament type is assembled from specific subunits in a","notes":"reversible process.\nBottom panels show localization of the 3 filament systems in the\nsame cultured cell.\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · I 细胞骨架的基本组成及其结构 ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 的一体化网络结构。狭义：指细胞质骨架，位于细胞质中，由微丝、微管、中间纤维构成纤维型的网络结构。弥散性、整体性、变动性共同特点：由蛋白质亚基构成的线性多聚体、动态，可组装和去组装、高度保守微管       （中心粒、鞭毛、纤毛、纺锤体）由 13 根原纤维呈纵向平行排列而成微管蛋白(tubulin)：α 微管蛋白、β 微管蛋白（结合 GTP，可水解为 GDP）聚                              原纤维                    微管异二聚体\n\n【本页英文讲解】\n本页讲细胞骨架的三大纤维系统均由各自特定的亚基（subunit）通过可逆的组装与去组装过程装配而成，且这三类纤维可在同一培养细胞中同时存在。下图用不同荧光标记展现了微丝、微管和中间纤维在同一细胞内的定位（localization）差异。考点：三大骨架组分的基本组成与自组装可逆性，对应翟中和《细胞生物学》第4版第十章细胞骨架总论。","page":4,"level":"掌握","img":"assets/img/ch06/p004.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":4,"sec":"","title":"微丝                     微管骨架","notes":"The cytoskeleton filament in a cultured liver cell (2006)\n中间纤维\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · I 细胞骨架的基本组成及其结构 ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 细胞骨架（cytoskeleton）：是细胞内蛋白质成分组成的一个复合网架系统，包括微管、微丝和中间丝。\n\n【本页英文讲解】\n本页以2006年培养的肝细胞（liver cell）为例，展示细胞骨架（cytoskeleton）三种纤维在同一细胞中的分布：微丝（microfilament, MF）、微管（microtubule, MT）以及中间纤维（intermediate filament, IF）。三种纤维相互交织、各成网络，共同维持细胞形态与结构。记忆要点是三大组分的中英名称及它们在细胞内的不同空间排布，为第十章细胞骨架的学习打基础。","page":5,"level":"掌握","img":"assets/img/ch06/p005.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":5,"sec":"","title":"细胞骨架的超微结构及其模式图","notes":"微管(MT)        微丝(MF)   中间纤维(IF)\n组成蛋白tubulin   组成蛋白actin 组成蛋白多种\n\n【读图讲解】\n本图展示细胞骨架三大组分的超微结构与模式图。左侧为微管(MT)，呈中空管状，由α、β微管蛋白(tubulin)二聚体螺旋排列组成，旁附电镜照片；中间为微丝(MF)，由肌动蛋白(actin)单体聚合成的双螺旋结构；右侧为中间纤维(IF)，其组成蛋白种类多样，并绘出组装流程：单体(Monomer)→二聚体(Dimer)→四聚体(Tetramer)→原纤维(Protofilament)→中间纤维(Filament)，标注N端、C端。要点：牢记三类骨架的管状/纤维形态、组成蛋白及IF的逐级组装方式，注意IF无极性、由四聚体为基本单位。","page":6,"level":"掌握","img":"assets/img/ch06/p006.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null}],"mcq":[],"judge":[],"fill":[{"id":"ch06_fill_17","modI":1,"q":"广义细胞骨架包括_________、_________、_________及_________，它们一起构成了高 等动物的纤维网络结构。","a":"细胞核骨架；细胞质骨架；细胞膜骨架；细胞外基质","kp":"ch06_s1_5"}],"short":[{"id":"ch06_short_7","modI":1,"q":"如何证明染色体骨架的真实性？","a":"（1）银染法能选择性地显示染色体轴结构；（2）DNA 酶和 RNA 酶处理或用 0.4mol ／LH2sO4 处理去除组蛋白，对染色体轴没有影响，用胰蛋白酶消化则染色体轴破坏，说明 染色体轴是非组蛋白性的；（3）染色体骨架／放射环模型在分子水平上得到两个直接证据。","kp":"ch06_s1_5"},{"id":"ch06_short_15","modI":1,"q":"除支持作用和运动功能外，细胞骨架还有什么功能？怎样理解“骨架”的概念？","a":"（1）细胞骨架的其他功能 为物质运输提供轨道、参与肌肉收缩和细胞分化、介导染色体的移动和动物细胞胞质分裂、 形成细胞的特化结构等。 （2）“骨架”的理解 ①骨架是指真核细胞内一个复杂的由特异蛋白质组成的纤维网架结构，具有支持功能，在细 胞形态维持、膜性细胞器定位和移动过程中具有重要的作用。 ②理解骨架概念时的注意事项： a．细胞骨架是一种动态平衡的结构； b．具有多种功能； c．由蛋白质组装而成，组装的过程受到信号的调节。","kp":"ch06_s1_5"}],"calc":[{"id":"ch06_calc_2","modI":1,"q":"试述三种胞质细胞骨架的主要成分、形态结构、功能及特异性药物。","a":"细胞骨架（cytoskeleton）是指真核细胞中复杂的蛋白纤维网架体系。广义的细胞骨架包 括细胞核骨架，细胞质骨架，细胞膜骨架和细胞外基质。狭义的细胞骨架是指细胞质骨架， 包括微丝（microfilament，MF）、微管（microtubule，MT）、中间纤维（inter- mediated filament， IF）。 （1）微管的形态结构：中空圆柱状，直径 15nm，一般长几微米，微管蛋白是与肌动蛋白相 似的一种酸性蛋白质，常常以二聚体存在（αβ-微管蛋白）。 微管的功能：①支架作用：维持细胞形态、固定细胞器。②细胞收缩，伪足运动；如纤毛、 鞭毛。③细胞器位移、染色体分裂与位移。④胞质内物质运输。 特异性药物：紫杉酚：抗肿瘤药物，研究表明它对微管的作用与传统的抗癌药长春花碱和秋 水仙碱等相反，它能促进微管的聚合、抑制微管的解聚。是微管的特异性稳定剂。 （2）微丝的形态结构：微丝存在很普遍，具有可变结构，直径 6 μm，由肌动蛋白组成，与 微管共同构成细胞支架。 微丝的功能：①与微管共同形成细胞支架，以维持细胞形状。②具有运动功能，与细胞质的 运动紧密相关。③与细胞器关系密切。④细胞内信号传递、蛋白质合成支架。 特异性药物：鬼笔环肽：特异性与微丝侧面结合，增强其稳定性，抑制微丝解聚，对微丝具 有稳定作用。荧光标记的鬼笔环肽可特异性的显示微丝。是微丝的特异性稳定剂。 细胞松弛素：可以切断微丝，并结合在微丝正极阻抑肌动蛋白聚合，因而可以破坏微丝的三 维网络，特异性的抑制微丝的装配。是微丝的特异性抑制剂。 （3）中间纤维：大小介于微管和微丝之间，结构复杂。中间纤维具有严格的组织特异性， 不同类型细胞含有不同 IF。按其组织来源及免疫原性可分为 5 类：①角蛋白纤维：为上皮 细胞特有，具有α和β两类，β角蛋白存在于体表、体腔的上皮细胞中，α角蛋白形成头发、 指甲等坚韧结构；②波形纤维：存在于间充质细胞及中胚层来源的细胞中；③神经胶质纤维： 存在于星形神经胶质细胞；④结蛋白纤维：存在于肌肉细胞；⑤神经元纤维：存在于神经元 中。 此外细胞核中的核纤层蛋白（lamin）也是一种中间纤维。 肿瘤细胞转移后仍保留源细胞的 IF，因此可用 IF 抗体来鉴定肿瘤的来源。如乳腺癌和胃肠 道癌，含有角蛋白，因此可断定它来源于上皮组织。而且大多数细胞中只含有一种中间纤维 （少数细胞含有两种以上，如骨骼肌细胞含有结蛋白和波形蛋白）。中间纤维这种严格的组 织特异性，就被应用于肿瘤临床鉴别诊断，以鉴别肿瘤细胞。 至今尚未发信中间纤维的特异性药物。","kp":"ch06_s1_5"}],"term":[]},{"i":2,"name":"第一节 微管 · 一、微管","slides":[{"i":6,"sec":"1.1 微管(microtubule, ","title":"一、微管","notes":"一、微管\n1.1 微管(microtubule, MT)的装配\n• 微管蛋白异二聚体(α,β-tubulin)是微管(MT)装配的基本单位。\n• α-tubulin 上有 1 个 GTP 结合位点：不可逆结合、不能水解（N-site，不可交换位点）。\n• 第 2 个 GTP 结合位点在 β-tubulin 上：可逆结合、可水解 GTP（E-site，可交换位点）。\n• α-tubulin + GTP-β-tubulin → α,β-tubulin 二聚体。\n• 装配：二聚体先装配成原纤维(protofilaments) → 侧面增加扩展为片层(sheet) → 13 根原纤维合拢形成中空微管；新的游离 GTP-α,β-tubulin 不断加到两端使微管延长。\n【读图讲解·考点】\nα/β 异二聚体是微管装配的基本单位；两个 GTP 位点不同——α 上的 N-site 不可交换/不水解，β 上的 E-site 可交换并可水解（GTP→GDP）。β 位点 GTP 水解是微管动态不稳定性的分子基础（GTP 帽维持正端聚合，GDP 化促解聚）。","page":7,"level":"掌握","img":"assets/img/ch06/p007.jpg","anim":null,"fig":null,"points":["α,β-tubulin 异二聚体是微管装配基本单位","α 上 N-site：不可交换、不水解；β 上 E-site：可交换、可水解 GTP","GTP→GDP 水解是动态不稳定性基础"],"check":{"q":"关于「微管」，下列说法正确的是（　）","o":["A. 与合成细胞板的物质运输有关","B. 附着在二联体微管上，伸出动","C. 2个GTP结合位点:","D. These drugs efficiently kill certain types of tumor cells"],"a":"C","e":"本页要点：2个GTP结合位点:"},"cards":null},{"i":7,"sec":"1.1 微管(microtubule, ","title":"（本页为图片/无文字层）","notes":"【读图讲解】\n结构示意+电镜。α/β-微管蛋白组成异二聚体（β上含GTP结合位点），二聚体串成原纤维(protofilament)，多条围成中空微管，标注 plus/minus end、lumen。考点：异二聚体是微管基本亚基；微管有极性、中空。","page":8,"level":"掌握","img":"assets/img/ch06/p008.jpg","anim":null,"fig":null,"points":["β-tubulin","GTP","tubulinheterodimer","（=microtubule subunit)","(E)","10nm","protofilament","lumen"],"check":null,"cards":null},{"i":8,"sec":"1.1 微管(microtubule, ","title":"微管的结构和类型 ●形态","notes":"微管类型\n●组成分为：单管、二联体微管、三联体微管\n细胞中大部分微管是单体微管，13根原纤维构成;\n鞭毛、纤毛中，二联体；\n中心体和基体(basal body)中，三联体\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 一、微管 ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 的一体化网络结构。狭义：指细胞质骨架，位于细胞质中，由微丝、微管、中间纤维构成纤维型的网络结构。弥散性、整体性、变动性共同特点：由蛋白质亚基构成的线性多聚体、动态，可组装和去组装、高度保守微管       （中心粒、鞭毛、纤毛、纺锤体）由 13 根原纤维呈纵向平行排列而成微管蛋白(tubulin)：α 微管蛋白、β 微管蛋白（结合 GTP，可水解为 GDP）聚                              原纤维                    微管异二聚体","page":9,"level":"掌握","img":"assets/img/ch06/p009.jpg","anim":null,"fig":null,"points":["Microtubules are hollow, tubular structures","outer diameter of 24 nm, inner diameter of 14 nm","wall thickness of approximately 4 nm","微管的长度变化不定"],"check":{"q":"关于「微管的结构和类型 ●形态」，下列说法正确的是（　）","o":["A. Microtubules are hollow, tubular structures","B. 长春花碱(vinblastine)、除草剂(植物细胞微管研究)","C. A purified GFP-kinesin molecule is seen","D. 基部同A管相连"],"a":"A","e":"本页要点：Microtubules are hollow, tubular structures"},"cards":null},{"i":9,"sec":"1.1 微管(microtubule, ","title":"（本页为图片/无文字层）","notes":"【图中英文对照】\n• Figure 6.24 Structure of a flagellum or motile cilium. —— 图6.24 鞭毛或能动纤毛的结构\n• Microtubules —— 微管\n• Plasma membrane —— 质膜\n• Basal body —— 基体\n• 0.5 μm / 0.1 μm —— 0.5 / 0.1 微米（标尺）\n• (a) A longitudinal section of a motile cilium shows microtubules running the length of the membrane-sheathed structure (TEM). —— (a) 能动纤毛纵切面：微管沿被质膜包裹的结构全长延伸（透射电镜 TEM）\n• (b) A cross section through a motile cilium shows the \"9 + 2\" arrangement of microtubules (TEM). The outer microtubule doublets are held together with the two central microtubules by flexible cross-linking proteins (blue in art), including the radial spokes. The doublets also have attached motor proteins called dyneins (red in art). —— (b) 能动纤毛横切面：微管呈“9+2”排列（TEM）；外侧二联体与两根中央微管由柔性交联蛋白（图中蓝色，含径向辐条）相连；二联体上附着马达蛋白——动力蛋白（图中红色）\n• (c) Basal body: The nine outer doublets of a cilium or flagellum extend into the basal body, where each doublet joins another microtubule to form a ring of nine triplets. Each triplet is connected to the next by nontubulin proteins. This is a \"9 + 0\" arrangement: The two central microtubules are not present because they terminate above the basal body (TEM). —— (c) 基体：纤毛/鞭毛的 9 个外侧二联体伸入基体，各与另 1 根微管结合，形成 9 个三联体的环；相邻三联体由非微管蛋白相连。此为“9+0”排列：两根中央微管在基体上方终止，故基体中不存在（TEM）\n• Outer microtubule doublet —— 外侧微管二联体\n• Central microtubule —— 中央微管\n• Motor proteins (dyneins) —— 马达蛋白（动力蛋白 dynein）\n• Radial spoke —— 径向辐条\n• Cross-linking protein between outer doublets —— 外侧二联体之间的交联蛋白\n• Triplet —— 三联体\n• Cross section of basal body —— 基体横切面\n【读图讲解】\n电镜+模式图。运动纤毛/鞭毛横切为“9+2”：9对外周二联体微管+2根中央微管，二联体带动力蛋白臂(dynein)、辐条(radial spoke)与连接蛋白；基体为“9+0”三联体、无中央微管。考点：9+2 轴丝结构、动力蛋白驱动。","page":10,"level":"掌握","img":"assets/img/ch06/p010.jpg","anim":null,"fig":null,"points":["0.1 μm","Outermicrotubule","Plasma","doublet","membrane","Motorproteins","(dyneins)","Central"],"check":null,"cards":null},{"i":10,"sec":"1.1 微管(microtubule, ","title":"●根据稳定性分为：","notes":"神经元细胞内微管\n\n【读图讲解】\n本图讲细胞骨架(微管)根据稳定性的分类。左侧文字指出：②根据稳定性分为不稳定微管，如纺锤体微管；稳定微管，如鞭毛、纤毛微管及神经元细胞内微管。图(A)显示可溶性小亚基与丝状多聚体之间的双向聚合/解聚平衡。图(B)以细胞示意图表现动态变化：受营养等信号刺激后，已组装的纤维解聚，亚基快速扩散，随后在新的部位重新组装。要点：理解微管动态不稳定性/踏车行为，区分不稳定与稳定微管，明确稳定微管存在于纤毛、鞭毛和神经元突起中。","page":11,"level":"掌握","img":"assets/img/ch06/p011.jpg","anim":null,"fig":null,"points":["不稳定微管，如纺锤体微管","稳定微管， 如鞭毛、纤毛微管;"],"check":{"q":"关于「●根据稳定性分为：」，下列说法正确的是（　）","o":["A. 神经轴突中的蛋白和膜结构的转运;","B. 原生动物中纤毛虫纲、鞭毛虫纲；","C. 不稳定微管，如纺锤体微管","D. 真核细胞中的蛋白纤维网架体系"],"a":"C","e":"本页要点：不稳定微管，如纺锤体微管"},"cards":null},{"i":11,"sec":"1.1 微管(microtubule, ","title":"微管的动态不稳定性 (Microtubule dynamic instability)","notes":"【读图讲解】\n体外实验：游离 tubulin（αβ 异二聚体）浓度高于临界浓度、并满足 pH6.9、Mg²⁺、37℃、GTP 供能时，聚合为微管；低于临界浓度，且有 Ca²⁺ 或 0℃ 低温时，微管解聚为 tubulin。临界浓度=聚合与解聚达动态平衡所需的最低游离 tubulin 浓度。微管末端在生长与缩短间随机切换即为动态不稳定性；右侧荧光延时图像直接记录活细胞中微管的动态变化。\n\n【本页英文讲解】\n本页主题是微管的动态不稳定性（microtubule dynamic instability），即微管末端在聚合与解聚间随机切换。体外（in vitro）实验显示：当微管蛋白（tubulin）浓度高于临界浓度、pH6.9、有Mg²⁺、GTP及37℃时，αβ-tubulin异二聚体聚合成聚合态微管；而tubulin低于临界浓度、有Ca²⁺或0℃低温时微管解聚。原文还提到在活细胞中直接观察到了微管的动态不稳定性。这是本章核心考点。","page":12,"level":"掌握","img":"assets/img/ch06/p012.jpg","anim":null,"fig":null,"points":["体外聚合：tubulin>临界浓度、pH6.9、Mg²⁺、37℃、GTP","体外解聚：tubulin<临界浓度、Ca²⁺、0℃低温","临界浓度=聚合与解聚达动态平衡的最低游离tubulin浓度"],"check":null,"cards":null},{"i":12,"sec":"1.1 微管(microtubule, ","title":"●脚踏车运动 (Microtubule treadmilling)","notes":"【结合课本/笔记】微管相关蛋白是一类可与微管结合并与微管蛋白共同组成微管系统的蛋白，主要功能是调节微管的特异性并将微管连接到特异性的细胞器上。踏车现象：微管蛋白、GTP 浓度达到一定浓度时，在正端结合上去的微管蛋白与负端释放出来的速度相同时，出现的现象。微管组织中心(microtubule organizing center, MTOC)：微管在生理状态或实验处理解聚后重新装配的发生处。功能（功能控制位点）：在细胞质微管装配过程的成核步骤起重要作用(提供核心，两种作用)。如中心体、有丝分裂纺锤体极、基体微管的功能：1 支架作用 2 细胞内运输 3 鞭毛、纤毛运动 4.有丝分裂 5. 物质运输微丝（microvilli、contractile bund\n\n【本页英文讲解】\n本页介绍微管的脚踏车运动（microtubule treadmilling）。它指在同一根微管上，一端不断添加tubulin亚基而另一端不断脱落，整体长度不变但亚基像踏车一样从一端“流向”另一端。这是微管动态性的一种表现形式，与动态不稳定性（dynamic instability）相区别。考研中常以名词解释或与动态不稳定性对比的形式考查，注意区分二者定义与末端行为差异。","page":13,"level":"掌握","img":"assets/img/ch06/p013.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":13,"sec":"1.1 微管(microtubule, ","title":"微管(microtubule) ● 微管蛋白(α,β-tubulin)","notes":"GTP/α,β-tubulin   GDP/α,β-tubulin    解聚\nGTP水解发生在聚合之后。\n微丝、微管的聚合、解聚都是在端部进行的。\n【结合课本/笔记】（三）、细胞骨架、细胞核（3 个英文选择）细胞骨架定义：指真核细胞中的蛋白纤维交织而成的立体网络体系，是细胞的重要组成部分。广义：膜骨架、细胞质骨架、核纤层、核骨架、细胞外基质，构成细胞内外的一体化网络结构。狭义：指细胞质骨架，位于细胞质中，由微丝、微管、中间纤维构成纤维型的网络结构。弥散性、整体性、变动性共同特点：由蛋白质亚基构成的线性多聚体、动态，可组装和去组装、高度保守微管       （中心粒、鞭毛、纤毛、纺锤体）由 13 根原纤维呈纵向平行排列而成微管蛋白(tubulin)：α 微管蛋白、β 微管蛋白（结合 GTP，可水解为 GDP）聚                              原纤维","page":14,"level":"掌握","img":"assets/img/ch06/p014.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":14,"sec":"1.1 微管(microtubule, ","title":"（本页为图片/无文字层）","notes":"【图中英文对照】\nE-site（可交换位点，位于 β-tubulin）\nN-site（不可交换位点，位于 α-tubulin）\nα-tubulin（α-微管蛋白）\nβ-tubulin（β-微管蛋白）\nGTP（三磷酸鸟苷，结合/供能）\nGDP（二磷酸鸟苷，GTP 水解产物）\nGTP cap（GTP 帽，维持正端稳定、继续聚合）\nGTP hydrolysis（GTP 水解→GDP，促解聚）\nGTP-contacting region（GTP 接触区，二聚体界面）\nPlus end of a MT（微管正端 (+) 端）\nprotofilament（原纤维，约 13 条围成中空微管）\n【读图讲解】\n模式图示微管正端 GTP 帽：α/β-微管蛋白异二聚体，β-tubulin 具 E-site/N-site，GTP 结合于二聚体界面，聚合后水解为 GDP。考点：GTP 帽维持正端稳定；GDP 化导致解聚，是动态不稳定性的分子基础。","page":15,"level":"掌握","img":"assets/img/ch06/p015.jpg","anim":null,"fig":null,"points":["E-site","GTP","N-site","β-tubulin","GTP-","GTP","a-tubulin","contacting"],"check":null,"cards":null},{"i":15,"sec":"1.1 微管(microtubule, ","title":"●微管动态不稳定性－GTP cap理论","notes":"GDP cap\n－聚合生长态, 有稳定微管的作用。\n丢失，此时GDP cap－微管趋于解聚\n微丝动态特性具有类似\n的“ATP帽”理论","page":16,"level":"掌握","img":"assets/img/ch06/p016.jpg","anim":null,"fig":null,"points":["两端是GTP-α,β-tubulin时，即形成所谓的微管GTP帽","当聚合速率小于核苷酸水解速率时，两端的GTP帽会"],"check":{"q":"关于「●微管动态不稳定性－GTP cap理论」，下列说法正确的是（　）","o":["A. 长春花碱(vinblastine)、除草剂(植物细胞微管研究)","B. A purified GFP-kinesin molecule is seen","C. 基部同A管相连","D. 两端是GTP-α,β-tubulin时，即形成所谓的微管GTP帽"],"a":"D","e":"本页要点：两端是GTP-α,β-tubulin时，即形成所谓的微管GTP帽"},"cards":null},{"i":16,"sec":"1.1 微管(microtubule, ","title":"Prebleach             漂白","notes":"The study of cytoskeleton using FRAP\nGFP-tubulin\n漂白后300秒              漂白后500秒\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 一、微管 ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 细胞骨架（cytoskeleton）：是细胞内蛋白质成分组成的一个复合网架系统，包括微管、微丝和中间丝。\n\n【本页英文讲解】\n本页展示用荧光漂白恢复技术（fluorescence recovery after photobleaching, FRAP）研究细胞骨架。实验用绿色荧光蛋白标记的微管蛋白（GFP-tubulin），先对局部区域漂白（prebleach/漂白），再在不同时间（漂白后300秒、500秒）观察荧光恢复。荧光恢复说明漂白区外的tubulin亚基不断进入并掺入微管，证明微管处于动态更新之中。FRAP是研究骨架动态性的经典方法，需掌握其原理。","page":17,"level":"掌握","img":"assets/img/ch06/p017.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":17,"sec":"1.1 微管(microtubule, ","title":"Microtubule","notes":"dynamics in\nliving cells\nThe cultured fibroblast was injected with a small volume of\ntubulin-biotin (fluorescent anti-biotin antibodies.)\nApproximately 1min following injection, the cell was fixed.\n→during periods as short as 1min, tubulin subunits are widely\nincorporated at the growing ends of cytoskeletal microtubules.\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 一、微管 ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 微管在生理状态或实验处理解聚后重新装配的发生处称为微管组织中心(microtubule organizingcenter, MTOC)。常见微管组织中心◆间期细胞MTOC：●      中心体(动态微管)\n\n【本页英文讲解】\n本页讲活细胞内微管的动态（dynamics in living cells）。实验向培养的成纤维细胞（fibroblast）注射少量生物素标记的微管蛋白（tubulin-biotin），再用荧光抗生物素抗体检测，注射约1分钟后固定细胞。结果显示，短短1分钟内tubulin亚基已广泛掺入到细胞骨架微管的生长端（growing ends）。这直接证明了微管在活细胞中快速、持续地组装与更新，是动态性的有力证据。","page":18,"level":"掌握","img":"assets/img/ch06/p018.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null}],"mcq":[{"id":"ch06_mcq_2","mod":"一、微管","modI":2,"q":"具有稳定微管的结构特异性药物是（            ）。","o":["A．秋水仙素","B．细胞松弛素","C．鬼笔环肽","D．紫杉酚"],"a":"D","e":"紫杉酚能促进微管的装配，并使已形成的微管稳定，但这种稳定性的增加对细胞是 有害的。","kp":"ch06_s2_15"},{"id":"ch06_mcq_3","mod":"一、微管","modI":2,"q":"微管蛋白在一定条件下，能装配成微管，其管壁由几根原纤维构成？（           ）","o":["A．9","B．11","C．13","D．15"],"a":"C","e":"在微管装配的过程中，αβ二聚体形成后，再形成原纤维（protofilament），经过侧 面增加而扩展为片层，至 13 根原纤维时，即合拢形成一段微管。","kp":"ch06_s2_13"},{"id":"ch06_mcq_7","mod":"一、微管","modI":2,"q":"微管蛋白的异二聚体上具有哪种核苷酸的结合位点？（             ）","o":["A．GDP","B．ADP","C．GTP","D．ATP"],"a":"C","e":"在α/β-微管蛋白二聚体中，α-微管蛋白上有一个 GTP 结合位点，结合在该位点上的 GTP 通常不会被水解，被称为不可交换位点；β-微管蛋白上也有一个 GTP 结合位点，该 GTP 在微管蛋白二聚体参与组装成微管后即被水解成 GDP，因此β-微管蛋白上的 GTP 结合位点 是可交换位点。","kp":"ch06_s2_6"}],"judge":[{"id":"ch06_judge_9","modI":2,"q":"中心粒和基体均不具有自我复制性质。（                       ）","a":"错","e":"中心体与基体都有自我复制能力，新的中心粒是由原来的中心粒在 S 期复制而来， 而基体则可由中心体衍生而来。","kp":"ch06_s2_8"}],"fill":[{"id":"ch06_fill_1","modI":2,"q":"组成细肌丝主要的三种蛋白质是：______、______、______。组成粗肌丝的主要蛋白成 分是：______。构成微管的蛋白有两类：______和______。","a":"肌动蛋白；原肌球蛋白；肌钙蛋白；肌球蛋白；α-微管蛋白；β-微管蛋白","kp":"ch06_s2_13"},{"id":"ch06_fill_4","modI":2,"q":"细胞质骨架包括______、______和______。","a":"微丝；微管；中间丝","kp":"ch06_s2_13"},{"id":"ch06_fill_14","modI":2,"q":"组成细肌丝主要的三种蛋白质是：______、______、______。组成粗肌丝的主要蛋白质 成分是：______ 。构成微管的蛋白有两类：______和 ______。","a":"肌动蛋白；原肌球蛋白；肌钙蛋白；肌球蛋白；α微管蛋白；β微管蛋白","kp":"ch06_s2_13"},{"id":"ch06_fill_15","modI":2,"q":"细胞内具有分子马达（引擎蛋白）作用的蛋白分子有______、______、______、______ 等。","a":"肌球蛋白；动力蛋白；驱动蛋白；ATP 合成酶","kp":"ch06_s2_10"}],"short":[{"id":"ch06_short_3","modI":2,"q":"叙述什么是微管的 GTP 帽和 GDP 帽，其对微管的动态性质有什么影响。","a":"微管的 GTP 或 GDP 帽就是微管正端αβ微管蛋白二聚体结合 GTP 或 GDP 的状态。 （1）如果微管正端结合的是由结合 GTP 的微管蛋白二聚体组成的 GTP 帽结构，微管就趋 于生长； （2）如果微管的正端结合的是由结合 GDP 的微管蛋白二聚体组成的 GDP 帽结构，这种微 管就趋于缩短。 决定微管正端是 GTP 帽还是 GDP 帽，又受两种因素影响：一是结合 GTP 的游离微管蛋白 二聚体的浓度；二是 GTP 帽中 GTP 水解的速度。当（＋）端形成 GTP 帽，而游离微管蛋 白二聚体的浓度又很高时，微管趋向于生长。由于结合 GTP 的游离微管蛋白二聚体的浓度 降低，使得微管延长的速度下降，随着 GTP 水解的不断进行最后 GTP 帽结构转变成 GDP， 逐渐使微管变得不稳定，趋于解聚。细胞内微管的这两种状态是不断发生的，因为细胞内不 断有微管解聚，又不断地有新微管的组装。","kp":"ch06_s2_15"},{"id":"ch06_short_5","modI":2,"q":"比较胞质骨架三种组分。","a":"胞质骨架三种组分比较如下： 表 10-1","kp":"ch06_s2_13"}],"calc":[{"id":"ch06_calc_3","modI":2,"q":"动态不稳定性造成微管迅速伸长或缩短。设想一条单一的处于缩短状态的微管： （1）如果要停止缩短并进入伸长状态，其末端必须发生什么变化？ （2）发生这一转换后微管蛋白的浓度有什么变化？ （3）如果溶液中只有 GDP 而没有 GTP，将会发生什么情况？ （4）如果溶液中存在不能被水解的 GTP 类似物，将会发生什么情况？","a":"（1）由于失去了 GTP 帽，即末端的微管蛋白亚基都以结合 GDP 的形式存在，微管因 而缩短。溶液中带有 GTP 的微管蛋白亚基仍会添加到末端，但是寿命很短，因为 GTP 可能 被水解，或者围绕着的微管解体使其脱落下来。但是如果足够的带有 GTP 的亚基以足够快 的速度添加上去并覆盖了微管末端带有 GDP 的微管蛋白亚基，   这时可产生一个新的 GTP 帽， 微管就可重新开始生长。 （2）当微管蛋白浓度较高时，GTP 亚基的添加速率会比较高，因而缩短微管转变为增长微 管的频率也会随微管蛋白浓度的升高而增加。这种调节机制使该系统达到自主平衡：较多微 管的缩短可造成高浓度的游离微管蛋白，转为增长的微管也就增多；反之，增长的微管多了， 游离微管蛋白浓度下降从而 GTP-亚基的添加速率也下降，在某些部位 GTP 水解的速率会超 过添加速率，造成 GTP 帽破坏，微管又开始进入缩短状态。 （3）如果只有 GDP 存在，微管会持续短缩，并最终消失，因为结合有 GDP 的微管蛋白二 聚体之间的亲和力十分低，不可能被稳定地添加到微管上。 （4）如果有 GTP 存在但不能被水解，那么微管将持续增长，直到所有游离的微管蛋白亚基 被消耗完为止。","kp":"ch06_s2_15"}],"term":[{"id":"ch06_term_4","modI":2,"term":"微管蛋白流（tubulin flow）。","def":"微管踏车学说认为微管组装过程中，在 GTP、 Mg2 等条件下，微管蛋白异二聚体不断 ＋   地在微管正极端聚合使微管延长，而微管的负极端则因微管蛋白的解聚缩短。微管蛋白从负 极端解聚下来，又到正极端聚合的流动称为微管蛋白流，但 GTP 不存在时，微管蛋白流就 不会发生。","kps":"","kp":"ch06_s2_6"},{"id":"ch06_term_5","modI":2,"term":"微管相关蛋白（MAP）","def":"微管相关蛋白（MAP）即微管结合蛋白，是指一些与微管密切联系，附着于微管多聚 体上，参与微管装配并能增加微管稳定性的蛋白，包括 MAP1，MAP2，MAP3，tau 蛋白等。 微管相关蛋白多分布于神经元的树突和轴突中，一般认为与骨架纤维间的连接有关，可能决 定了轴突和树突的不同形态。","kps":"","kp":"ch06_s2_10"}]},{"i":3,"name":"第一节 微管 · 1.2 微管极性:","slides":[{"i":18,"sec":"1.2 微管极性:","title":"1.2 微管极性:","notes":"●αβ→αβ→αβ重复排列, 头尾相接, 构成微管\n结构上的极性；\n●组装、生长速度：两个末端在结构上不是\n等同的→ tubulin二聚体加上/释放优先在微管\n的一端进行，称正极(MT assembly and\ndisassembly occur preferentially at the + end),\n通常正极的聚合速率(the rate of\npolymerization)比负极快。\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 1.2 微管极性: ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 的一体化网络结构。狭义：指细胞质骨架，位于细胞质中，由微丝、微管、中间纤维构成纤维型的网络结构。弥散性、整体性、变动性共同特点：由蛋白质亚基构成的线性多聚体、动态，可组装和去组装、高度保守微管       （中心粒、鞭毛、纤毛、纺锤体）由 13 根原纤维呈纵向平行排列而成微管蛋白(tubulin)：α 微管蛋白、β 微管蛋白（结合 GTP，可水解为 GDP）聚                              原纤维                    微管异二聚体","page":19,"level":"掌握","img":"assets/img/ch06/p019.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":19,"sec":"1.2 微管极性:","title":"Microtubules grow","notes":"preferentially at the\n(+) end\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 1.2 微管极性: ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 微管在生理状态或实验处理解聚后重新装配的发生处称为微管组织中心(microtubule organizingcenter, MTOC)。常见微管组织中心◆间期细胞MTOC：●      中心体(动态微管)\n\n【本页英文讲解】\n本页指出微管（microtubules）主要在正端（plus end, (+) end）优先生长，即tubulin亚基更倾向于加到微管的正端，使微管沿正极方向延伸。由于微管具有极性，正端动力学更活跃（聚合解聚都快），负端相对稳定并常锚定在微管组织中心（MTOC）。这一极性是马达蛋白定向运输和纺锤体组装的基础，属于高频考点。","page":20,"level":"掌握","img":"assets/img/ch06/p020.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null}],"mcq":[{"id":"ch06_amcq_1","mod":"第一节 微管 · 1.2 微管极性:","modI":3,"q":"关于「微管极性:」，下列说法正确的是（　）","o":["A. 真核细胞中的蛋白纤维网架体系","B. ●αβ→αβ→αβ重复排列, 头尾相接, 构成微管","C. 细胞骨架","D. 2个GTP结合位点:"],"a":"B","e":"本页要点：●αβ→αβ→αβ重复排列, 头尾相接, 构成微管","kp":"ch06_s3_18"}],"judge":[{"id":"ch06_ajudge_2","modI":3,"q":"●αβ→αβ→αβ重复排列, 头尾相接, 构成微管","a":"对","e":"本页要点：●αβ→αβ→αβ重复排列, 头尾相接, 构成微管","kp":"ch06_s3_18"}],"fill":[],"short":[],"calc":[],"term":[]},{"i":4,"name":"第一节 微管 · 1.3 MTOC and orienta","slides":[{"i":20,"sec":"1.3 MTOC and orienta","title":"微管组织中心(MTOC):存在于细胞中决定微管","notes":"1.3 MTOC and orientation of cellular MTs\n在生理状态或实验处理 解聚后，重新装配的结\n构称~。\nMTOC：\n●为微管提供生长的起点\n●决定细胞内微管的方向性, 靠近MTOC的一\n端为(-)端； 远离MTOC一端的微管生长快，为\n(+)极。","page":21,"level":"掌握","img":"assets/img/ch06/p021.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":21,"sec":"1.3 MTOC and orienta","title":"微管组织中心（MTOC）","notes":"microtubule organization center\n细胞间期位于细胞核附近；有丝分裂时位于纺\n锤体的两极。\n细胞核旁/核膜？\ncentrosome\n【结合课本/笔记】肌肉收缩系统中的有关蛋白①肌球蛋白(myosin)—所有actin-dependent motor proteins都属于该家族，其头部具ATP酶活力,沿微丝从负极到正极进行运动。·Myosin Ⅱ主要分布于肌细胞，有两个球形头部结构域(具有ATPase活性)和尾部链,多个Myosin尾部相互缠绕，形成myosin filament,即粗肌丝。②原肌球蛋白(tropomyosin, Tm)由两条平行的多肽链形成α-螺旋构型,位于肌动蛋白螺旋沟内,结合于细丝, 调节肌动蛋白与肌球蛋白头部的结合。③肌钙蛋白 (Troponin, Tn)为复合物，包括三个亚基：TnC(Ca2+敏感性蛋白)能特异与Ca2+结合; TnT(与原肌球蛋白结合)","page":22,"level":"掌握","img":"assets/img/ch06/p022.jpg","anim":null,"fig":null,"points":["动物细胞中心体(Centrosome)/中心粒(Centriole)","纤毛、鞭毛的基体(basal body)","真菌细胞中的纺锤体极体","植物细胞？","微管组织中心的γ-tubulin"],"check":{"q":"关于「微管组织中心（MTOC）」，下列说法正确的是（　）","o":["A. The force-generating heads bind to the MTs；","B. 动物细胞中心体(Centrosome)/中心粒(Centriole)","C. 长春花碱(vinblastine)、除草剂(植物细胞微管研究)","D. A purified GFP-kinesin molecule is seen"],"a":"B","e":"本页要点：动物细胞中心体(Centrosome)/中心粒(Centriole)"},"cards":null},{"i":22,"sec":"1.3 MTOC and orienta","title":"中心体","notes":"纤毛、鞭毛的基体\n常见的动物细胞微管组织中心\n\n【读图讲解】\n本图归纳常见的动物细胞微管组织中心(MTOC)。左上为中心体(Centrosome)：位于核旁，微管以其为起点向四周辐射，游离端为(+)极。右上为神经元，MTOC位于细胞体，微管伸入树突与轴突(Axon)，标出(+)、(-)极性。左下为纺锤体，两极(Spindle poles)发出微管连接染色体。右下为纤毛/鞭毛，其基体(Basal body)作为组织中心。要点：各MTOC均从(-)极发生、向(+)极延伸，中心体与基体同源，掌握四类微管组织中心及极性。","page":23,"level":"掌握","img":"assets/img/ch06/p023.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":23,"sec":"1.3 MTOC and orienta","title":"中心体的微管组织中心作用","notes":"【结合课本/笔记】微管相关蛋白是一类可与微管结合并与微管蛋白共同组成微管系统的蛋白，主要功能是调节微管的特异性并将微管连接到特异性的细胞器上。踏车现象：微管蛋白、GTP 浓度达到一定浓度时，在正端结合上去的微管蛋白与负端释放出来的速度相同时，出现的现象。微管组织中心(microtubule organizing center, MTOC)：微管在生理状态或实验处理解聚后重新装配的发生处。功能（功能控制位点）：在细胞质微管装配过程的成核步骤起重要作用(提供核心，两种作用)。如中心体、有丝分裂纺锤体极、基体微管的功能：1 支架作用 2 细胞内运输 3 鞭毛、纤毛运动 4.有丝分裂 5. 物质运输微丝（microvilli、contractile bund","page":24,"level":"掌握","img":"assets/img/ch06/p024.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":24,"sec":"1.3 MTOC and orienta","title":"植物细胞的MTOC","notes":"The same cell that has been\nMTs of a Haemanthus\nstained with an antibody\nendosperm cell during\ninterphase              against purified calf\ncentrosomes.\n【结合课本/笔记】特异的细胞周期特异的细胞周期是指那些特殊的细胞所具有的与标准的细胞周期相比有着鲜明特点的细胞周期。◆爪蟾早期胚胎细胞的细胞周期◆酵母细胞的细胞周期◆植物细胞的细胞周期◆细菌的细胞周期爪蟾早期胚胎细胞的细胞周期·细胞分裂快,无G1期, G2期非常短,S期也短(所有复制子都激活), 以至认为仅含有S期和M期·无需临时合成其它物质·子细胞在G1、G2期并不生长，越分裂体积越小·细胞周期调控因子和调节机制与一般体细胞标准的细胞周期基本是一致的\n\n【本页英文讲解】\n本页讲植物细胞的微管组织中心（microtubule organizing center, MTOC）。图中展示的是一株待宵草（Haemanthus）胚乳细胞（endosperm cell）间期（interphase）的微管，右侧同一细胞用抗纯化小牛中心体（centrosome）的抗体染色。要点是：植物细胞虽有MTOC功能，却没有动物细胞那种含中心粒的中心体，其微管组织中心较为分散。常与动物MTOC对比考查。","page":25,"level":"掌握","img":"assets/img/ch06/p025.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":25,"sec":"1.3 MTOC and orienta","title":"γ-tubulin与微管组织中心(MTOC)","notes":"γ-tubulin 与微管组织中心(MTOC)\n• 动物细胞中心体（微管组织中心）上有由 γ-tubulin 组成的诸多环状结构，每个 γ-tubulin 环都是微管生长的起点（成核部位）。\n• αβ-tubulin 二聚体以一定方向添加到环上，结果长出的微管负极埋在中心体内、正极朝外。\n【考点】γ-tubulin 通常位于 MTOC，在微管组装（成核）中有重要作用；γ-TuRC（γ-微管蛋白环复合体）成核微管并决定其极性方向。","page":26,"level":"掌握","img":"assets/img/ch06/p026.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":26,"sec":"1.3 MTOC and orienta","title":"MT are nucleated by a protein complex containing","notes":"γ-tubulin, and MT was extended from γ-tubulin of\nMTOC\nThe centrosome is the major MTOC of animal cells\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 1.3 MTOC and orienta ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 的一体化网络结构。狭义：指细胞质骨架，位于细胞质中，由微丝、微管、中间纤维构成纤维型的网络结构。弥散性、整体性、变动性共同特点：由蛋白质亚基构成的线性多聚体、动态，可组装和去组装、高度保守微管       （中心粒、鞭毛、纤毛、纺锤体）由 13 根原纤维呈纵向平行排列而成微管蛋白(tubulin)：α 微管蛋白、β 微管蛋白（结合 GTP，可水解为 GDP）聚                              原纤维                    微管异二聚体\n\n【本页英文讲解】\n本页说明微管（MT）由含有γ-微管蛋白（γ-tubulin）的蛋白复合物成核（nucleated），微管从微管组织中心（MTOC）中的γ-tubulin处延伸生长。中心体（centrosome）是动物细胞最主要的MTOC。核心机制是γ-tubulin作为成核核心，决定微管的数量、极性及成核位置。γ-tubulin环状复合物如何启动微管装配，是本章重要考点。","page":27,"level":"掌握","img":"assets/img/ch06/p027.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":27,"sec":"1.3 MTOC and orienta","title":"New MTs are nucleated at the sites of γ-tubulin","notes":"present on the surface of an existing microtubule.\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 1.3 MTOC and orienta ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 的一体化网络结构。狭义：指细胞质骨架，位于细胞质中，由微丝、微管、中间纤维构成纤维型的网络结构。弥散性、整体性、变动性共同特点：由蛋白质亚基构成的线性多聚体、动态，可组装和去组装、高度保守微管       （中心粒、鞭毛、纤毛、纺锤体）由 13 根原纤维呈纵向平行排列而成微管蛋白(tubulin)：α 微管蛋白、β 微管蛋白（结合 GTP，可水解为 GDP）聚                              原纤维                    微管异二聚体\n\n【本页英文讲解】\n本页讲新的微管（MTs）可在已有微管表面的γ-微管蛋白（γ-tubulin）位点处成核（nucleated）。也就是说，除了中心体，细胞中小型成核位点可依附于现有微管，从γ-tubulin处发出新的微管，形成分支式的微管网络。这解释了植物细胞等缺乏典型中心体的细胞如何生成微管，也体现了γ-tubulin作为通用成核因子的作用。","page":28,"level":"掌握","img":"assets/img/ch06/p028.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":28,"sec":"1.3 MTOC and orienta","title":"γ-tubulin ring complex (from J.M.Kollman et al. Nature 2010)","notes":"(a) two copies of γ-tubulin associate a pair of accessory proteins\nto form the γ-tubulin small complex(γ-TuSC).\n(b) 7 copies of the γ-TuSC form a spiral structure\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 1.3 MTOC and orienta ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 微管在生理状态或实验处理解聚后重新装配的发生处称为微管组织中心(microtubule organizingcenter, MTOC)。常见微管组织中心◆间期细胞MTOC：●      中心体(动态微管)\n\n【本页英文讲解】\n本页介绍γ-微管蛋白环状复合物（γ-tubulin ring complex, γ-TuRC），图像取自Kollman等2010年发表在《Nature》上的研究。图中说明：两个γ-tubulin拷贝与一对辅助蛋白（accessory proteins）结合，形成γ-微管蛋白小复合物（γ-tubulin small complex, γ-TuSC）；再由7个γ-TuSC形成一个螺旋状结构（spiral structure），即γ-TuRC。它模拟微管正端的构型，为微管成核提供模板。","page":29,"level":"掌握","img":"assets/img/ch06/p029.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":29,"sec":"1.3 MTOC and orienta","title":"微管在植物细胞中的排列方式","notes":"Spindle\nMTs\nCortical MTs\n周质微管                                       Phragmoplast\n成膜体微管\n早前期带\n●植物细胞：Four major arrays of MTs present during the cell\ncycle of a Plant Cell\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 1.3 MTOC and orienta ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 的一体化网络结构。狭义：指细胞质骨架，位于细胞质中，由微丝、微管、中间纤维构成纤维型的网络结构。弥散性、整体性、变动性共同特点：由蛋白质亚基构成的线性多聚体、动态，可组装和去组装、高度保守微管       （中心粒、鞭毛、纤毛、纺锤体）由 13 根原纤维呈纵向平行排列而成微管蛋白(tubulin)：α 微管蛋白、β 微管蛋白（结合 GTP，可水解为 GDP）聚                              原纤维                    微管异二聚体\n\n【本页英文讲解】\n本页讲微管在植物细胞中的排列方式。植物细胞周期中出现四种主要微管阵列（arrays）：周质微管（cortical MTs）、早前期带（对应未来分裂面 future division plane）、纺锤体微管（spindle MTs）和成膜体微管（phragmoplast）。它们分别参与细胞形态维持、分裂面定位、染色体分离和胞质分裂。原文强调这是植物细胞周期中四类主要微管阵列，属常考的结构—功能对应关系。","page":30,"level":"掌握","img":"assets/img/ch06/p030.jpg","anim":null,"fig":null,"points":["cell wall","future division plane"],"check":{"q":"关于「微管在植物细胞中的排列方式」，下列说法正确的是（　）","o":["A. A purified GFP-kinesin molecule is seen","B. cell wall","C. 基部同A管相连","D. Most kinesins have the motor domain at the N-terminus of the"],"a":"B","e":"本页要点：cell wall"},"cards":null},{"i":30,"sec":"1.3 MTOC and orienta","title":"胞质分裂及植物细胞壁的形成","notes":"有丝分裂后期细胞质一分为二\n动物细胞：微丝及相关的马达蛋白actin/myosin形成收缩环\n(contractile ring)，通过相互滑动使收缩环紧缩完成。\n植物细胞：胞质分裂靠细胞内新细胞壁的形成完成。携带细胞壁\n前体物质的膜泡沿着成膜体微管运到细胞中间，相互融合成膜包\n裹的盘状结构-初级细胞板(cell plate)后向两侧扩大延伸，与原有\n的细胞质膜结合，同时将细胞质分成两半。","page":31,"level":"掌握","img":"assets/img/ch06/p031.jpg","anim":null,"fig":null,"points":["与合成细胞板的物质运输有关"],"check":{"q":"关于「胞质分裂及植物细胞壁的形成」，下列说法正确的是（　）","o":["A. Most kinesins have the motor domain at the N-terminus of the","B. involved in chromosome movement","C. 与合成细胞板的物质运输有关","D. 骨架蛋白对机械刺激，如压"],"a":"C","e":"本页要点：与合成细胞板的物质运输有关"},"cards":null},{"i":31,"sec":"1.3 MTOC and orienta","title":"植物成膜体微管作用","notes":"The phragmoplast guides cytokinesis in higher plants.\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 1.3 MTOC and orienta ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 的一体化网络结构。狭义：指细胞质骨架，位于细胞质中，由微丝、微管、中间纤维构成纤维型的网络结构。弥散性、整体性、变动性共同特点：由蛋白质亚基构成的线性多聚体、动态，可组装和去组装、高度保守微管       （中心粒、鞭毛、纤毛、纺锤体）由 13 根原纤维呈纵向平行排列而成微管蛋白(tubulin)：α 微管蛋白、β 微管蛋白（结合 GTP，可水解为 GDP）聚                              原纤维                    微管异二聚体\n\n【本页英文讲解】\n本页讲植物成膜体微管（phragmoplast）的作用：成膜体引导高等植物的胞质分裂（cytokinesis）。成膜体由反向平行的微管和微丝构成，位于分裂细胞赤道面，指导含细胞壁物质的囊泡向中央运输并融合，逐步形成细胞板（cell plate），最终分隔成两个子细胞。与动物细胞的收缩环分裂方式不同，是植物细胞分裂的特征结构，属高频考点。","page":32,"level":"掌握","img":"assets/img/ch06/p032.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null}],"mcq":[{"id":"ch06_mcq_1","mod":"1.3 MTOC and orienta","modI":4,"q":"由微管组成的细胞表面特化结构是（            ）。","o":["A．鞭毛","B．微绒毛","C．伪足","D．桥粒与半桥粒"],"a":"A","e":"纤毛和鞭毛是细胞表面的特化结构，具有运动功能。纤毛和鞭毛的轴心有一束“9 ＋2”排列的平行微管。","kp":"ch06_s4_22"},{"id":"ch06_mcq_5","mod":"1.3 MTOC and orienta","modI":4,"q":"纤毛、鞭毛的基体由下列哪种微管构成（         ）。","o":["A．二联管","B．三联管","C．单管","D．四联管"],"a":"A","e":"中心粒是三联管。","kp":"ch06_s4_22"}],"judge":[{"id":"ch06_judge_1","modI":4,"q":"通常微管的负端埋在中心体中，而正端只能加长，不能缩短，所以能保证微管的稳定。 （   ）","a":"错","e":"微管的负端埋在中心体中，但正端是可以加长的。","kp":"ch06_s4_25"},{"id":"ch06_judge_2","modI":4,"q":"在动物细胞中，中心体是主要的微管组织中心。（            ）","a":"对","e":"纺锤体微管和胞质微管由中心体基质囊多个γ管蛋白形成的环状核心放射出来。","kp":"ch06_s4_22"},{"id":"ch06_judge_3","modI":4,"q":"微管存在于所有真核生物细胞中。（                 ）","a":"错","e":"人的红细胞中没有微管，另外，原核生物中没有微管。","kp":"ch06_s4_22"},{"id":"ch06_judge_5","modI":4,"q":"在所有动力动物细胞中，中心体是主要的微管组织中心。（                   ）","a":"错","e":"在动物细胞中，微管组织中心还包括纤毛、鞭毛的基体。","kp":"ch06_s4_22"},{"id":"ch06_judge_8","modI":4,"q":"加入秋水仙碱可抑制绿藻细胞中的胞质环流运动。（                        ）","a":"对","e":"秋水仙碱是微管组装的阻断剂，用它处理细胞会导致细胞内微管系统的解体，从而 抑制胞质环流运动。","kp":"ch06_s4_29"}],"fill":[{"id":"ch06_fill_2","modI":4,"q":"______在细胞间期组织形成间期微管，在细胞分裂期组织形成______，因而被称为细胞 的微管组织中心。","a":"中心体；胞质分裂环","kp":"ch06_s4_22"},{"id":"ch06_fill_7","modI":4,"q":"肌丝成分中收缩蛋白有______和______，调节蛋白有______和______。","a":"肌动蛋白；肌球蛋白；原肌球蛋白；肌钙蛋白","kp":"ch06_s4_24"},{"id":"ch06_fill_8","modI":4,"q":"组成纤毛、鞭毛结构的 3 部分是______、______和______，其中______具有 MTOC 作 用。","a":"毛部；基体；根丝；基体","kp":"ch06_s4_22"},{"id":"ch06_fill_13","modI":4,"q":"微管在细胞中以三种形式存在，大部分细胞质微管是______不太稳定；构成纤毛、鞭毛 周围小管的是 ______，比较稳定；组成中心粒和基体的是______，十分稳定。","a":"单体；二联体；三联体","kp":"ch06_s4_22"}],"short":[{"id":"ch06_short_1","modI":4,"q":"微管的主要功能有哪些？","a":"真核细胞内部是高度区域化的体系，微管与生物大分子、细胞器在细胞内的分布，以及 细胞形态的维持具有密切关系。 （1）支持细胞的功能，构成细胞内网状支架，维持细胞形状，固定与支持细胞器的位置。 （2）与细胞器位移和细胞运动有关，染色体的移动、纤毛、鞭毛的运动都是由微管聚合和 解聚产生的。 （3）参与运输，颗粒物质可沿微管移动。 （4）与某些信息的传递有关。","kp":"ch06_s4_23"},{"id":"ch06_short_2","modI":4,"q":"试述纤毛和鞭毛的结构与功能。","a":"纤毛（flagella）和鞭毛（cilia）是真核细胞表面的具有运动功能特化结构。 （1）纤毛和鞭毛的结构：是细胞质膜所包被的细长突起，内部由微管构成轴丝结构。由基 体和纤毛轴丝两部分组成。纤毛轴轴丝为“9＋2”排列微管，即外周 9 组二联体微管＋中央鞘 包围的 2 根中央单体微管。外周二联体微管由 A，B 亚纤维组成，A 亚纤维为完全微管，B 亚纤维仅由 10 个亚基构成。中央微管均为完全微管。基体的微管组成为“9＋0”，无中央微 管。 （2）纤毛和鞭毛的运动机相关的滑动学说被普遍认可：纤毛运动由轴丝介导的相邻二联体 间相互滑动所致。由一个二联体的 A 管伸出的动力蛋白臂的马达结构域在相邻的二联体的 B 管上“行走”。","kp":"ch06_s4_22"},{"id":"ch06_short_11","modI":4,"q":"用秋水仙素处理动物细胞，细胞内质网与高尔基体分布有什么改变，为什么？","a":"（1）秋水仙素处理动物细胞后内质网与高尔基体分布的改变 用秋水仙素处理动物细胞，内质网缩回到细胞核周围，高尔基体解体成小的膜泡样结构分散 在细胞质内，细胞内依赖于微管的物质运输系统全面瘫痪。 （2）发生改变的原因 真核细胞内部是高度区室化的结构，细胞中某些物质的合成部位与行使功能部位往往是不同 的。内膜系统把细胞质分割成一个个区室，将物质合成部位和功能行使部位分隔开，微管是 维持区室化的重要结构基础。秋水仙素是微管蛋白组装抑制剂，当用秋水仙素处理动物细胞 后，微管很快解聚，从而造成内质网和高尔基体凝聚化。","kp":"ch06_s4_22"}],"calc":[],"term":[{"id":"ch06_term_3","modI":4,"term":"微管组织中心（microtubule organizingcenter，MTOC）。","def":"微管组织中心（microtubule organizingcenter，MTOC）是指微管在生理状态或实验处理 解聚后重新装配的发生处。如鞭毛基体、动物细胞中的中心体。微管组织中心决定了细胞微 管的极性，微管的负极指向微管组织中心，正极背向微管组织中心。","kps":"","kp":"ch06_s4_23"},{"id":"ch06_term_7","modI":4,"term":"MTOC","def":"MTOC 的中文名称是微管组织中心。微管组织中心是指具有起始微管组装和延伸的细 胞结构，细胞内的微管组织中心包括中心体和位于纤毛和鞭毛基部的基体等。MTOC 不仅 为微管提供了生长的起点，而且还决定了微管的方向性。靠近 MTOC 的一端由于生长慢而 称为负端；远离 MTOC 一端的微管生长速度快，称为正端，所以正端指向细胞质基质，常 常靠近细胞质膜。","kps":"","kp":"ch06_s4_20"}]},{"i":5,"name":"第一节 微管 · 1.4 微管特异性药物","slides":[{"i":32,"sec":"1.4 微管特异性药物","title":"1.4 微管特异性药物","notes":"Microtubule specific drug\n◆紫杉醇(taxol)：存在于红豆杉属植物中的一种次生代谢产物,\n也是目前所了解的惟一一种可以促进微管聚合和稳定已聚合\n微管的药物。(facilitate the assemble of microtubule, enhance\nthe stability of microtubule； Binding to MTs, stabilize MTs)\n◆秋水仙素(colchicine)\n秋水仙素结合到游离的微管蛋白二聚体, 阻止微管聚合\n(Binding to tubulin dimers, prevent MTs polymerization) ……\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 1.4 微管特异性药物 ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• ·动力学不稳定性产生的原因：微管两端具GTP帽(取决于微管蛋白浓度),微管将继续组装,反之,无GDP帽则解聚。微管特异性药物◆秋水仙素(colchicine)阻断微管蛋白组装成微管，可破坏纺锤体结构。◆紫杉酚(taxol)能促进微管的装配,","page":33,"level":"了解","img":"assets/img/ch06/p033.jpg","anim":null,"fig":null,"points":["长春花碱(vinblastine)、除草剂(植物细胞微管研究)"],"check":{"q":"关于「微管特异性药物」，下列说法正确的是（　）","o":["A. 长春花碱(vinblastine)、除草剂(植物细胞微管研究)","B. 与染色体运动(中期列队赤道板&后期染色单体分离","C. 细胞骨架","D. Microtubules are hollow, tubular structures"],"a":"A","e":"本页要点：长春花碱(vinblastine)、除草剂(植物细胞微管研究)"},"cards":null},{"i":33,"sec":"1.4 微管特异性药物","title":"Effect of the drug taxol on microtubule organization","notes":"MT organization in a liver epithelial cell\nbefore and after taxol treatment.\ncontrol     taxol teatment\nThe natural source\nof taxol\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 1.4 微管特异性药物 ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 微管在生理状态或实验处理解聚后重新装配的发生处称为微管组织中心(microtubule organizingcenter, MTOC)。常见微管组织中心◆间期细胞MTOC：●      中心体(动态微管)\n\n【本页英文讲解】\n本页展示药物紫杉醇（taxol）对微管组织（microtubule organization）的影响。图为肝上皮细胞（liver epithelial cell）在紫杉醇处理前（control）与处理后（taxol treatment）的微管组织对比。紫杉醇能与微管结合并稳定微管，抑制其解聚，从而打乱微管的正常动态与排布。原文还提到紫杉醇的天然来源（natural source）。紫杉醇稳定微管的机制及其抗癌应用是重点。","page":34,"level":"掌握","img":"assets/img/ch06/p034.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null}],"mcq":[{"id":"ch06_mcq_4","mod":"1.4 微管特异性药物","modI":5,"q":"促进微管聚合的药物是（         ）。","o":["A．鬼臼素","B．长春花碱","C．紫杉酚","D．细胞松弛素"],"a":"C","e":"A 项，鬼臼素（peltatin）会抑制细胞 DNA 合成，使细胞处于分裂期。B 项，长春 花碱与秋水仙素的作用相似，能抑制微管的装配，是微管的特异性抑制剂。C 项，紫杉酚和 重水（D2O）可使微管稳定性增加并使细胞周期停止于有丝分裂期。D 项，细胞松弛素可以 切断微丝，并结合在微丝正极阻抑肌动蛋白聚合，而可以破坏微丝的三维网络，特异性的抑 制微丝的装配。","kp":"ch06_s5_32"}],"judge":[{"id":"ch06_judge_4","modI":5,"q":"紫杉酚能促进微管的装配，因此对细胞是有利的。（                    ）","a":"错","e":"紫杉酚能促进微管的装配，但这种稳定性的增加对细胞是有害的，使细胞周期停止 于有丝分裂期。","kp":"ch06_s5_32"}],"fill":[{"id":"ch06_fill_6","modI":5,"q":"微管蛋白二聚体是由______和______组成的。","a":"α-微管蛋白；β微管蛋白","kp":"ch06_s5_32"},{"id":"ch06_fill_12","modI":5,"q":"紫杉醇和长春花碱抗癌作用的机制分别是______。","a":"抑制微管解聚和抑制微管聚合","kp":"ch06_s5_32"}],"short":[],"calc":[],"term":[]},{"i":6,"name":"第一节 微管 · 1.5 微管结合蛋白","slides":[{"i":34,"sec":"1.5 微管结合蛋白","title":"1.5 微管结合蛋白","notes":"microtubule-associated proteins, MAPs:\nproteins that bind along the sides of microtubules\nare collectively called MAPs.\n能够结合单体以及多聚体状态的微管蛋白并调节微管\n功能的蛋白质。\n细胞骨架(微管、微丝、中间纤维)结合蛋白：细\n胞骨架功能的实现及其调节需要结合蛋白的参与；\n结合蛋白在组织细胞骨架排列、动态特性调节以及\n细胞骨架成分之间的相互联系上都有重要作用。","page":35,"level":"掌握","img":"assets/img/ch06/p035.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":35,"sec":"1.5 微管结合蛋白","title":"Mictrotubule-","notes":"associated proteins\n(MAPs) co-purify\nwith microtubules\nPhoto courtesy of\nLynne Cassimeris,\nLehigh University.\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 1.5 微管结合蛋白 ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 肌球蛋白（myosin）：与微丝运动有关的动力蛋白，分头部、颈部和尾部。头部能结合肌动蛋白和 ATP。\n\n【本页英文讲解】\n本页介绍微管结合蛋白（microtubule-associated proteins, MAPs）。这类蛋白能与微管共纯化（co-purify），即随微管一起被分离出来，说明它们与微管紧密结合。MAPs可调节微管的稳定性、成束（bundling）及与其他细胞结构的连接。图片由美国Lehigh大学Lynne Cassimeris提供。掌握MAPs的定义与共纯化这一实验依据，是理解微管功能调控的入口。","page":36,"level":"掌握","img":"assets/img/ch06/p036.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":36,"sec":"1.5 微管结合蛋白","title":"（本页为图片/无文字层）","notes":"【读图讲解】\n汇总模式图：γ-TuRC 在中心体(centrosome)成核并结合微管负端；MAP 调控微管——stathmin 阻止组装、kinesin-13 促灾变、katanin 切断、XMAP215 与 τ/MAP-2 稳定或成束、+TIPs 随正端生长、plectin 连接中间纤维。考点：MAPs 与 γ-TuRC 调控微管组装、稳定与成束。","page":37,"level":"掌握","img":"assets/img/ch06/p037.jpg","anim":null,"fig":null,"points":["Y-TURC","nucleates assembly and","remalnsassoclatedwith","centrosome","the mlnus end","stathmin","+TIPS","binds subunits,"],"check":null,"cards":null},{"i":37,"sec":"1.5 微管结合蛋白","title":"Effects of proteins that bind to microtubule ends.","notes":"【结合课本/笔记】（五）Signal Transduction           （问答英文）ReceptorsDefinition: Any protein that specifically binds to another molecules tomediate cell-cell signaling, adhesion, endocytosis or other cellularprocess. Mostly commonly denotes a protein located in the plasma membraneor cytoplasm that is activated by binding a specific extrace\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 1.5 微管结合蛋白 ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 信号转导（signal transduction）：指细胞外因子通过与受体（膜受体或核受体）结合，引起细胞内的一系列生物化学反应以及蛋白间相互作用，直至细胞生理反应所需基因开始表达、各种生物学效应形成的过程\n\n【本页英文讲解】\n本页标题为结合微管末端蛋白的作用（effects of proteins that bind to microtubule ends）。原文正文较为残缺，仅能判断该页讨论某些蛋白结合到微管两端后对微管动力学的影响：这类蛋白可改变微管末端的聚合或解聚速率，进而调控微管的伸长、缩短或稳定性。理解“末端结合蛋白可调节微管动态”这一核心即可，具体实验细节原文未完整给出。","page":38,"level":"掌握","img":"assets/img/ch06/p038.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":38,"sec":"1.5 微管结合蛋白","title":"● Organization of MTs bundles by MAPs.","notes":"Overexpressing MAP2        Overexpressing tau\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 1.5 微管结合蛋白 ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 的一体化网络结构。狭义：指细胞质骨架，位于细胞质中，由微丝、微管、中间纤维构成纤维型的网络结构。弥散性、整体性、变动性共同特点：由蛋白质亚基构成的线性多聚体、动态，可组装和去组装、高度保守微管       （中心粒、鞭毛、纤毛、纺锤体）由 13 根原纤维呈纵向平行排列而成微管蛋白(tubulin)：α 微管蛋白、β 微管蛋白（结合 GTP，可水解为 GDP）聚                              原纤维                    微管异二聚体\n\n【本页英文讲解】\n本页讲微管结合蛋白（MAPs）对微管成束（bundles）的组织作用。图中分别展示过表达MAP2和过表达tau两种蛋白时微管的排列变化。MAP2和tau都是神经细胞中重要的MAPs，它们能交联相邻微管，使微管形成平行的束状结构，从而稳定和支持神经元突起。要点是不同MAPs介导不同形式的微管成束，tau异常与神经退行性疾病相关，属易考联系点。","page":39,"level":"掌握","img":"assets/img/ch06/p039.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":39,"sec":"1.5 微管结合蛋白","title":"tau主要分布          Localization of MAPs in axon(轴突)","notes":"在神经细胞            and dendrites(树突) of a neuron.\n轴突\n阿尔茨海默症(Alzheimer’s disease,\nAD)患者脑内tau蛋白结构和功能异\n常：\ntau过度磷酸化，易从微管上脱落，\n聚集形成神经元纤维缠结\nMAP2主要分              (neurofibrillary tangles, NFTs)\n布在神经细                                 →\n胞树突                  脑神经细胞内微管稳定性降低，结\n构破坏，依赖微管的物质及信息传\n递系统受损\nThe tistribution of tau (green) and 阻碍正常的神经递质传递，甚至神\nMAP2(orange) in a hippocampal\n经元死亡\nneuron(海马神经细胞) in culture.\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 1.5 微管结合蛋白 ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 的一体化网络结构。狭义：指细胞质骨架，位于细胞质中，由微丝、微管、中间纤维构成纤维型的网络结构。弥散性、整体性、变动性共同特点：由蛋白质亚基构成的线性多聚体、动态，可组装和去组装、高度保守微管       （中心粒、鞭毛、纤毛、纺锤体）由 13 根原纤维呈纵向平行排列而成微管蛋白(tubulin)：α 微管蛋白、β 微管蛋白（结合 GTP，可水解为 GDP）聚                              原纤维                    微管异二聚体","page":40,"level":"掌握","img":"assets/img/ch06/p040.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":40,"sec":"1.5 微管结合蛋白","title":"● Microtubule severing by","notes":"katanin\nA : 30 seconds after the\naddition of katanin\nB : the same field 3 minutes\nafter the addition of katanin\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 1.5 微管结合蛋白 ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 微管在生理状态或实验处理解聚后重新装配的发生处称为微管组织中心(microtubule organizingcenter, MTOC)。常见微管组织中心◆间期细胞MTOC：●      中心体(动态微管)\n\n【本页英文讲解】\n本页讲微管切割蛋白（katanin）对微管的切断作用（microtubule severing）。图A显示加入katanin后30秒，图B显示同一视野加入katanin后3分钟的变化，可见微管被逐渐切短、数量增多。Katanin是一种依赖ATP的微管切割蛋白，通过切断微管产生新的末端，增加微管数量并促进其重组。这是微管结合蛋白调控微管的重要方式，需掌握切割的含义。","page":41,"level":"掌握","img":"assets/img/ch06/p041.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":41,"sec":"1.5 微管结合蛋白","title":"p208","notes":"Proteins that destabilize the ends of microtubules.\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 1.5 微管结合蛋白 ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 的一体化网络结构。狭义：指细胞质骨架，位于细胞质中，由微丝、微管、中间纤维构成纤维型的网络结构。弥散性、整体性、变动性共同特点：由蛋白质亚基构成的线性多聚体、动态，可组装和去组装、高度保守微管       （中心粒、鞭毛、纤毛、纺锤体）由 13 根原纤维呈纵向平行排列而成微管蛋白(tubulin)：α 微管蛋白、β 微管蛋白（结合 GTP，可水解为 GDP）聚                              原纤维                    微管异二聚体\n\n【本页英文讲解】\n本页（教材第208页）指出存在一类使微管末端去稳定的蛋白（proteins that destabilize the ends of microtubules）。这类蛋白结合在微管末端并促进解聚或抑制聚合，从而增加微管的不稳定性、缩短微管寿命。它们与稳定微管的MAPs作用相反，共同精细调控微管动态。原文文字较简略，重点掌握“末端去稳定蛋白”这一概念及其与微管动态稳定性的关系。","page":42,"level":"掌握","img":"assets/img/ch06/p042.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":42,"sec":"1.5 微管结合蛋白","title":"●1.6 马达蛋白 Motor protein:","notes":"A special class of enzymes (ATPase) that use energy from ATP\nhydrolysis to walk or slide along a MF or a MT.\n与微管、微丝结合的一类蛋白，具有ATPase活性，\n水解ATP，将化学能转化成机械能，驱动沿与微管、\n微丝有关的细胞内物质运输或运动(细胞周期中染色体\n运动－微管、细胞变形运动－微丝等)。\n●驱动蛋白(kinesin superfamily): 380 kDa\nkinesin1-kinesin12 move along microtubules(+).\nkinesin13解聚微管；Kinesin14(-)\n●动力蛋白(dyneins): over 1000 kDa\nTo move along microtubules(-).\n●肌球蛋白家族(myosin superfamily): 520 kDa\nTo move along microfilaments(+), except mysoin VI (-)\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 1.5 微管结合蛋白 ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 驱动蛋白（kinesin）：与微丝运动有关的动力蛋白，分头部、颈部和尾部。头部是产\f生力的活性部位，尾部能与膜泡结合。\n• 肌球蛋白（myosin）：与微丝运动有关的动力蛋白，分头部、颈部和尾部。头部能结合肌动蛋白和 ATP。\n\n【本页英文讲解】\n本页介绍马达蛋白（motor protein）：一类具有ATP酶（ATPase）活性的酶，水解ATP将化学能转化为机械能，沿微丝（MF）或微管（MT）行走或滑动，驱动细胞内运输与运动。驱动蛋白超家族（kinesin）约380 kDa，kinesin1–12沿微管正端移动，kinesin13解聚微管，kinesin14向负端移动；动力蛋白（dynein）超1000 kDa，向微管负端移动；肌球蛋白（myosin）约520 kDa，沿微丝正端移动（myosin VI除外）。","page":43,"level":"掌握","img":"assets/img/ch06/p043.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":43,"sec":"1.5 微管结合蛋白","title":"马达蛋白特点：","notes":"Cytoplasmic dynein mechanical energy\nmotor;\nF-actin (MFs) and MTs-tracks;\nATP-fuel\nthat uses intermediate filament\ntracks.\n马达蛋白在微管、微丝上的移动有一定的\n方向性，这对于控制细胞运输或运动的\n方向性非常重要。\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 1.5 微管结合蛋白 ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 驱动蛋白（kinesin）：与微丝运动有关的动力蛋白，分头部、颈部和尾部。头部是产\f生力的活性部位，尾部能与膜泡结合。\n• 肌球蛋白（myosin）：与微丝运动有关的动力蛋白，分头部、颈部和尾部。头部能结合肌动蛋白和 ATP。\n\n【本页英文讲解】\n本页归纳马达蛋白的特点：能将化学能转化为机械能；肌球蛋白（myosin）、驱动蛋白（kinesin）、动力蛋白（dynein）为马达，分别以肌动蛋白纤维（F-actin/MF）和微管（MT）为轨道，以ATP为燃料。原文特别指出，目前尚未发现以中间纤维（intermediate filament）为轨道的马达蛋白。此外，马达蛋白在微管、微丝上移动具有方向性，这对控制细胞运输和运动的方向至关重要。方向性为高频考点。","page":44,"level":"掌握","img":"assets/img/ch06/p044.jpg","anim":null,"fig":null,"points":["Convert chemical energy into","Myosin, kinesin, dynein-","No motor protein is known"],"check":{"q":"关于「马达蛋白特点：」，下列说法正确的是（　）","o":["A. 基部同A管相连","B. Most kinesins have the motor domain at the N-terminus of the","C. involved in chromosome movement","D. Convert chemical energy into"],"a":"D","e":"本页要点：Convert chemical energy into"},"cards":null},{"i":44,"sec":"1.5 微管结合蛋白","title":"微管的马达蛋白(motor protein):","notes":"具有ATPase活性, 水解ATP, 化学能转化\n为机械能, 驱动与微管有关的物质运输\n(intracellular transport)。\n(1)驱动蛋白(kinesin, is a (+) end-directed\nmicrotuble motor protein);\nKinesin1-kinesin12均为正向马达蛋白。\n(2)动力蛋白(dynein, is a (-) end-directed\nMT motor protein)：有两种\n●细胞质动力蛋白(Cytoplasmic dynein)\n●鞭毛、纤毛中的轴丝动力蛋白\nAxonemal dynein\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 1.5 微管结合蛋白 ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 驱动蛋白（kinesin）：与微丝运动有关的动力蛋白，分头部、颈部和尾部。头部是产\f生力的活性部位，尾部能与膜泡结合。\n\n【本页英文讲解】\n本页专讲微管的马达蛋白（motor protein）：具ATP酶活性，水解ATP把化学能转为机械能，驱动与微管有关的物质运输（intracellular transport）。一类是驱动蛋白（kinesin），是向微管正端（(+) end）移动的马达，kinesin1–12均为正向马达；另一类是动力蛋白（dynein），向微管负端（(−) end）移动，包括细胞质动力蛋白（cytoplasmic dynein）和鞭毛、纤毛中的轴丝动力蛋白（axonemal dynein）。正负端方向性是核心考点。","page":45,"level":"掌握","img":"assets/img/ch06/p045.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null}],"mcq":[{"id":"ch06_amcq_1","mod":"第一节 微管 · 1.5 微管结合蛋白","modI":6,"q":"关于「微管结合蛋白」，下列说法正确的是（　）","o":["A. 真核细胞中的蛋白纤维网架体系","B. Convert chemical energy into","C. 细胞骨架","D. 2个GTP结合位点:"],"a":"B","e":"本页要点：Convert chemical energy into","kp":"ch06_s6_34"}],"judge":[{"id":"ch06_ajudge_2","modI":6,"q":"Convert chemical energy into","a":"对","e":"本页要点：Convert chemical energy into","kp":"ch06_s6_34"}],"fill":[{"id":"ch06_fill_5","modI":6,"q":"胞质中微管动力蛋白分为两大类分别为：______（kinesin）和______（cytoplasmic dynein）。 驱动蛋白通常朝微管的______方向运动，动力蛋白朝微管的______运动。","a":"驱动蛋白；动力蛋白；正极；负极","kp":"ch06_s6_44"}],"short":[],"calc":[],"term":[{"id":"ch06_term_6","modI":6,"term":"kinesin & cytoplasmatic dynein 相关试题：驱动蛋白与动力蛋白","def":"kinesin 的中文名称是驱动蛋白，cytoplasmatic dynein 的中文名称是细胞质动力蛋白。二 者均属于微管马达蛋白，主要负责为物质沿着微管运输提供能量。 二者的区别在于沿微管运动的方向不同。驱动蛋白从微管的（－）端移向微管的（＋）端， 是正端走向的微管发动机；细胞质动力蛋白是负端走向的微管发动机，担负小泡和各种膜结 合细胞器的运输任务，同时还是细胞分裂中染色体运动的动力来源。","kps":"","kp":"ch06_s6_44"}]},{"i":7,"name":"第一节 微管 · 1.6.1 驱动蛋白(kinesin)","slides":[{"i":45,"sec":"1.6.1 驱动蛋白(kinesin)","title":"1.6.1 驱动蛋白(kinesin)","notes":"驱动蛋白：两条重链、两条\n轻链构成，MW为380 kD 。\n两个球状头部，一个柄，一\n个尾组成。\ntail\nhead\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 1.6.1 驱动蛋白(kinesin) ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 驱动蛋白（kinesin）：与微丝运动有关的动力蛋白，分头部、颈部和尾部。头部是产\f生力的活性部位，尾部能与膜泡结合。\n\n【本页英文讲解】\n本页介绍驱动蛋白（kinesin）的结构：由两条重链、两条轻链构成，分子量约380 kD，具有两个球状头部（head）、一个柄（stalk）和一个尾部（tail）。核心功能关系是：产生力的头部（head）结合到微管（MT）上，而尾部（tail）结合被运输的货物（cargo）。因此驱动蛋白一头“抓轨道”、一头“拉货物”，沿微管定向运输。掌握头部与尾部的分工是理解其工作机制的关键。","page":46,"level":"掌握","img":"assets/img/ch06/p046.jpg","anim":null,"fig":null,"points":["The force-generating heads bind to the MTs；","the tail binds to the cargo being transported."],"check":{"q":"关于「驱动蛋白(kinesin)」，下列说法正确的是（　）","o":["A. 神经轴突中的蛋白和膜结构的转运;","B. The force-generating heads bind to the MTs；","C. 原生动物中纤毛虫纲、鞭毛虫纲；","D. 真核细胞中的蛋白纤维网架体系"],"a":"B","e":"本页要点：The force-generating heads bind to the MTs；"},"cards":null},{"i":46,"sec":"1.6.1 驱动蛋白(kinesin)","title":"The movement of a labeled kinesin(GFP) molecules along","notes":"microtubules(Cy5). (2007)\nto move processively along a microtubule\nwhose + end is labeled with a red\nfluorescent dye named Cy5.\nrepresent separate micrographs.\n0.77 μm/second.\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 1.6.1 驱动蛋白(kinesin) ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 驱动蛋白（kinesin）：与微丝运动有关的动力蛋白，分头部、颈部和尾部。头部是产\f生力的活性部位，尾部能与膜泡结合。\n\n【本页英文讲解】\n本页（2007年数据）展示荧光标记的驱动蛋白分子沿微管运动。实验将纯化的GFP-驱动蛋白（GFP-kinesin）与正端用红色荧光染料Cy5标记的微管一起观察，可见单个GFP-kinesin持续地（processively）沿微管行走，连续图像从左到右为不同时刻的显微照片，其平均速度约为0.77 μm/秒。该实验直观证明了驱动蛋白能沿微管定向、持续移动，是单分子运动研究的经典证据。","page":47,"level":"掌握","img":"assets/img/ch06/p047.jpg","anim":null,"fig":null,"points":["A purified GFP-kinesin molecule is seen","The successive images, from left to right,","Kinesin is moving at an average speed of"],"check":{"q":"关于「The movement of a labele…」，下列说法正确的是（　）","o":["A. 与染色体运动(中期列队赤道板&后期染色单体分离","B. 细胞骨架","C. A purified GFP-kinesin molecule is seen","D. Microtubules are hollow, tubular structures"],"a":"C","e":"本页要点：A purified GFP-kinesin molecule is seen"},"cards":null},{"i":47,"sec":"1.6.1 驱动蛋白(kinesin)","title":"驱动蛋白特点","notes":"The yeast Saccharomyces cerevisiae酿酒酵母 has 6 distinct\nkinesins, the nematode C. elegans has 20 kinesins, and humans\nhave 45.\nheavy chain and walk toward the + end of the microtubule\n(MT).\nterminus and walks toward the minus end of the MT.\ndepolymerization.\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 1.6.1 驱动蛋白(kinesin) ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 驱动蛋白（kinesin）：与微丝运动有关的动力蛋白，分头部、颈部和尾部。头部是产\f生力的活性部位，尾部能与膜泡结合。\n\n【本页英文讲解】\n本页总结驱动蛋白（kinesin）的特点：酿酒酵母（S. cerevisiae）有6种，线虫（C. elegans）20种，人类多达45种。多数驱动蛋白的马达结构域位于重链N端，向微管正端行走；kinesin-5成员形成反向四聚体，在纺锤体两极微管间滑动；kinesin-14的马达域位于C端，向微管负端行走；kinesin-13则利用ATP水解促进微管解聚。注意各类驱动蛋白的方向与功能差异。","page":48,"level":"掌握","img":"assets/img/ch06/p048.jpg","anim":null,"fig":null,"points":["Most kinesins have the motor domain at the N-terminus of the","Kinesin-5成员形成反向四聚体，在纺锤体两极微管之间滑动。","One fimily（kinesin-14）has the motor domain at the C-","Kinesin-13 uses the energy of ATP hydrolysis to promote MTs"],"check":{"q":"关于「驱动蛋白特点」，下列说法正确的是（　）","o":["A. 与合成细胞板的物质运输有关","B. 附着在二联体微管上，伸出动","C. These drugs efficiently kill certain types of tumor cells","D. Most kinesins have the motor domain at the N-terminus of the"],"a":"D","e":"本页要点：Most kinesins have the motor domain at the N-terminus of the"},"cards":null},{"i":48,"sec":"1.6.1 驱动蛋白(kinesin)","title":"kinesin5通过杆状区","notes":"Kinesin-1 was first\npurified from squid\nneurons, and\nsimilar to myosin II.\n域形成反向四聚体，\n在极性相反的两根相\n邻微管间滑动。如纺\n锤体两极微管。\nSelected members of the kinesin superfamily\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 1.6.1 驱动蛋白(kinesin) ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 驱动蛋白（kinesin）：与微丝运动有关的动力蛋白，分头部、颈部和尾部。头部是产\f生力的活性部位，尾部能与膜泡结合。\n• 肌球蛋白（myosin）：与微丝运动有关的动力蛋白，分头部、颈部和尾部。头部能结合肌动蛋白和 ATP。\n\n【本页英文讲解】\n本页介绍驱动蛋白超家族的成员。驱动蛋白-1（kinesin-1）最早从鱿鱼神经元中纯化得到，结构与肌球蛋白II（myosin II）相似。kinesin-5通过杆状区域形成反向四聚体，能在极性相反的两根相邻微管之间滑动，例如纺锤体两极的微管，从而推动纺锤体两极分离。要点是kinesin-5的反向四聚体结构与在纺锤体中的滑动功能，常与有丝分裂考点结合。","page":49,"level":"掌握","img":"assets/img/ch06/p049.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":49,"sec":"1.6.1 驱动蛋白(kinesin)","title":"（本页为图片/无文字层）","notes":"【图中英文对照】\n• kinesin-1 —— 驱动蛋白-1\n• kinesin-5 —— 驱动蛋白-5\n• kinesin-13 —— 驱动蛋白-13\n• kinesin-14 —— 驱动蛋白-14\n• mRNA —— 信使RNA\n• KIF5/KIF3/KIF17/KIF1A/KIF4等 —— 驱动蛋白家族成员(KIF 系列)\n• Chromokinesin —— 染色体驱动蛋白\n• Eg5/KLP61F/BimC/Cin8/Kip1/Cut7 —— 双极驱动蛋白-5 同源物\n• KIF2A/2B/2C/KLP10A/KLP59C —— 驱动蛋白-13 家族(促微管解聚)\n• KIFC1/C2/C3 —— 驱动蛋白-14 家族(负端方向)\n【读图讲解】\n表格（驱动蛋白超家族）：kinesin-1 运输膜泡/细胞器/mRNA；kinesin-5 双极四聚体分开纺锤体极、确立极性；kinesin-13 纠正动粒微管错误；kinesin-14 组织纺锤体极。考点：驱动蛋白多数朝微管正端移动，结构决定功能。","page":50,"level":"掌握","img":"assets/img/ch06/p050.jpg","anim":null,"fig":null,"points":["表10-1驱动蛋白家族成员的结构与功能","驱动蛋白家族","分子结构模式图","亚基组成及主要成员","kinesin-1","膜泡、细胞器和mRNA","2条重链和2条轻链，如KIF5，KHC","运输"],"check":null,"cards":null},{"i":50,"sec":"1.6.1 驱动蛋白(kinesin)","title":"Two kinesin heads (purple)","notes":"bound to MTs.\nKinesin-1 uses ATP to “walk”\ndown a microtubule.\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 1.6.1 驱动蛋白(kinesin) ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 驱动蛋白（kinesin）：与微丝运动有关的动力蛋白，分头部、颈部和尾部。头部是产\f生力的活性部位，尾部能与膜泡结合。\n\n【本页英文讲解】\n本页图注说明：两个驱动蛋白头部（kinesin heads，图中紫色）结合在微管（MTs）上；驱动蛋白-1（kinesin-1）利用ATP水解供能，沿微管“行走”（walk）。这体现了驱动蛋白以两个头部交替结合与摆动、逐步移动的机制。理解“两个头部交替迈步、ATP驱动、沿微管定向行走”是本节的关键，属于马达蛋白工作机制的高频考点。","page":51,"level":"掌握","img":"assets/img/ch06/p051.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":51,"sec":"1.6.1 驱动蛋白(kinesin)","title":"轴","notes":"突\n内\n部\n的\n微\n管\n及\n马\n达\n蛋\n白\n\n【读图讲解】\n本图为电子显微镜照片，显示轴突内部的微管及马达蛋白。画面为黑白高倍放大像，可见神经轴突内密集排列的纤维与颗粒状结构，白色箭头指向沿微管分布、被运输的囊泡/细胞器样物质。轴突内微管平行成束、极性统一，驱动蛋白与胞质动力蛋白等马达蛋白可携载物质沿微管做双向运输。要点：掌握轴突内微管作为“轨道”、马达蛋白作为“搬运工”的轴突运输机制；读图时注意箭头标示的是被转运的物质，而非微管本身。","page":52,"level":"掌握","img":"assets/img/ch06/p052.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":52,"sec":"1.6.1 驱动蛋白(kinesin)","title":"Dynein是已知马达蛋白中最大，移","notes":"动速度最快的一员。\n发现的第一个dynein是与鞭毛、纤\n毛运动有关的；\n后来从哺乳动物脑组织中分离到细\n胞质动力蛋白：分子量1.2MD 的多\n亚基蛋白巨大分子复合物。\nDyneins are the largest of the known\nmolecular motors, and they are also\namong the fastest: axonemal dyneins\nattached to a glass slide can move\nmicrotubules at the rate of 14 μm/sec.\n1.6.2 ●细胞质动力蛋白(Cytoplasmic dynein)\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 1.6.1 驱动蛋白(kinesin) ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 驱动蛋白（kinesin）：与微丝运动有关的动力蛋白，分头部、颈部和尾部。头部是产\f生力的活性部位，尾部能与膜泡结合。\n\n【本页英文讲解】\n本页介绍动力蛋白（dynein）：它是已知马达蛋白中最大、移动速度最快的一类。最早发现的dynein与鞭毛、纤毛运动有关；后来从哺乳动物脑组织中分离出细胞质动力蛋白（cytoplasmic dynein），是分子量约1.2 MD的多亚基巨大复合物。轴丝动力蛋白（axonemal dynein）固定在玻片上时能以约14 μm/秒的速率移动微管。掌握dynein的大小、速度与两类区分。","page":53,"level":"掌握","img":"assets/img/ch06/p053.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":53,"sec":"1.6.1 驱动蛋白(kinesin)","title":"●鞭毛、纤毛中的轴丝动力蛋白Axonemal dynein，","notes":"主要在鞭毛运动中起作用。\ndynein\n3 heavy chains\n2 intermediate chains\nSeveral light chains\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 1.6.1 驱动蛋白(kinesin) ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 驱动蛋白（kinesin）：与微丝运动有关的动力蛋白，分头部、颈部和尾部。头部是产\f生力的活性部位，尾部能与膜泡结合。\n\n【本页英文讲解】\n本页讲鞭毛、纤毛中的轴丝动力蛋白（axonemal dynein），主要在鞭毛运动中起作用。其结构由3条重链（heavy chains）、2条中间链（intermediate chains）和若干条轻链（light chains）组成，是一种多亚基复合物。轴丝动力蛋白通过水解ATP使相邻二联体微管之间发生滑动，从而引起鞭毛、纤毛弯曲。掌握其亚基组成和驱动纤毛/鞭毛运动的功能。","page":54,"level":"掌握","img":"assets/img/ch06/p054.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":54,"sec":"1.6.1 驱动蛋白(kinesin)","title":"胞质动力蛋白","notes":"纤毛动力蛋白\n\n【读图讲解】\n本图介绍动力蛋白(dynein)。图(A)为负染电镜照片，分别显示胞质动力蛋白(cytoplasmic dynein)与纤毛动力蛋白(ciliary dynein)，标尺25 nm；纤毛动力蛋白可见两个头部。图(B)为分子模式图：重链(heavy chain)构成motor domain，含stalk，红圈标出MT-binding(微管结合位点)和ATPase(ATP水解酶活性位点)；另有中间链(intermediate chains)和轻链(light chains)。要点：动力蛋白是靠ATP供能、沿微管(-)极运输的马达蛋白，其头部结合微管、尾部结合货物。","page":55,"level":"掌握","img":"assets/img/ch06/p055.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null}],"mcq":[],"judge":[],"fill":[{"id":"ch06_fill_3","modI":7,"q":"构成纺锤体的微管有三种：______、______和 ______ 。","a":"星体微管；动力微管；极性微管","kp":"ch06_s7_51"},{"id":"ch06_fill_9","modI":7,"q":"纺锤体中与染色体连接的微管有______和______。","a":"染色体微管；中间微管","kp":"ch06_s7_51"},{"id":"ch06_fill_19","modI":7,"q":"在神经轴突物质转运过程中，有两种马达蛋白介导，一是_________介导运输小泡由轴突 顶端运向胞体；二是_________介导运输小泡由胞体运向轴突顶端。","a":"动力蛋白；驱动蛋白","kp":"ch06_s7_51"}],"short":[{"id":"ch06_short_8","modI":7,"q":"比较细胞质动力蛋白与驱动蛋白。","a":"（1）两者都是将 ATP 的化学能转化为动能的大的发动机蛋白，都与微管结合在一起， 但只有动力蛋白存在于纤毛和鞭毛的微管之中。 （2）驱动蛋白是通过加末端方式来引导微管的运动，动力蛋白则通过减末端方式来引导微 管运动。 （3）虽然它们在功能上有相似之处，但不是同源蛋白，而且立体结构非常不同。它们并不 属于同一蛋白家族。","kp":"ch06_s7_54"}],"calc":[],"term":[{"id":"ch06_term_1","modI":7,"term":"基粒（basal body）。","def":"基粒（basal body）是指位于鞭毛和纤毛根部，类似于动物细胞中的中心体，呈圆柱状 的微管性结构，平均大小为 0.2～0.5μm。其壁由 9 组微管三联体组成，包括完全微管与不 完全微管。胞质动力蛋白。中心粒和基粒是同源的，在某些时候可以相互转变，且都具有自 我复制能力。","kps":"","kp":"ch06_s7_54"}]},{"i":8,"name":"第一节 微管 · 1.7 微管的功能","slides":[{"i":55,"sec":"1.7.2 细胞内物质运输 (micro","title":"1.7 微管的功能","notes":"1.7.1 维持细胞的形态及细胞器在细胞内的位置－支架\n1.7.2 细胞内物质运输 (microtuble&kinesin/dynein)\n微管可作为高尔基体和其他小泡及颗粒的运输轨道\n1.7.3 鞭毛、纤毛的运动\n1.7.4 纺锤体和染色体运动\n主要由微管和其结合蛋白构成。\n聚合&微管间的相对滑动","page":56,"level":"掌握","img":"assets/img/ch06/p056.jpg","anim":null,"fig":null,"points":["神经轴突中的蛋白和膜结构的转运;","鱼色素细胞中色素颗粒的运输;","鞭毛、纤毛结构基本相同，轴心含“9+2”排列的平行微管","运动机制: 相邻二联体微管间的相对滑动/dynein","纺锤体, 与细胞分裂和染色体运动直接相关的临时细胞器，","染色体向两极的运动依靠纺锤体微管(spindle MT)的解聚/"],"check":{"q":"关于「微管的功能」，下列说法正确的是（　）","o":["A. 附着在二联体微管上，伸出动","B. These drugs efficiently kill certain types of tumor cells","C. 不稳定微管，如纺锤体微管","D. 神经轴突中的蛋白和膜结构的转运;"],"a":"D","e":"本页要点：神经轴突中的蛋白和膜结构的转运;"},"cards":null}],"mcq":[],"judge":[{"id":"ch06_judge_7","modI":8,"q":"纤毛的运动是微管收缩的结果。（                ）","a":"错","e":"纤毛的运动是肌动蛋白运动的结果。","kp":"ch06_s8_55"}],"fill":[{"id":"ch06_fill_18","modI":8,"q":"纤毛具有______结构，通过微管上结合的_________分解_______造成微管间的______。","a":"“9＋2”排列的平行微管；ATP 酶；ATP；二联管解聚","kp":"ch06_s8_55"}],"short":[{"id":"ch06_short_13","modI":8,"q":"试分析纤毛不动症发生机制，并以此为例叙述纤毛和鞭毛的运动机制。","a":"（1）纤毛不动症发生机制 纤毛不动症即原发性纤毛运动障碍（PCD），是指纤毛超微结构具有特异的、先天性遗传缺 陷导致的一组疾病。目前认为 PCD 的纤毛异常与内、外动力蛋白臂的缺失或纤毛动力蛋白 臂中 ATP 酶缺乏或代谢异常有关，以致微管滑行缺乏能量，使纤毛摆动受阻。 （2）纤毛和鞭毛的运动机制 纤毛和鞭毛的运动本质是轴丝动力蛋白介导的相邻二联体微管之间的相互滑动。纤毛和鞭毛 摆动的特征是从基体产生滑动，沿着轴丝将弯曲传递到尾部，因此，二联管之间的滑动必须 转换为弯曲运动。当轴丝上任意两点的滑动速率不等时，滑动即可转换为弯曲。 ①滑动速率的差异主要来自维持轴丝结构的连接蛋白，它们在一定程度上限制了二联管的自 由滑动； ②在某一时间某一位置，只有部分动力蛋白臂被激活，激活一半的动力蛋白臂使轴丝朝一边 弯曲，激活另一半则朝另一边弯曲。二条动力蛋白臂的作用不同，内臂产生滑动，导致轴丝 弯曲，而外臂可以加快滑动的速度。","kp":"ch06_s8_55"}],"calc":[],"term":[]},{"i":9,"name":"第一节 微管 · 1.7.1 植物细胞壁中纤维素的定向沉积-微管","slides":[{"i":56,"sec":"1.7.1 植物细胞壁中纤维素的定向沉积","title":"1.7.1 植物细胞壁中纤维素的定向沉积-微管","notes":"(The Arabidopsis Book 2015, Takashi Hashimoto)\n胞内微管的排列方向决定了新合成的细胞壁\n纤维素微纤丝的排列方向→细胞的生长及形态。","page":57,"level":"掌握","img":"assets/img/ch06/p057.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null}],"mcq":[{"id":"ch06_amcq_3","mod":"第一节 微管 · 1.7.1 植物细胞壁中纤维素的定向沉积-微管","modI":9,"q":"关于「植物细胞壁中纤维素的定向沉积-微管」，下列说法正确的是（　）","o":["A. 真核细胞中的蛋白纤维网架体系","B. 细胞骨架","C. 2个GTP结合位点:","D. (The Arabidopsis Book 2015, Takashi Hashimoto)"],"a":"D","e":"本页要点：(The Arabidopsis Book 2015, Takashi Hashimoto)","kp":"ch06_s9_56"}],"judge":[{"id":"ch06_ajudge_4","modI":9,"q":"(The Arabidopsis Book 2015, Takashi Hashimoto)","a":"对","e":"本页要点：(The Arabidopsis Book 2015, Takashi Hashimoto)","kp":"ch06_s9_56"}],"fill":[],"short":[],"calc":[],"term":[]},{"i":10,"name":"第一节 微管 · 1.7.1 维持细胞内膜性细胞器的空间分布：线粒体、","slides":[{"i":57,"sec":"1.7.1 维持细胞内膜性细胞器的空间分","title":"1.7.1 维持细胞内膜性细胞器的空间分布：线粒体、","notes":"高尔基体、核糖体等\nEffect of MTs (red) on the Golgi apparatus (green).\nA:对照 as long as the MTs remains intact, Golgi is localized near\nthe centrosome, close to the nucleus.\nB: After exposure to nocodazole, MTs depolymerized, the Golgi\napparatus fragments and is dispersed throughout the cell.\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 1.7.1 维持细胞内膜性细胞器的空间分布：线粒体、 ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 的一体化网络结构。狭义：指细胞质骨架，位于细胞质中，由微丝、微管、中间纤维构成纤维型的网络结构。弥散性、整体性、变动性共同特点：由蛋白质亚基构成的线性多聚体、动态，可组装和去组装、高度保守微管       （中心粒、鞭毛、纤毛、纺锤体）由 13 根原纤维呈纵向平行排列而成微管蛋白(tubulin)：α 微管蛋白、β 微管蛋白（结合 GTP，可水解为 GDP）聚                              原纤维                    微管异二聚体\n\n【本页英文讲解】\n本页讲微管维持细胞内膜性细胞器的空间分布，如线粒体、高尔基体、核糖体等。图中红色为微管（MTs），绿色为高尔基体。对照（A）：只要微管保持完整，高尔基体就定位在中心体附近、紧靠细胞核；用诺考达唑（nocodazole）处理后（B），微管解聚，高尔基体碎裂并散布到整个细胞中。这证明微管对细胞器定位至关重要，诺考达唑解聚微管是常考实验证据。","page":58,"level":"掌握","img":"assets/img/ch06/p058.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null}],"mcq":[{"id":"ch06_amcq_5","mod":"第一节 微管 · 1.7.1 维持细胞内膜性细胞器的空间分布：线粒体、","modI":10,"q":"关于「维持细胞内膜性细胞器的空间分布：线粒体、」，下列说法正确的是（　）","o":["A. 真核细胞中的蛋白纤维网架体系","B. 高尔基体、核糖体等","C. 细胞骨架","D. 2个GTP结合位点:"],"a":"B","e":"本页要点：高尔基体、核糖体等","kp":"ch06_s10_57"}],"judge":[{"id":"ch06_ajudge_6","modI":10,"q":"高尔基体、核糖体等","a":"对","e":"本页要点：高尔基体、核糖体等","kp":"ch06_s10_57"}],"fill":[],"short":[],"calc":[],"term":[]},{"i":11,"name":"第一节 微管 · 1.7.2 物质运输：微管作为运输轨道，马达蛋白提供动","slides":[{"i":58,"sec":"1.7.1 维持细胞内膜性细胞器的空间分","title":"1.7.2 物质运输：微管作为运输轨道，马达蛋白提供动","notes":"A nerve cell:\nvesicles move in\nboth directions\nwithin the axon\n力驱动。\n例如，神经元细胞\n●向外顺向运输(anterograde transport)：在细胞体中\n合成的蛋白等物质，如神经递质、膜向轴突末端的运\n输。 kinesin/MT运向轴突末梢\n●向内逆向运输(retrograde transport)：轴突末梢形成\n的内吞泡向细胞体运输 dynein\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 1.7.2 物质运输：微管作为运输轨道，马达蛋白提供动 ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 驱动蛋白（kinesin）：与微丝运动有关的动力蛋白，分头部、颈部和尾部。头部是产\f生力的活性部位，尾部能与膜泡结合。","page":59,"level":"掌握","img":"assets/img/ch06/p059.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":59,"sec":"1.7.1 维持细胞内膜性细胞器的空间分","title":"（本页为图片/无文字层）","notes":"【图中英文对照】\n• Microtubule —— 微管\n• Vesicle —— 囊泡\n• Kinesin —— 驱动蛋白\n• Kinesin receptor —— 驱动蛋白受体\n• (−) end —— （−）端（负端）\n• (+) end —— （+）端（正端）\n• Stationary microtubule —— 静止的微管\n• Figure 18-20 Molecular Cell Biology 6e —— 图18-20《分子细胞生物学》第6版\n• 0.1 μm —— 0.1 微米（标尺）\n【读图讲解】\n电镜＋示意图：kinesin 经 kinesin receptor 结合囊泡，沿微管由(-)end 走向(+)end。考点：驱动蛋白向微管正端顺向运输，需 ATP 供能。","page":60,"level":"掌握","img":"assets/img/ch06/p060.jpg","anim":null,"fig":null,"points":["(b)","Microtubule","Vesicles","Vesicle","Kinesin","receptor.","Kinesin","(-) end"],"check":null,"cards":null},{"i":60,"sec":"1.7.1 维持细胞内膜性细胞器的空间分","title":"melanophores(黑色素","notes":"Movement of pigment granules: color adjustment\nMake skin\ndarker                                              Skin paler\nMovement of pigment\ngranules in frog\n细胞).\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 1.7.2 物质运输：微管作为运输轨道，马达蛋白提供动 ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 的一体化网络结构。狭义：指细胞质骨架，位于细胞质中，由微丝、微管、中间纤维构成纤维型的网络结构。弥散性、整体性、变动性共同特点：由蛋白质亚基构成的线性多聚体、动态，可组装和去组装、高度保守微管       （中心粒、鞭毛、纤毛、纺锤体）由 13 根原纤维呈纵向平行排列而成微管蛋白(tubulin)：α 微管蛋白、β 微管蛋白（结合 GTP，可水解为 GDP）聚                              原纤维                    微管异二聚体\n\n【本页英文讲解】\n本页讲色素颗粒运动（movement of pigment granules）与颜色调节（color adjustment）。在蛙的黑色素细胞（melanophores）中，色素颗粒沿细胞骨架定向运输，使皮肤变深（make skin darker）或变浅（skin paler）。颗粒向细胞周边分散时颜色变深，向中心聚集时颜色变浅。这是马达蛋白驱动细胞内运输的直观例证，常用于说明微管/微丝在物质运输中的作用。","page":61,"level":"掌握","img":"assets/img/ch06/p061.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":61,"sec":"1.7.1 维持细胞内膜性细胞器的空间分","title":"对照           突变体","notes":"Expression of a mutant motor protein inhibits the\ndispersion of pigment granules on a pigment cell\n马达蛋白突变体抑制了爪蟾色素细胞中色素颗粒的运输分布。\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 1.7.2 物质运输：微管作为运输轨道，马达蛋白提供动 ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 的一体化网络结构。狭义：指细胞质骨架，位于细胞质中，由微丝、微管、中间纤维构成纤维型的网络结构。弥散性、整体性、变动性共同特点：由蛋白质亚基构成的线性多聚体、动态，可组装和去组装、高度保守微管       （中心粒、鞭毛、纤毛、纺锤体）由 13 根原纤维呈纵向平行排列而成微管蛋白(tubulin)：α 微管蛋白、β 微管蛋白（结合 GTP，可水解为 GDP）聚                              原纤维                    微管异二聚体\n\n【本页英文讲解】\n本页展示表达突变马达蛋白会抑制色素颗粒在色素细胞中的分散（dispersion）。图中为对照（对照）与突变体（突变体）的对比，原文指出马达蛋白突变体会抑制爪蟾色素细胞中色素颗粒的运输与分布。这说明色素颗粒的正常转运依赖功能性马达蛋白，反过来也用于鉴定参与运输的马达蛋白种类。突变体抑制运输是本节经典实验证据。","page":62,"level":"掌握","img":"assets/img/ch06/p062.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null}],"mcq":[{"id":"ch06_amcq_7","mod":"第一节 微管 · 1.7.2 物质运输：微管作为运输轨道，马达蛋白提供动","modI":11,"q":"关于「物质运输：微管作为运输轨道，马达蛋白提供动」，下列说法正确的是（　）","o":["A. 真核细胞中的蛋白纤维网架体系","B. 细胞骨架","C. 2个GTP结合位点:","D. A nerve cell:"],"a":"D","e":"本页要点：A nerve cell:","kp":"ch06_s11_58"}],"judge":[{"id":"ch06_ajudge_8","modI":11,"q":"A nerve cell:","a":"对","e":"本页要点：A nerve cell:","kp":"ch06_s11_58"}],"fill":[],"short":[],"calc":[],"term":[]},{"i":12,"name":"第一节 微管 · 1.7.3 鞭毛(flagellae)、纤毛(cilia)运动","slides":[{"i":62,"sec":"1.7.3 鞭毛(flagellae)、","title":"1.7.3 鞭毛(flagellae)、纤毛(cilia)运动","notes":"而推动前进的；\n集体定向运动推动液体流；\n鞭毛、纤毛中的微管骨架属于永久性微管，没有解\n聚、聚合的动态不稳定性。\n鞭毛、纤毛是一种弯曲运动，其动力主要来源\n于轴丝中微管马达蛋白dynein动力臂带动微管\n的滑动。","page":63,"level":"掌握","img":"assets/img/ch06/p063.jpg","anim":null,"fig":null,"points":["原生动物中纤毛虫纲、鞭毛虫纲；","动物精子细胞；","两栖类和哺乳类动物的卵是依靠输卵管内壁上的纤毛运动","动物呼吸系统中气管由具有纤毛的表皮细胞层组成，纤毛"],"check":{"q":"关于「鞭毛(flagellae)、纤毛(cilia)运…」，下列说法正确的是（　）","o":["A. These drugs efficiently kill certain types of tumor cells","B. 不稳定微管，如纺锤体微管","C. 原生动物中纤毛虫纲、鞭毛虫纲；","D. The force-generating heads bind to the MTs；"],"a":"C","e":"本页要点：原生动物中纤毛虫纲、鞭毛虫纲；"},"cards":null},{"i":63,"sec":"1.7.3 鞭毛(flagellae)、","title":"真核细胞的纤毛","notes":"气管\n草履虫\n\n【读图讲解】\n本图说明真核细胞的纤毛及结构的统一性。草履虫(Paramecium)靠体表纤毛在池塘水中游动，人体气管上皮细胞的纤毛则向上摆动，清除黏液与碎片。图中取两者各一根纤毛做电镜横切对比，均呈“9+2”排列：外围9组二联体微管环绕中央2根单微管，横切图标尺0.1 μm；草履虫标尺15 μm、气管纤毛标尺5 μm示其尺度。要点：尽管草履虫与人类亲缘极远，纤毛却共有相同微管构筑，体现生命多样性的统一；牢记纤毛横切面的9+2结构。","page":64,"level":"掌握","img":"assets/img/ch06/p064.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":64,"sec":"1.7.3 鞭毛(flagellae)、","title":"（本页为图片/无文字层）","notes":"【图中英文对照】\n• Cilia —— 纤毛\n• Longitudinal section of cilium —— 纤毛纵切面\n• Cross section of cilium —— 纤毛横切面\n• Transmission electron microscopy (TEM) —— 透射电镜\n• Scanning electron microscopy (SEM) —— 扫描电镜\n• 2 μm —— 2 微米（标尺）\n• TEM text —— TEM 显示标本薄切片剖面；气管细胞的纤毛沿长度切为纵切面、垂直切为横切面\n• SEM text —— SEM 显示标本表面三维图像；气管细胞表面覆盖纤毛突起，黑白电镜图常人工着色\n【读图讲解】\n电镜组图：SEM 示气管上皮表面纤毛三维形态；TEM 示纤毛纵切与横切，横切可见微管成环排列（9+2）。考点：纤毛由微管构成，横切显示 9+2 轴丝。","page":65,"level":"掌握","img":"assets/img/ch06/p065.jpg","anim":null,"fig":null,"points":["tha scan-","Longitudinalsection","Crosssection","ofcilium","ofcilium","Transmissionelectron","specimen.","microscopy (TEM)."],"check":null,"cards":null},{"i":65,"sec":"1.7.3 鞭毛(flagellae)、","title":"鞭毛(flagellae)、纤毛(cilia)轴心结构组分","notes":"1) “9+2”排列的平行微管\n2中央单体微管 + 9外围二联体微管\n2) 微管马达蛋白－动力蛋白\n(axonemal dynein)\n力臂(dynein arms)同相邻二联体微管\n作用, 使纤毛运动。 3) 微管连接蛋白(nexin): 将相\n邻微管二联体连在一块","page":66,"level":"掌握","img":"assets/img/ch06/p066.jpg","anim":null,"fig":null,"points":["附着在二联体微管上，伸出动"],"check":{"q":"关于「鞭毛(flagellae)、纤毛(cilia)轴…」，下列说法正确的是（　）","o":["A. involved in chromosome movement","B. 附着在二联体微管上，伸出动","C. 骨架蛋白对机械刺激，如压","D. 2个GTP结合位点:"],"a":"B","e":"本页要点：附着在二联体微管上，伸出动"},"cards":null},{"i":66,"sec":"1.7.3 鞭毛(flagellae)、","title":"轴丝动力蛋","notes":"白(axonemal\ndynein)的球\n形头部伸向\n相邻二联体\n的B管。\nLongitudinal\nview of an\naxoneme\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 1.7.3 鞭毛(flagellae)、纤毛(cilia)运动 ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 驱动蛋白（kinesin）：与微丝运动有关的动力蛋白，分头部、颈部和尾部。头部是产\f生力的活性部位，尾部能与膜泡结合。\n\n【本页英文讲解】\n本页讲轴丝动力蛋白（axonemal dynein）的结构与位置：其球形头部伸向相邻二联体微管的B管，图中给出轴丝（axoneme）的纵切面（longitudinal view）。轴丝动力蛋白一端固定在自己的A管上，头部朝向相邻二联体的B管，水解ATP时试图使相邻二联体相对滑动。由于二联体间存在连接，滑动被转化为弯曲。掌握“头部朝向相邻B管”这一结构特征是理解鞭毛运动的基础。","page":67,"level":"掌握","img":"assets/img/ch06/p067.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":67,"sec":"1.7.3 鞭毛(flagellae)、","title":"• 是多头的动力蛋白","notes":"ciliary dynein\n纤毛运动机制\n动相邻轴心外围的微管二联体间(outer doublet MTs)\n的相对滑动\nMTs “walk” along the adjacent doublet’s B tubule.\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 1.7.3 鞭毛(flagellae)、纤毛(cilia)运动 ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 驱动蛋白（kinesin）：与微丝运动有关的动力蛋白，分头部、颈部和尾部。头部是产\f生力的活性部位，尾部能与膜泡结合。","page":68,"level":"掌握","img":"assets/img/ch06/p068.jpg","anim":null,"fig":null,"points":["基部同A管相连","头部同相邻的B管相连","头部具有ATP结合位点，能够水解ATP。","动力蛋白臂(dynein arms)水解ATP产生能量，驱","The dynein arms on the A tubule of one doublet"],"check":{"q":"关于「• 是多头的动力蛋白」，下列说法正确的是（　）","o":["A. 细胞骨架","B. Microtubules are hollow, tubular structures","C. 两端是GTP-α,β-tubulin时，即形成所谓的微管GTP帽","D. 基部同A管相连"],"a":"D","e":"本页要点：基部同A管相连"},"cards":null},{"i":68,"sec":"1.7.3 鞭毛(flagellae)、","title":"微管的相对滑动   Microtubule/dynein sliding causes","notes":"cilia/flagella to bend- Crosslinks and\nspokes\n连接蛋白nexin\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 1.7.3 鞭毛(flagellae)、纤毛(cilia)运动 ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 驱动蛋白（kinesin）：与微丝运动有关的动力蛋白，分头部、颈部和尾部。头部是产\f生力的活性部位，尾部能与膜泡结合。\n\n【本页英文讲解】\n本页讲微管的相对滑动（microtubule/dynein sliding）引起纤毛和鞭毛弯曲。轴丝动力蛋白（dynein）驱动相邻二联体微管相互滑动，但由于二联体之间由连接蛋白（nexin）和放射辐（spokes）等结构限制，滑动不能自由进行，于是被转换成纤毛、鞭毛的弯曲运动。要点是“滑动→受连接蛋白约束→弯曲”这一逻辑链，是纤毛/鞭毛运动机制的核心考点。","page":69,"level":"掌握","img":"assets/img/ch06/p069.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":69,"sec":"1.7.3 鞭毛(flagellae)、","title":"A 体外：外侧二联体微管及结合的动力蛋白从精子","notes":"鞭毛分离出来然后处于ATP中，由于microtubules与\n其结合的马达蛋白dynein的相互作用，水解ATP，驱\n动微管之间以望远镜拉长的方式自身相互滑动。\nB 体内：在一条完整的鞭毛中，它的外侧二联体微\n管通过易弯曲的蛋白－微管连接蛋白(nexin)连接而相\n互结合在一起，所以整个系统产生的动作是弯曲而不\n是滑动。","page":70,"level":"掌握","img":"assets/img/ch06/p070.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null}],"mcq":[],"judge":[],"fill":[{"id":"ch06_fill_11","modI":12,"q":"构成一根微管的原纤丝有______条。","a":"13","kp":"ch06_s12_68"}],"short":[{"id":"ch06_short_9","modI":12,"q":"列举细菌与动物细胞之间的差别。这些差别很可能是由于在进化过程中出现的部分或所 有现代真核细胞具有的细胞骨架所造成的。","a":"（1）动物细胞相当大，形状多变，而且没有细胞壁，因而需要细胞骨架来支撑并保持 其形状。 （2）动物细胞及其他真核细胞都有细胞核，细胞核靠中间纤维在细胞中成形并维持在适当 的部位。核纤层附着于核被膜的内侧，支持核被膜并使之成形，中间纤维网络包围核并穿行 在细胞质中。 （3）动物细胞可通过改变细胞形状进行移动。这—过程需要肌动蛋白及肌球蛋白的参与。 （4）动物细胞的基因组比细菌大得多，分为许多染色体。细胞分裂时，染色体必须精确地 分配到两个子细胞中。这—过程需要形成有丝分裂纺锤体的微管系统参与。 （5）动物细胞具有胞内细胞器。细胞器在胞内的定位依赖于沿着微管移动的发动机蛋白。 显著的例子是从脊髓到脚部的神经轴突（该轴突可长达 1 m）中，胞内运输小泡（细胞器） 沿着微管的长距离运输。","kp":"ch06_s12_63"},{"id":"ch06_short_10","modI":12,"q":"什么叫凝胶-溶胶（gel-sol）和溶胶-凝胶（sol-gel）转变？","a":"原生动物中的变形虫，高等动物中的巨噬细胞和白细胞等没有鞭毛、纤毛等运动器官， 但能够依靠细胞体的变化进行移动，叫作变形运动。通常要靠胞质环流形成伪足，细胞沿着 伪足形成的方向前进。细胞内流动的细胞质叫作内质，从尾部流向前进中的伪足。当液流到 达伪足时，流动的细胞质分向细胞的两侧，并形成较硬的外质。其间，位于细胞后部的外质 被破坏并向前方提供新的内质，由此产生内质和外质的循环转变，并引起细胞向前移动。细 胞质由坚硬的凝质状态（外质）向可流动的液态（内质）转变的过程称为凝胶-溶胶转变， 相反的过程叫溶胶-凝胶转变。","kp":"ch06_s12_68"}],"calc":[],"term":[]},{"i":13,"name":"第一节 微管 · 1.7.4 染色体运动","slides":[{"i":70,"sec":"1.7.4 染色体运动","title":"1.7.4 染色体运动","notes":"纺锤体(spindle):\n移向细胞两极)直接相关的细胞器；\n地更加活跃。\nLight micrographs of lily endosperm(胚乳) cells\n\n【读图讲解】\n本图讲1.7.4染色体运动与纺锤体。文字给出定义：纺锤体(spindle)是与染色体运动(中期排列于赤道板、后期染色单体分离移向两极)直接相关的细胞器，主要由微管和微管相关蛋白组成；微管的动态不稳定性在有丝分裂期比间期更活跃。下方为百合胚乳(lily endosperm)细胞光镜照片(A、B)，标尺20 μm：A中染色体趋向赤道板，红色纺锤丝连接两极；B为后期，染色体呈V形分向两极。要点：掌握纺锤体的成分、功能及微管动态特性。","page":71,"level":"掌握","img":"assets/img/ch06/p071.jpg","anim":null,"fig":null,"points":["与染色体运动(中期列队赤道板&后期染色单体分离","主要由微管和微管相关蛋白组成。","微管的动态不稳定性在细胞有丝分裂期比间期表现"],"check":{"q":"关于「染色体运动」，下列说法正确的是（　）","o":["A. 长春花碱(vinblastine)、除草剂(植物细胞微管研究)","B. A purified GFP-kinesin molecule is seen","C. 与染色体运动(中期列队赤道板&后期染色单体分离","D. 基部同A管相连"],"a":"C","e":"本页要点：与染色体运动(中期列队赤道板&后期染色单体分离"},"cards":null},{"i":71,"sec":"1.7.4 染色体运动","title":"（本页为图片/无文字层）","notes":"【图中英文对照】\n• Interphase —— 间期\n• Prophase —— 前期\n• Prometaphase —— 前中期\n• Metaphase —— 中期\n• Anaphase —— 后期\n• Telophase —— 末期\n• Cytokinesis —— 胞质分裂\n• Chromosome duplication and cohesion —— 染色体复制与黏连\n• Centrosome duplication —— 中心体复制\n• Mitotic aster separation —— 有丝分裂星体分离\n• Chromosome condensation —— 染色体凝缩\n• Nuclear envelope breakdown —— 核膜解体\n• Chromosomes aligned at the metaphase plate —— 染色体排列在中期板(赤道板)\n• APC/C activated and cohesins degraded —— APC/C 激活、黏连蛋白降解\n• Anaphase A: chromosome movement to poles —— 后期A：染色体移向两极\n• Anaphase B: spindle pole separation —— 后期B：纺锤体两极分离\n• Nuclear envelope reassembly —— 核膜重新组装\n• Contractile ring forms cleavage furrow —— 收缩环形成卵裂沟\n【读图讲解】\n细胞分裂荧光图＋模式图：Interphase→Prophase→Prometaphase→Metaphase→Anaphase→Telophase→Cytokinesis。关键：纺锤体微管动态组装、染色体排列赤道板、APC/C 激活降解 cohesin、后期 A/B、收缩环形成分裂沟。考点：微管在 M 期的动态变化。","page":72,"level":"掌握","img":"assets/img/ch06/p072.jpg","anim":null,"fig":null,"points":["Interphase","Prophase","Prometaphase","Metaphase","Chromosomeduplication","Breakdownofinterphase","Nuclearenvelope","Chromosomesaligned at"],"check":null,"cards":null},{"i":72,"sec":"1.7.4 染色体运动","title":"Three classes of MTs of the   ●星体微管(astral microtubles)","notes":"spindle in an animal cell     ●动粒微管(kinetochore MTs)\n●两极微管/极性微管(polar MTs)\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 1.7.4 染色体运动 ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 的一体化网络结构。狭义：指细胞质骨架，位于细胞质中，由微丝、微管、中间纤维构成纤维型的网络结构。弥散性、整体性、变动性共同特点：由蛋白质亚基构成的线性多聚体、动态，可组装和去组装、高度保守微管       （中心粒、鞭毛、纤毛、纺锤体）由 13 根原纤维呈纵向平行排列而成微管蛋白(tubulin)：α 微管蛋白、β 微管蛋白（结合 GTP，可水解为 GDP）聚                              原纤维                    微管异二聚体\n\n【本页英文讲解】\n本页讲动物细胞纺锤体（spindle）中微管的三类：星体微管（astral microtubules）、动粒微管（kinetochore MTs）和两极微管/极性微管（polar MTs）。星体微管由两极伸向细胞皮层，参与纺锤体定位；动粒微管连接着丝粒动粒，负责染色体分离；极性微管在两极间相互重叠并交联，维持纺锤体结构。三类微管的名称、走向与功能对应是本章必考内容。","page":73,"level":"掌握","img":"assets/img/ch06/p073.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":73,"sec":"1.7.4 染色体运动","title":"●微管骨架自身的解聚、聚合⎯MTs behavior during","notes":"formation of the metaphase plate\n→染色体向细胞中\n央赤道板聚集过程是\n由纺锤体微管调控的。\n微管正极动态地收缩\n(解聚)/延伸(聚合)，\n以“搜索、捕获”染色\n体动粒，拉动染色体\n向中央赤道板移动。","page":74,"level":"掌握","img":"assets/img/ch06/p074.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":74,"sec":"1.7.4 染色体运动","title":"在染色体移动中，微管正极与动粒牢牢结合，却能在正极通过","notes":"MT de/polymerization\noccur at the exposed“+”\nend while the MTs\nremains attached to the\nkinetochore.\n丢失或获得tubulin来缩短或延长。\nHow\ndepolymerization\nmay pull the\nkinetochore toward\nthe spindle pole.\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 1.7.4 染色体运动 ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 的一体化网络结构。狭义：指细胞质骨架，位于细胞质中，由微丝、微管、中间纤维构成纤维型的网络结构。弥散性、整体性、变动性共同特点：由蛋白质亚基构成的线性多聚体、动态，可组装和去组装、高度保守微管       （中心粒、鞭毛、纤毛、纺锤体）由 13 根原纤维呈纵向平行排列而成微管蛋白(tubulin)：α 微管蛋白、β 微管蛋白（结合 GTP，可水解为 GDP）聚                              原纤维                    微管异二聚体\n\n【本页英文讲解】\n本页讲染色体移动中动粒微管的动态：微管的解聚/聚合（de/polymerization）发生在暴露的“正端（+ end）”，而微管另一端仍牢牢连接在动粒（kinetochore）上。原文指出，染色体移动时微管正端与动粒牢固结合，却能在正端通过丢失或获得tubulin来缩短或延长。图示说明解聚如何将动粒拉向纺锤体极。核心是“微管正端解聚拉动物粒”的后期A机制。","page":75,"level":"掌握","img":"assets/img/ch06/p075.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":75,"sec":"1.7.4 染色体运动","title":"●Major motor proteins of the spindle","notes":"The colored arrows indicate the direction of motor movement\nalong a MT-blue toward the minus end, and red toward the plus\nend.\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 1.7.4 染色体运动 ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 染色体（chromosome）：当细胞进入有丝分裂时，伸展、弥散的丝状染色质高度折叠、盘曲而凝缩成条状或棒状的特殊形态，称为染色体。\n\n【本页英文讲解】\n本页讲纺锤体的主要马达蛋白（major motor proteins of the spindle），它们参与染色体运动。图中彩色箭头标示马达沿微管的运动方向：蓝色箭头表示朝微管负端移动，红色箭头表示朝微管正端移动。也就是说，不同马达蛋白（如kinesin和dynein）在纺锤体上按方向分工，协同完成染色体排列与分离。方向与功能对应是本节考点。","page":76,"level":"掌握","img":"assets/img/ch06/p076.jpg","anim":null,"fig":null,"points":["involved in chromosome movement"],"check":{"q":"关于「●Major motor proteins of…」，下列说法正确的是（　）","o":["A. 与合成细胞板的物质运输有关","B. 附着在二联体微管上，伸出动","C. These drugs efficiently kill certain types of tumor cells","D. involved in chromosome movement"],"a":"D","e":"本页要点：involved in chromosome movement"},"cards":null},{"i":76,"sec":"1.7.4 染色体运动","title":"The consequence of a","notes":"CK                      missing motor protein\non chromsome\nalignment during\nprometaphase.\nFrog egg extract\nDepleted of a\nparticular kinesin-like\nproein\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 1.7.4 染色体运动 ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 驱动蛋白（kinesin）：与微丝运动有关的动力蛋白，分头部、颈部和尾部。头部是产\f生力的活性部位，尾部能与膜泡结合。\n\n【本页英文讲解】\n本页展示缺失某种马达蛋白的后果（consequence of a missing motor protein）：在哺乳动物细胞前中期（prometaphase），染色体无法正常排列（alignment）。实验中用蛙卵提取物（frog egg extract）去除某种类驱动蛋白（kinesin-like protein）后，观察到染色体排列异常。这说明该马达蛋白是纺锤体正常组装与染色体排列所必需的。缺失功能实验是研究马达蛋白功能的常用手段。","page":77,"level":"掌握","img":"assets/img/ch06/p077.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":77,"sec":"1.7.4 染色体运动","title":"后期A: 染色                后期B：两","notes":"Separate daughter chromosomes at\nanaphase in the mammalian cell\n体向两极运动                 极分离运动\n【结合课本/笔记】后期(anaphase)◆排列在赤道面上的染色体的姐妹染色单体分离产生向极运动◆后期(anaphase)大致可以划分为连续的两个阶段，即后期A和后期B·后期A，动粒微管去装配变短，染色体产生两极运动·后期B，极间微管长度增加，两极之间的距离逐渐拉长，介导染色体向极运动\n\n【本页英文讲解】\n本页讲哺乳动物细胞有丝分裂后期的染色体分离，分为两个阶段：后期A（anaphase A）是染色体向两极运动，即动粒微管解聚把染色体拉向两极；后期B（anaphase B）是两极分离运动，即纺锤体两极相互远离。二者协同完成染色体向子细胞的分配。区分后期A与后期B的运动主体（染色体 vs 两极）是高频考点。","page":78,"level":"掌握","img":"assets/img/ch06/p078.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":78,"sec":"1.7.4 染色体运动","title":"A model of motor protein in anaphase B","notes":"【结合课本/笔记】肌肉收缩系统中的有关蛋白①肌球蛋白(myosin)—所有actin-dependent motor proteins都属于该家族，其头部具ATP酶活力,沿微丝从负极到正极进行运动。·Myosin Ⅱ主要分布于肌细胞，有两个球形头部结构域(具有ATPase活性)和尾部链,多个Myosin尾部相互缠绕，形成myosin filament,即粗肌丝。②原肌球蛋白(tropomyosin, Tm)由两条平行的多肽链形成α-螺旋构型,位于肌动蛋白螺旋沟内,结合于细丝, 调节肌动蛋白与肌球蛋白头部的结合。③肌钙蛋白 (Troponin, Tn)为复合物，包括三个亚基：TnC(Ca2+敏感性蛋白)能特异与Ca2+结合; TnT(与原肌球蛋白结合)\n\n【本页英文讲解】\n本页给出后期B（anaphase B）中马达蛋白作用的模型（model of motor protein in anaphase B）。后期B是纺锤体两极分离的过程，一般认为由两类机制共同驱动：极性微管之间的马达蛋白（如kinesin-5）滑动，将两极推开；同时星体微管在细胞皮层处受力，协助两极分离。原文仅给出标题与模型图，重点掌握“马达蛋白驱动两极分离”这一核心结论。","page":79,"level":"掌握","img":"assets/img/ch06/p079.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":79,"sec":"1.7.4 染色体运动","title":"⎯Both microtubule-depolymerizing drugs (such as vinblastine)","notes":"and microtubule-polymerizing drugs (such as taxol)\npreferentially kill dividing cells, since“ both MT\nassembly and disassembly are crucial for correct\nfunction of the mitotic spindle”.\nin a human patient, although not without toxicity to rapidly\ndividing normal cells, including those in the bone marrow\n(骨髓), intestine (肠), and hair follicles (毛囊)..\nof the breast and lung, and it is frequently successful in\ntreatment of tumors that are resistant to other chemotherapeutic\nagents.\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 1.7.4 染色体运动 ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 纺锤体（mitotic spindle）：有丝分裂前期，中心粒分别移向细胞两级，微管加速聚合，形成纺锤形结构，称为纺锤体。\n\n【本页英文讲解】\n本页讲微管药物与癌症化疗：解聚微管的药物（如长春碱 vinblastine）和稳定/促聚合微管的药物（如紫杉醇 taxol）都优先杀死分裂中的细胞，因为微管的组装与解聚对纺锤体正常功能都至关重要。这些药可有效杀伤某些肿瘤细胞，但对骨髓（bone marrow）、肠（intestine）和毛囊（hair follicles）等快速分裂的正常细胞有毒性。紫杉醇常用于治疗乳腺癌和肺癌，对其他化疗耐药的肿瘤也常有效。","page":80,"level":"掌握","img":"assets/img/ch06/p080.jpg","anim":null,"fig":null,"points":["These drugs efficiently kill certain types of tumor cells","Taxol in particular has been widely used to treat cancers"],"check":{"q":"关于「⎯Both microtubule-depoly…」，下列说法正确的是（　）","o":["A. 2个GTP结合位点:","B. 神经轴突中的蛋白和膜结构的转运;","C. 原生动物中纤毛虫纲、鞭毛虫纲；","D. These drugs efficiently kill certain types of tumor cells"],"a":"D","e":"本页要点：These drugs efficiently kill certain types of tumor cells"},"cards":null},{"i":80,"sec":"1.7.4 染色体运动","title":"哺乳动物小肠上皮细胞的更新和干细胞增殖","notes":"【结合课本/笔记】二、细胞在体内条件下的衰老●在机体内，细胞的衰老和死亡是常见的现象，甚至在个体发育的早期也会发生;●正常情况下终生保持分裂的细胞，其分裂能力是否随着有机体年龄的增高而下降？它们 会不会衰老？◆衰老动物体内，细胞分裂速度显著减慢，其原因主要是G1期明显延长;◆衰老个体内的环境因素影响了细胞的增殖和衰老;◆骨髓干细胞移植实验说明随着年龄的增加，干细胞增殖速度也趋缓慢.","page":81,"level":"掌握","img":"assets/img/ch06/p081.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":81,"sec":"1.7.4 染色体运动","title":"are continuously renewed throughout life. 皮肤和毛发","notes":"The skin and hair are exposed to a harsh external\nenvironment-including UV radiation from sunlight-and\n在整个生命周期中是持续更新的。\nThe stem cells干细胞 responsible for producing\nhair reside in a region of the hair follicle(毛囊)\ncalled the bulge.\nThe bulge stem cells give rise to transit-\namplifying matrix cells(毛基质细胞), which\nproliferate and differentiate to form the hair\nshaft(毛干).\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 1.7.4 染色体运动 ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 的一体化网络结构。狭义：指细胞质骨架，位于细胞质中，由微丝、微管、中间纤维构成纤维型的网络结构。弥散性、整体性、变动性共同特点：由蛋白质亚基构成的线性多聚体、动态，可组装和去组装、高度保守微管       （中心粒、鞭毛、纤毛、纺锤体）由 13 根原纤维呈纵向平行排列而成微管蛋白(tubulin)：α 微管蛋白、β 微管蛋白（结合 GTP，可水解为 GDP）聚                              原纤维                    微管异二聚体\n\n【本页英文讲解】\n本页讲皮肤和毛发（skin and hair）在整个生命周期中持续更新。皮肤与毛发暴露于包括阳光紫外线（UV）在内的恶劣外界环境。负责产生毛发的干细胞（stem cells）位于毛囊（hair follicle）中一个称为隆突（bulge）的区域；隆突干细胞产生短暂扩增的毛基质细胞（transit-amplifying matrix cells），后者增殖并分化形成毛干（hair shaft）。要点是毛发干细胞的定位与分化谱系。","page":82,"level":"掌握","img":"assets/img/ch06/p082.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null}],"mcq":[],"judge":[],"fill":[],"short":[{"id":"ch06_short_6","modI":13,"q":"由神经冲动诱发的肌肉收缩基本过程分哪几步？","a":"由神经冲动诱发的肌肉收缩基本过程可以分为：（1）动作电位的产生；（2）Ca2 的释 ＋   放；（3）原肌球蛋白位移；（4）肌动蛋白丝与肌球蛋白丝的相对滑动；（5）Ca2 的回收。 ＋","kp":"ch06_s13_78"}],"calc":[{"id":"ch06_calc_6","modI":13,"q":"如何理解细胞骨架的动态不稳定性？这一现象与细胞生命活动过程有什么关系？","a":"（1）细胞骨架的动态不稳定性的理解 ①细胞骨架的动态不稳定性是指骨架纤维的持续组装与去组装，通过蛋白亚基的添加和解聚 实现骨架长度的延长或缩短。 ②细胞骨架是一种高度动态的结构体系，细胞的运动是通过肌动蛋白的聚合与解聚完成的。 ③在细胞周期的不同时相，细胞骨架具有完全不同的分布状态。间期微丝、微管分布在细胞 质中，中间丝在细胞质和细胞核均有分布。分裂期时，细胞质中的微管迅速解体，用于纺锤 体微管的延长，牵拉染色体运动；微丝解聚，在细胞赤道板分裂沟部位组装成胞质分裂环， 实现胞质分离；细胞内的中间丝解体，游离在细胞质中。分裂末期，这一过程逆向转变。 （2）细胞骨架的动态不稳定性与细胞生命活动过程的关系 ①在细胞周期中，细胞内的微管经历着动态组装和去组装，在间期和分裂期，其分布或组织 形式存在很大的差异； ②胞质环流和细胞的运动或迁移需要凝胶态与溶胶态的互变； ③细胞的分裂需要纺锤体的组装与解聚； ④细胞核的消失与重新形成也涉及核纤层结构的动态不稳定性； ⑤踏车行为改变了微管或微丝在细胞中分布的部位，可能与细胞的移动有关。","kp":"ch06_s13_70"}],"term":[{"id":"ch06_term_2","modI":13,"term":"肌原纤维（myofrbrils）。","def":"肌原纤维（myofrbrils）是指肌纤维中许多纵行的，直径约 1μm 的圆筒状的微细结构， 与肌肉的收缩有直接关系。骨骼肌的肌原纤维的单位是肌节，藉 Z 线隔开，其中间有 A 带， 两侧有 I 带，明-暗重复单位是肌肉收缩和舒张最基本的功能单位。","kps":"","kp":"ch06_s13_78"}]},{"i":14,"name":"第一节 微管 · 1.7.5 细胞信号转导","slides":[{"i":82,"sec":"1.7.5 细胞信号转导","title":"1.7.5 细胞信号转导","notes":"力、震动、膨压的感受(sensor)\n细胞骨架       ⎯离子通道活性调节；\n细胞凋亡等\n【结合课本/笔记】总趋势●细胞生物学与分子生物学(包括分子遗传学与生物化学) 相互渗透与交融是总的发展趋势。重点领域●染色体DNA与蛋白质相互作用关系—主要是非组蛋白对基因组的作用●细胞增殖、分化、凋亡的相互关系及其调控●细胞信号转导的研究●细胞结构体系的组装","page":83,"level":"掌握","img":"assets/img/ch06/p083.jpg","anim":null,"fig":null,"points":["骨架蛋白对机械刺激，如压","信号分子的细胞定位；","信号分子向核的运输；"],"check":{"q":"关于「细胞信号转导」，下列说法正确的是（　）","o":["A. 与合成细胞板的物质运输有关","B. 附着在二联体微管上，伸出动","C. 骨架蛋白对机械刺激，如压","D. These drugs efficiently kill certain types of tumor cells"],"a":"C","e":"本页要点：骨架蛋白对机械刺激，如压"},"cards":null}],"mcq":[{"id":"ch06_amcq_3","mod":"第一节 微管 · 1.7.5 细胞信号转导","modI":14,"q":"关于「细胞信号转导」，下列说法正确的是（　）","o":["A. 真核细胞中的蛋白纤维网架体系","B. 细胞骨架","C. 2个GTP结合位点:","D. 骨架蛋白对机械刺激，如压"],"a":"D","e":"本页要点：骨架蛋白对机械刺激，如压","kp":"ch06_s14_82"}],"judge":[{"id":"ch06_ajudge_4","modI":14,"q":"骨架蛋白对机械刺激，如压","a":"对","e":"本页要点：骨架蛋白对机械刺激，如压","kp":"ch06_s14_82"}],"fill":[],"short":[],"calc":[{"id":"ch06_calc_5","modI":14,"q":"为什么说细胞骨架是细胞结构和功能的组织者？细胞内一些细胞器和生物大分子的不对 称分布有什么意义？","a":"（1）细胞骨架是细胞结构和功能的组织者的原因 ①细胞骨架形成了细胞的多种结构：微管能形成鞭毛、纤毛、基体和中心体等结构，微丝参 与微绒毛、收缩环、应力纤维、黏着斑和黏着带的形成，中间丝对维持细胞核的形态和形成 桥粒等具有重要的作用； ②细胞骨架在细胞形态发生和维持等方面具有重要的作用； ③细胞骨架在物质运输、信号传递、细胞运动、细胞分裂等活动中具有重要的作用。 （2）细胞内一些细胞器和生物大分子不对称分布的意义 ①细胞内一些细胞器和生物大分子的不对称分布与细胞不同结构或部分具有特定的功能是 相互联系的，这种不对称分布与细胞骨架的组织方式有关； ②神经细胞中的轴突和树突具有大量的胞质骨架，这与轴突和树突形态的维持及物质的定向 运输有关； ③桥粒、半桥粒、黏着斑和黏着带含有丰富的细胞质骨架结构，这与锚定连接的形成有关； ④细胞内一些细胞器和生物大分子的不对称分布特点是与细胞特定结构的功能相一致的。","kp":"ch06_s14_82"}],"term":[]}],"mcq":[{"id":"ch06_mcq_1","mod":"1.3 MTOC and orienta","modI":4,"q":"由微管组成的细胞表面特化结构是（            ）。","o":["A．鞭毛","B．微绒毛","C．伪足","D．桥粒与半桥粒"],"a":"A","e":"纤毛和鞭毛是细胞表面的特化结构，具有运动功能。纤毛和鞭毛的轴心有一束“9 ＋2”排列的平行微管。","kp":"ch06_s4_22"},{"id":"ch06_mcq_2","mod":"一、微管","modI":2,"q":"具有稳定微管的结构特异性药物是（            ）。","o":["A．秋水仙素","B．细胞松弛素","C．鬼笔环肽","D．紫杉酚"],"a":"D","e":"紫杉酚能促进微管的装配，并使已形成的微管稳定，但这种稳定性的增加对细胞是 有害的。","kp":"ch06_s2_15"},{"id":"ch06_mcq_3","mod":"一、微管","modI":2,"q":"微管蛋白在一定条件下，能装配成微管，其管壁由几根原纤维构成？（           ）","o":["A．9","B．11","C．13","D．15"],"a":"C","e":"在微管装配的过程中，αβ二聚体形成后，再形成原纤维（protofilament），经过侧 面增加而扩展为片层，至 13 根原纤维时，即合拢形成一段微管。","kp":"ch06_s2_13"},{"id":"ch06_mcq_4","mod":"1.4 微管特异性药物","modI":5,"q":"促进微管聚合的药物是（         ）。","o":["A．鬼臼素","B．长春花碱","C．紫杉酚","D．细胞松弛素"],"a":"C","e":"A 项，鬼臼素（peltatin）会抑制细胞 DNA 合成，使细胞处于分裂期。B 项，长春 花碱与秋水仙素的作用相似，能抑制微管的装配，是微管的特异性抑制剂。C 项，紫杉酚和 重水（D2O）可使微管稳定性增加并使细胞周期停止于有丝分裂期。D 项，细胞松弛素可以 切断微丝，并结合在微丝正极阻抑肌动蛋白聚合，而可以破坏微丝的三维网络，特异性的抑 制微丝的装配。","kp":"ch06_s5_32"},{"id":"ch06_mcq_5","mod":"1.3 MTOC and orienta","modI":4,"q":"纤毛、鞭毛的基体由下列哪种微管构成（         ）。","o":["A．二联管","B．三联管","C．单管","D．四联管"],"a":"A","e":"中心粒是三联管。","kp":"ch06_s4_22"},{"id":"ch06_mcq_6","mod":"绪论 · 概览","modI":0,"q":"凝胶与溶胶的互变与（       ）的变化有关。","o":["A．微丝","B．微管","C．中间丝","D．胶原纤维"],"a":"A","e":"微丝与细胞伪足的形成与迁移运动有关。","kp":"ch06_s0_0"},{"id":"ch06_mcq_7","mod":"一、微管","modI":2,"q":"微管蛋白的异二聚体上具有哪种核苷酸的结合位点？（             ）","o":["A．GDP","B．ADP","C．GTP","D．ATP"],"a":"C","e":"在α/β-微管蛋白二聚体中，α-微管蛋白上有一个 GTP 结合位点，结合在该位点上的 GTP 通常不会被水解，被称为不可交换位点；β-微管蛋白上也有一个 GTP 结合位点，该 GTP 在微管蛋白二聚体参与组装成微管后即被水解成 GDP，因此β-微管蛋白上的 GTP 结合位点 是可交换位点。","kp":"ch06_s2_6"},{"id":"ch06_amcq_1","mod":"第一节 微管 · 1.5 微管结合蛋白","modI":6,"q":"关于「微管结合蛋白」，下列说法正确的是（　）","o":["A. 真核细胞中的蛋白纤维网架体系","B. Convert chemical energy into","C. 细胞骨架","D. 2个GTP结合位点:"],"a":"B","e":"本页要点：Convert chemical energy into","kp":"ch06_s6_34"},{"id":"ch06_amcq_3","mod":"第一节 微管 · 1.7.5 细胞信号转导","modI":14,"q":"关于「细胞信号转导」，下列说法正确的是（　）","o":["A. 真核细胞中的蛋白纤维网架体系","B. 细胞骨架","C. 2个GTP结合位点:","D. 骨架蛋白对机械刺激，如压"],"a":"D","e":"本页要点：骨架蛋白对机械刺激，如压","kp":"ch06_s14_82"},{"id":"ch06_amcq_1","mod":"第一节 微管 · 1.2 微管极性:","modI":3,"q":"关于「微管极性:」，下列说法正确的是（　）","o":["A. 真核细胞中的蛋白纤维网架体系","B. ●αβ→αβ→αβ重复排列, 头尾相接, 构成微管","C. 细胞骨架","D. 2个GTP结合位点:"],"a":"B","e":"本页要点：●αβ→αβ→αβ重复排列, 头尾相接, 构成微管","kp":"ch06_s3_18"},{"id":"ch06_amcq_3","mod":"第一节 微管 · 1.7.1 植物细胞壁中纤维素的定向沉积-微管","modI":9,"q":"关于「植物细胞壁中纤维素的定向沉积-微管」，下列说法正确的是（　）","o":["A. 真核细胞中的蛋白纤维网架体系","B. 细胞骨架","C. 2个GTP结合位点:","D. (The Arabidopsis Book 2015, Takashi Hashimoto)"],"a":"D","e":"本页要点：(The Arabidopsis Book 2015, Takashi Hashimoto)","kp":"ch06_s9_56"},{"id":"ch06_amcq_5","mod":"第一节 微管 · 1.7.1 维持细胞内膜性细胞器的空间分布：线粒体、","modI":10,"q":"关于「维持细胞内膜性细胞器的空间分布：线粒体、」，下列说法正确的是（　）","o":["A. 真核细胞中的蛋白纤维网架体系","B. 高尔基体、核糖体等","C. 细胞骨架","D. 2个GTP结合位点:"],"a":"B","e":"本页要点：高尔基体、核糖体等","kp":"ch06_s10_57"},{"id":"ch06_amcq_7","mod":"第一节 微管 · 1.7.2 物质运输：微管作为运输轨道，马达蛋白提供动","modI":11,"q":"关于「物质运输：微管作为运输轨道，马达蛋白提供动」，下列说法正确的是（　）","o":["A. 真核细胞中的蛋白纤维网架体系","B. 细胞骨架","C. 2个GTP结合位点:","D. A nerve cell:"],"a":"D","e":"本页要点：A nerve cell:","kp":"ch06_s11_58"}],"judge":[{"id":"ch06_judge_1","modI":4,"q":"通常微管的负端埋在中心体中，而正端只能加长，不能缩短，所以能保证微管的稳定。 （   ）","a":"错","e":"微管的负端埋在中心体中，但正端是可以加长的。","kp":"ch06_s4_25"},{"id":"ch06_judge_2","modI":4,"q":"在动物细胞中，中心体是主要的微管组织中心。（            ）","a":"对","e":"纺锤体微管和胞质微管由中心体基质囊多个γ管蛋白形成的环状核心放射出来。","kp":"ch06_s4_22"},{"id":"ch06_judge_3","modI":4,"q":"微管存在于所有真核生物细胞中。（                 ）","a":"错","e":"人的红细胞中没有微管，另外，原核生物中没有微管。","kp":"ch06_s4_22"},{"id":"ch06_judge_4","modI":5,"q":"紫杉酚能促进微管的装配，因此对细胞是有利的。（                    ）","a":"错","e":"紫杉酚能促进微管的装配，但这种稳定性的增加对细胞是有害的，使细胞周期停止 于有丝分裂期。","kp":"ch06_s5_32"},{"id":"ch06_judge_5","modI":4,"q":"在所有动力动物细胞中，中心体是主要的微管组织中心。（                   ）","a":"错","e":"在动物细胞中，微管组织中心还包括纤毛、鞭毛的基体。","kp":"ch06_s4_22"},{"id":"ch06_judge_6","modI":0,"q":"肌肉的收缩是细肌丝收缩的结果。              （      ）","a":"错","e":"肌肉的收缩是粗肌丝和细肌丝相对滑动的结果。","kp":"ch06_s0_0"},{"id":"ch06_judge_7","modI":8,"q":"纤毛的运动是微管收缩的结果。（                ）","a":"错","e":"纤毛的运动是肌动蛋白运动的结果。","kp":"ch06_s8_55"},{"id":"ch06_judge_8","modI":4,"q":"加入秋水仙碱可抑制绿藻细胞中的胞质环流运动。（                        ）","a":"对","e":"秋水仙碱是微管组装的阻断剂，用它处理细胞会导致细胞内微管系统的解体，从而 抑制胞质环流运动。","kp":"ch06_s4_29"},{"id":"ch06_judge_9","modI":2,"q":"中心粒和基体均不具有自我复制性质。（                       ）","a":"错","e":"中心体与基体都有自我复制能力，新的中心粒是由原来的中心粒在 S 期复制而来， 而基体则可由中心体衍生而来。","kp":"ch06_s2_8"},{"id":"ch06_ajudge_2","modI":6,"q":"Convert chemical energy into","a":"对","e":"本页要点：Convert chemical energy into","kp":"ch06_s6_34"},{"id":"ch06_ajudge_4","modI":14,"q":"骨架蛋白对机械刺激，如压","a":"对","e":"本页要点：骨架蛋白对机械刺激，如压","kp":"ch06_s14_82"},{"id":"ch06_ajudge_2","modI":3,"q":"●αβ→αβ→αβ重复排列, 头尾相接, 构成微管","a":"对","e":"本页要点：●αβ→αβ→αβ重复排列, 头尾相接, 构成微管","kp":"ch06_s3_18"},{"id":"ch06_ajudge_4","modI":9,"q":"(The Arabidopsis Book 2015, Takashi Hashimoto)","a":"对","e":"本页要点：(The Arabidopsis Book 2015, Takashi Hashimoto)","kp":"ch06_s9_56"},{"id":"ch06_ajudge_6","modI":10,"q":"高尔基体、核糖体等","a":"对","e":"本页要点：高尔基体、核糖体等","kp":"ch06_s10_57"},{"id":"ch06_ajudge_8","modI":11,"q":"A nerve cell:","a":"对","e":"本页要点：A nerve cell:","kp":"ch06_s11_58"}],"fill":[{"id":"ch06_fill_1","modI":2,"q":"组成细肌丝主要的三种蛋白质是：______、______、______。组成粗肌丝的主要蛋白成 分是：______。构成微管的蛋白有两类：______和______。","a":"肌动蛋白；原肌球蛋白；肌钙蛋白；肌球蛋白；α-微管蛋白；β-微管蛋白","kp":"ch06_s2_13"},{"id":"ch06_fill_2","modI":4,"q":"______在细胞间期组织形成间期微管，在细胞分裂期组织形成______，因而被称为细胞 的微管组织中心。","a":"中心体；胞质分裂环","kp":"ch06_s4_22"},{"id":"ch06_fill_3","modI":7,"q":"构成纺锤体的微管有三种：______、______和 ______ 。","a":"星体微管；动力微管；极性微管","kp":"ch06_s7_51"},{"id":"ch06_fill_4","modI":2,"q":"细胞质骨架包括______、______和______。","a":"微丝；微管；中间丝","kp":"ch06_s2_13"},{"id":"ch06_fill_5","modI":6,"q":"胞质中微管动力蛋白分为两大类分别为：______（kinesin）和______（cytoplasmic dynein）。 驱动蛋白通常朝微管的______方向运动，动力蛋白朝微管的______运动。","a":"驱动蛋白；动力蛋白；正极；负极","kp":"ch06_s6_44"},{"id":"ch06_fill_6","modI":5,"q":"微管蛋白二聚体是由______和______组成的。","a":"α-微管蛋白；β微管蛋白","kp":"ch06_s5_32"},{"id":"ch06_fill_7","modI":4,"q":"肌丝成分中收缩蛋白有______和______，调节蛋白有______和______。","a":"肌动蛋白；肌球蛋白；原肌球蛋白；肌钙蛋白","kp":"ch06_s4_24"},{"id":"ch06_fill_8","modI":4,"q":"组成纤毛、鞭毛结构的 3 部分是______、______和______，其中______具有 MTOC 作 用。","a":"毛部；基体；根丝；基体","kp":"ch06_s4_22"},{"id":"ch06_fill_9","modI":7,"q":"纺锤体中与染色体连接的微管有______和______。","a":"染色体微管；中间微管","kp":"ch06_s7_51"},{"id":"ch06_fill_10","modI":0,"q":"广义的核骨架成分包括______、______和______。","a":"核基质核纤层；核孔复合体；染色体骨架","kp":"ch06_s0_1"},{"id":"ch06_fill_11","modI":12,"q":"构成一根微管的原纤丝有______条。","a":"13","kp":"ch06_s12_68"},{"id":"ch06_fill_12","modI":5,"q":"紫杉醇和长春花碱抗癌作用的机制分别是______。","a":"抑制微管解聚和抑制微管聚合","kp":"ch06_s5_32"},{"id":"ch06_fill_13","modI":4,"q":"微管在细胞中以三种形式存在，大部分细胞质微管是______不太稳定；构成纤毛、鞭毛 周围小管的是 ______，比较稳定；组成中心粒和基体的是______，十分稳定。","a":"单体；二联体；三联体","kp":"ch06_s4_22"},{"id":"ch06_fill_14","modI":2,"q":"组成细肌丝主要的三种蛋白质是：______、______、______。组成粗肌丝的主要蛋白质 成分是：______ 。构成微管的蛋白有两类：______和 ______。","a":"肌动蛋白；原肌球蛋白；肌钙蛋白；肌球蛋白；α微管蛋白；β微管蛋白","kp":"ch06_s2_13"},{"id":"ch06_fill_15","modI":2,"q":"细胞内具有分子马达（引擎蛋白）作用的蛋白分子有______、______、______、______ 等。","a":"肌球蛋白；动力蛋白；驱动蛋白；ATP 合成酶","kp":"ch06_s2_10"},{"id":"ch06_fill_16","modI":0,"q":"细胞骨架是指存在于真核细胞中的蛋白纤维网架体系，狭义的骨架系统主要是指细胞质 骨架，包括 ______、______和______。","a":"微丝；微管；中间纤维","kp":"ch06_s0_0"},{"id":"ch06_fill_17","modI":1,"q":"广义细胞骨架包括_________、_________、_________及_________，它们一起构成了高 等动物的纤维网络结构。","a":"细胞核骨架；细胞质骨架；细胞膜骨架；细胞外基质","kp":"ch06_s1_5"},{"id":"ch06_fill_18","modI":8,"q":"纤毛具有______结构，通过微管上结合的_________分解_______造成微管间的______。","a":"“9＋2”排列的平行微管；ATP 酶；ATP；二联管解聚","kp":"ch06_s8_55"},{"id":"ch06_fill_19","modI":7,"q":"在神经轴突物质转运过程中，有两种马达蛋白介导，一是_________介导运输小泡由轴突 顶端运向胞体；二是_________介导运输小泡由胞体运向轴突顶端。","a":"动力蛋白；驱动蛋白","kp":"ch06_s7_51"}],"term":[{"id":"ch06_term_1","modI":7,"term":"基粒（basal body）。","def":"基粒（basal body）是指位于鞭毛和纤毛根部，类似于动物细胞中的中心体，呈圆柱状 的微管性结构，平均大小为 0.2～0.5μm。其壁由 9 组微管三联体组成，包括完全微管与不 完全微管。胞质动力蛋白。中心粒和基粒是同源的，在某些时候可以相互转变，且都具有自 我复制能力。","kps":"","kp":"ch06_s7_54"},{"id":"ch06_term_2","modI":13,"term":"肌原纤维（myofrbrils）。","def":"肌原纤维（myofrbrils）是指肌纤维中许多纵行的，直径约 1μm 的圆筒状的微细结构， 与肌肉的收缩有直接关系。骨骼肌的肌原纤维的单位是肌节，藉 Z 线隔开，其中间有 A 带， 两侧有 I 带，明-暗重复单位是肌肉收缩和舒张最基本的功能单位。","kps":"","kp":"ch06_s13_78"},{"id":"ch06_term_3","modI":4,"term":"微管组织中心（microtubule organizingcenter，MTOC）。","def":"微管组织中心（microtubule organizingcenter，MTOC）是指微管在生理状态或实验处理 解聚后重新装配的发生处。如鞭毛基体、动物细胞中的中心体。微管组织中心决定了细胞微 管的极性，微管的负极指向微管组织中心，正极背向微管组织中心。","kps":"","kp":"ch06_s4_23"},{"id":"ch06_term_4","modI":2,"term":"微管蛋白流（tubulin flow）。","def":"微管踏车学说认为微管组装过程中，在 GTP、 Mg2 等条件下，微管蛋白异二聚体不断 ＋   地在微管正极端聚合使微管延长，而微管的负极端则因微管蛋白的解聚缩短。微管蛋白从负 极端解聚下来，又到正极端聚合的流动称为微管蛋白流，但 GTP 不存在时，微管蛋白流就 不会发生。","kps":"","kp":"ch06_s2_6"},{"id":"ch06_term_5","modI":2,"term":"微管相关蛋白（MAP）","def":"微管相关蛋白（MAP）即微管结合蛋白，是指一些与微管密切联系，附着于微管多聚 体上，参与微管装配并能增加微管稳定性的蛋白，包括 MAP1，MAP2，MAP3，tau 蛋白等。 微管相关蛋白多分布于神经元的树突和轴突中，一般认为与骨架纤维间的连接有关，可能决 定了轴突和树突的不同形态。","kps":"","kp":"ch06_s2_10"},{"id":"ch06_term_6","modI":6,"term":"kinesin & cytoplasmatic dynein 相关试题：驱动蛋白与动力蛋白","def":"kinesin 的中文名称是驱动蛋白，cytoplasmatic dynein 的中文名称是细胞质动力蛋白。二 者均属于微管马达蛋白，主要负责为物质沿着微管运输提供能量。 二者的区别在于沿微管运动的方向不同。驱动蛋白从微管的（－）端移向微管的（＋）端， 是正端走向的微管发动机；细胞质动力蛋白是负端走向的微管发动机，担负小泡和各种膜结 合细胞器的运输任务，同时还是细胞分裂中染色体运动的动力来源。","kps":"","kp":"ch06_s6_44"},{"id":"ch06_term_7","modI":4,"term":"MTOC","def":"MTOC 的中文名称是微管组织中心。微管组织中心是指具有起始微管组装和延伸的细 胞结构，细胞内的微管组织中心包括中心体和位于纤毛和鞭毛基部的基体等。MTOC 不仅 为微管提供了生长的起点，而且还决定了微管的方向性。靠近 MTOC 的一端由于生长慢而 称为负端；远离 MTOC 一端的微管生长速度快，称为正端，所以正端指向细胞质基质，常 常靠近细胞质膜。","kps":"","kp":"ch06_s4_20"}],"short":[{"id":"ch06_short_1","modI":4,"q":"微管的主要功能有哪些？","a":"真核细胞内部是高度区域化的体系，微管与生物大分子、细胞器在细胞内的分布，以及 细胞形态的维持具有密切关系。 （1）支持细胞的功能，构成细胞内网状支架，维持细胞形状，固定与支持细胞器的位置。 （2）与细胞器位移和细胞运动有关，染色体的移动、纤毛、鞭毛的运动都是由微管聚合和 解聚产生的。 （3）参与运输，颗粒物质可沿微管移动。 （4）与某些信息的传递有关。","kp":"ch06_s4_23"},{"id":"ch06_short_2","modI":4,"q":"试述纤毛和鞭毛的结构与功能。","a":"纤毛（flagella）和鞭毛（cilia）是真核细胞表面的具有运动功能特化结构。 （1）纤毛和鞭毛的结构：是细胞质膜所包被的细长突起，内部由微管构成轴丝结构。由基 体和纤毛轴丝两部分组成。纤毛轴轴丝为“9＋2”排列微管，即外周 9 组二联体微管＋中央鞘 包围的 2 根中央单体微管。外周二联体微管由 A，B 亚纤维组成，A 亚纤维为完全微管，B 亚纤维仅由 10 个亚基构成。中央微管均为完全微管。基体的微管组成为“9＋0”，无中央微 管。 （2）纤毛和鞭毛的运动机相关的滑动学说被普遍认可：纤毛运动由轴丝介导的相邻二联体 间相互滑动所致。由一个二联体的 A 管伸出的动力蛋白臂的马达结构域在相邻的二联体的 B 管上“行走”。","kp":"ch06_s4_22"},{"id":"ch06_short_3","modI":2,"q":"叙述什么是微管的 GTP 帽和 GDP 帽，其对微管的动态性质有什么影响。","a":"微管的 GTP 或 GDP 帽就是微管正端αβ微管蛋白二聚体结合 GTP 或 GDP 的状态。 （1）如果微管正端结合的是由结合 GTP 的微管蛋白二聚体组成的 GTP 帽结构，微管就趋 于生长； （2）如果微管的正端结合的是由结合 GDP 的微管蛋白二聚体组成的 GDP 帽结构，这种微 管就趋于缩短。 决定微管正端是 GTP 帽还是 GDP 帽，又受两种因素影响：一是结合 GTP 的游离微管蛋白 二聚体的浓度；二是 GTP 帽中 GTP 水解的速度。当（＋）端形成 GTP 帽，而游离微管蛋 白二聚体的浓度又很高时，微管趋向于生长。由于结合 GTP 的游离微管蛋白二聚体的浓度 降低，使得微管延长的速度下降，随着 GTP 水解的不断进行最后 GTP 帽结构转变成 GDP， 逐渐使微管变得不稳定，趋于解聚。细胞内微管的这两种状态是不断发生的，因为细胞内不 断有微管解聚，又不断地有新微管的组装。","kp":"ch06_s2_15"},{"id":"ch06_short_4","modI":0,"q":"如何用荧光显微镜研究细胞骨架?其基本原理是什么？","a":"用荧光显微镜研究细胞骨架主要是基于两方面的原理。 （1）组成细胞骨架的蛋白亚基能够同小分子的荧光染料共价结合，使细胞骨架带上荧光标 记，发出荧光。 （2）可以制备细胞骨架的荧光抗体，然后用荧光抗体进行细胞骨架的研究。借助于这两方 面原理，可用荧光显微镜研究细胞骨架的动力学。例如，用小分子的荧光染料标记细胞骨架 的蛋白亚基，就可以追踪细胞骨架蛋白在细胞活动中的作用，包括组装、去组装、物质运输 等。这种方法还有一个好处，就是在活细胞时就可以观察。 可用荧光抗体研究以很低浓度存在的蛋白质在细胞内的位置，因为标记的荧光抗体同特异的 蛋白质具有很高的亲和性，只要有相应的蛋白质存在，就一定会有反应。这种反应是特异的， 通过荧光显微镜观察就可确定。荧光抗体既可以直接注射活细胞进行反应，也可以加到固定 的细胞或组织切片中进行反应和分析。用这种方法可对微管、肌动蛋白纤维、中间纤维进行 定位。","kp":"ch06_s0_1"},{"id":"ch06_short_5","modI":2,"q":"比较胞质骨架三种组分。","a":"胞质骨架三种组分比较如下： 表 10-1","kp":"ch06_s2_13"},{"id":"ch06_short_6","modI":13,"q":"由神经冲动诱发的肌肉收缩基本过程分哪几步？","a":"由神经冲动诱发的肌肉收缩基本过程可以分为：（1）动作电位的产生；（2）Ca2 的释 ＋   放；（3）原肌球蛋白位移；（4）肌动蛋白丝与肌球蛋白丝的相对滑动；（5）Ca2 的回收。 ＋","kp":"ch06_s13_78"},{"id":"ch06_short_7","modI":1,"q":"如何证明染色体骨架的真实性？","a":"（1）银染法能选择性地显示染色体轴结构；（2）DNA 酶和 RNA 酶处理或用 0.4mol ／LH2sO4 处理去除组蛋白，对染色体轴没有影响，用胰蛋白酶消化则染色体轴破坏，说明 染色体轴是非组蛋白性的；（3）染色体骨架／放射环模型在分子水平上得到两个直接证据。","kp":"ch06_s1_5"},{"id":"ch06_short_8","modI":7,"q":"比较细胞质动力蛋白与驱动蛋白。","a":"（1）两者都是将 ATP 的化学能转化为动能的大的发动机蛋白，都与微管结合在一起， 但只有动力蛋白存在于纤毛和鞭毛的微管之中。 （2）驱动蛋白是通过加末端方式来引导微管的运动，动力蛋白则通过减末端方式来引导微 管运动。 （3）虽然它们在功能上有相似之处，但不是同源蛋白，而且立体结构非常不同。它们并不 属于同一蛋白家族。","kp":"ch06_s7_54"},{"id":"ch06_short_9","modI":12,"q":"列举细菌与动物细胞之间的差别。这些差别很可能是由于在进化过程中出现的部分或所 有现代真核细胞具有的细胞骨架所造成的。","a":"（1）动物细胞相当大，形状多变，而且没有细胞壁，因而需要细胞骨架来支撑并保持 其形状。 （2）动物细胞及其他真核细胞都有细胞核，细胞核靠中间纤维在细胞中成形并维持在适当 的部位。核纤层附着于核被膜的内侧，支持核被膜并使之成形，中间纤维网络包围核并穿行 在细胞质中。 （3）动物细胞可通过改变细胞形状进行移动。这—过程需要肌动蛋白及肌球蛋白的参与。 （4）动物细胞的基因组比细菌大得多，分为许多染色体。细胞分裂时，染色体必须精确地 分配到两个子细胞中。这—过程需要形成有丝分裂纺锤体的微管系统参与。 （5）动物细胞具有胞内细胞器。细胞器在胞内的定位依赖于沿着微管移动的发动机蛋白。 显著的例子是从脊髓到脚部的神经轴突（该轴突可长达 1 m）中，胞内运输小泡（细胞器） 沿着微管的长距离运输。","kp":"ch06_s12_63"},{"id":"ch06_short_10","modI":12,"q":"什么叫凝胶-溶胶（gel-sol）和溶胶-凝胶（sol-gel）转变？","a":"原生动物中的变形虫，高等动物中的巨噬细胞和白细胞等没有鞭毛、纤毛等运动器官， 但能够依靠细胞体的变化进行移动，叫作变形运动。通常要靠胞质环流形成伪足，细胞沿着 伪足形成的方向前进。细胞内流动的细胞质叫作内质，从尾部流向前进中的伪足。当液流到 达伪足时，流动的细胞质分向细胞的两侧，并形成较硬的外质。其间，位于细胞后部的外质 被破坏并向前方提供新的内质，由此产生内质和外质的循环转变，并引起细胞向前移动。细 胞质由坚硬的凝质状态（外质）向可流动的液态（内质）转变的过程称为凝胶-溶胶转变， 相反的过程叫溶胶-凝胶转变。","kp":"ch06_s12_68"},{"id":"ch06_short_11","modI":4,"q":"用秋水仙素处理动物细胞，细胞内质网与高尔基体分布有什么改变，为什么？","a":"（1）秋水仙素处理动物细胞后内质网与高尔基体分布的改变 用秋水仙素处理动物细胞，内质网缩回到细胞核周围，高尔基体解体成小的膜泡样结构分散 在细胞质内，细胞内依赖于微管的物质运输系统全面瘫痪。 （2）发生改变的原因 真核细胞内部是高度区室化的结构，细胞中某些物质的合成部位与行使功能部位往往是不同 的。内膜系统把细胞质分割成一个个区室，将物质合成部位和功能行使部位分隔开，微管是 维持区室化的重要结构基础。秋水仙素是微管蛋白组装抑制剂，当用秋水仙素处理动物细胞 后，微管很快解聚，从而造成内质网和高尔基体凝聚化。","kp":"ch06_s4_22"},{"id":"ch06_short_12","modI":0,"q":"何谓细胞骨架？如何理解细胞骨架是细胞内的一种动态结构？","a":"（1）细胞骨架的概念 细胞骨架是指由细胞内蛋白质成分组成的一个复合的网架系统，包括微管、微丝和中间丝。 与其他细胞结构相比，细胞骨架在形态结构上具有弥散性、整体性和变动性等特点，这些都 是与它们的功能相适应的。细胞骨架为真核细胞所特有，它不仅是活细胞的支撑结构，决定 了细胞的形状并赋予其强度，而且在细胞多种多样的生理活动（如细胞运动、膜泡运输和细 胞分裂等）中发挥着重要作用。 （2）细胞骨架是一种动态结构的理解 由于细胞骨架与细胞运动有关，在不同的功能状态、不同的细胞周期，细胞骨架是不断地组 装或去组装，因此细胞骨架是细胞内的一种动态结构。","kp":"ch06_s0_1"},{"id":"ch06_short_13","modI":8,"q":"试分析纤毛不动症发生机制，并以此为例叙述纤毛和鞭毛的运动机制。","a":"（1）纤毛不动症发生机制 纤毛不动症即原发性纤毛运动障碍（PCD），是指纤毛超微结构具有特异的、先天性遗传缺 陷导致的一组疾病。目前认为 PCD 的纤毛异常与内、外动力蛋白臂的缺失或纤毛动力蛋白 臂中 ATP 酶缺乏或代谢异常有关，以致微管滑行缺乏能量，使纤毛摆动受阻。 （2）纤毛和鞭毛的运动机制 纤毛和鞭毛的运动本质是轴丝动力蛋白介导的相邻二联体微管之间的相互滑动。纤毛和鞭毛 摆动的特征是从基体产生滑动，沿着轴丝将弯曲传递到尾部，因此，二联管之间的滑动必须 转换为弯曲运动。当轴丝上任意两点的滑动速率不等时，滑动即可转换为弯曲。 ①滑动速率的差异主要来自维持轴丝结构的连接蛋白，它们在一定程度上限制了二联管的自 由滑动； ②在某一时间某一位置，只有部分动力蛋白臂被激活，激活一半的动力蛋白臂使轴丝朝一边 弯曲，激活另一半则朝另一边弯曲。二条动力蛋白臂的作用不同，内臂产生滑动，导致轴丝 弯曲，而外臂可以加快滑动的速度。","kp":"ch06_s8_55"},{"id":"ch06_short_14","modI":0,"q":"通过本章的学习，你对生命体的自组装原则有何认识？","a":"我对生命体自组装原则的认识如下： （1）细胞内的复杂结构可由简单的分子组装而成，其组装过程受到细胞本身的调节，这样 便于细胞在不同生理状态下调节细胞结构的组织形式，执行特定的功能。 （2）多种结构相互联系，共同完成细胞的生命活动。 （3）生命体在装配过程中受到多种因素影响。如影响微管组装的因素有秋水仙素、紫杉醇、 长春花碱；影响微丝组装的因素有细胞松弛素、鬼笔环肽。 （4）生命体自组装具有高度的时空顺序性。","kp":"ch06_s0_0"},{"id":"ch06_short_15","modI":1,"q":"除支持作用和运动功能外，细胞骨架还有什么功能？怎样理解“骨架”的概念？","a":"（1）细胞骨架的其他功能 为物质运输提供轨道、参与肌肉收缩和细胞分化、介导染色体的移动和动物细胞胞质分裂、 形成细胞的特化结构等。 （2）“骨架”的理解 ①骨架是指真核细胞内一个复杂的由特异蛋白质组成的纤维网架结构，具有支持功能，在细 胞形态维持、膜性细胞器定位和移动过程中具有重要的作用。 ②理解骨架概念时的注意事项： a．细胞骨架是一种动态平衡的结构； b．具有多种功能； c．由蛋白质组装而成，组装的过程受到信号的调节。","kp":"ch06_s1_5"}],"calc":[{"id":"ch06_calc_1","modI":0,"q":"什么是分子马达？举例说明（至少 3 个）。","a":"分子马达（molecular motor），主要是指依赖于微管的驱动蛋白、动力蛋白和依赖于微 丝的肌球蛋白这三类蛋白超家族的成员。它们既能与微管或者微丝结合，又能与一些细胞器 或膜状小泡特异性结合，并利用水解 ATP 所产生的能量有规则地沿微管或微丝等细胞骨架 纤维运输所携带的“货物”。 （1）肌球蛋白是与微丝相关的一类分子马达。其共同特征是都含有一个作为马达结构域的 头部。其马达结构域包含一个微丝结合位点和一个具有 ATP 酶活性的 ATP 结合位点。 ①Ⅱ型肌球蛋白存在于多种细胞，包含 2 条重链和 4 条轻链。头部即马达结构域，尾部主要 起结构作用。Ⅱ型肌球蛋白尾尾相接所构成的双极纤维能介导相邻的微丝相互滑动。 ②Ⅰ型肌球蛋白头部亦为马达结构域，在 ATP 存在时可沿微丝运动。其尾部结构域具有多 样性，能与多种细胞组分结合，通过头部驱动或细胞质膜作相对于微丝的运动。V 型肌球蛋 白是二聚体马达蛋白，具有两个头部，交替与微丝结合可以确保整个分子以及所运载的“货 物”始终不与微丝脱离。 （2）驱动蛋白是一类蛋白质超家族，与微管相关。通常由 2 条重链和 2 条轻链组成，它们 共有保守的“马达”域，内有 ATP 结合位点和微管结合位点。马达结构域在重链的 N 端，介 导物质向微管的正极运动；而另一些少数驱动蛋白的马达结构域在重链的 C 端，介导物质 向微管的负极运动。 驱动蛋白的马达结构域具有两个重要的功能位点： ①ATP 结合位点； ②微管结合位点。 有关驱动蛋白沿微管运动的分子模型有两种：步行模型和尺蠖爬行模型。大多数学者承认步 行模型：驱动蛋白的两个球状头部交替向前，每水解一分子 ATP，落在后面的那个马达结 构域将移动两部的距离，即 16nm，并循环该过程。 （3）动力蛋白是马达蛋白中最大、移动速度最快的成员： ①轴丝动力蛋白，在纤毛与鞭毛中发现，与纤毛和鞭毛的运动相关； ②胞质动力蛋白，在真核细胞胞质内发现，与细胞内介导微管从正极向负极端的膜泡运输以 及有丝分裂动粒和纺锤体的共定位有关。 动力蛋白由 2 条或 3 条重链，多条轻链及中间链组成。其马达结构域位于重链 C 端，轴丝 动力蛋白有 3 个马达结构域，胞质动力蛋白有 2 个马达结构域。","kp":"ch06_s0_0"},{"id":"ch06_calc_2","modI":1,"q":"试述三种胞质细胞骨架的主要成分、形态结构、功能及特异性药物。","a":"细胞骨架（cytoskeleton）是指真核细胞中复杂的蛋白纤维网架体系。广义的细胞骨架包 括细胞核骨架，细胞质骨架，细胞膜骨架和细胞外基质。狭义的细胞骨架是指细胞质骨架， 包括微丝（microfilament，MF）、微管（microtubule，MT）、中间纤维（inter- mediated filament， IF）。 （1）微管的形态结构：中空圆柱状，直径 15nm，一般长几微米，微管蛋白是与肌动蛋白相 似的一种酸性蛋白质，常常以二聚体存在（αβ-微管蛋白）。 微管的功能：①支架作用：维持细胞形态、固定细胞器。②细胞收缩，伪足运动；如纤毛、 鞭毛。③细胞器位移、染色体分裂与位移。④胞质内物质运输。 特异性药物：紫杉酚：抗肿瘤药物，研究表明它对微管的作用与传统的抗癌药长春花碱和秋 水仙碱等相反，它能促进微管的聚合、抑制微管的解聚。是微管的特异性稳定剂。 （2）微丝的形态结构：微丝存在很普遍，具有可变结构，直径 6 μm，由肌动蛋白组成，与 微管共同构成细胞支架。 微丝的功能：①与微管共同形成细胞支架，以维持细胞形状。②具有运动功能，与细胞质的 运动紧密相关。③与细胞器关系密切。④细胞内信号传递、蛋白质合成支架。 特异性药物：鬼笔环肽：特异性与微丝侧面结合，增强其稳定性，抑制微丝解聚，对微丝具 有稳定作用。荧光标记的鬼笔环肽可特异性的显示微丝。是微丝的特异性稳定剂。 细胞松弛素：可以切断微丝，并结合在微丝正极阻抑肌动蛋白聚合，因而可以破坏微丝的三 维网络，特异性的抑制微丝的装配。是微丝的特异性抑制剂。 （3）中间纤维：大小介于微管和微丝之间，结构复杂。中间纤维具有严格的组织特异性， 不同类型细胞含有不同 IF。按其组织来源及免疫原性可分为 5 类：①角蛋白纤维：为上皮 细胞特有，具有α和β两类，β角蛋白存在于体表、体腔的上皮细胞中，α角蛋白形成头发、 指甲等坚韧结构；②波形纤维：存在于间充质细胞及中胚层来源的细胞中；③神经胶质纤维： 存在于星形神经胶质细胞；④结蛋白纤维：存在于肌肉细胞；⑤神经元纤维：存在于神经元 中。 此外细胞核中的核纤层蛋白（lamin）也是一种中间纤维。 肿瘤细胞转移后仍保留源细胞的 IF，因此可用 IF 抗体来鉴定肿瘤的来源。如乳腺癌和胃肠 道癌，含有角蛋白，因此可断定它来源于上皮组织。而且大多数细胞中只含有一种中间纤维 （少数细胞含有两种以上，如骨骼肌细胞含有结蛋白和波形蛋白）。中间纤维这种严格的组 织特异性，就被应用于肿瘤临床鉴别诊断，以鉴别肿瘤细胞。 至今尚未发信中间纤维的特异性药物。","kp":"ch06_s1_5"},{"id":"ch06_calc_3","modI":2,"q":"动态不稳定性造成微管迅速伸长或缩短。设想一条单一的处于缩短状态的微管： （1）如果要停止缩短并进入伸长状态，其末端必须发生什么变化？ （2）发生这一转换后微管蛋白的浓度有什么变化？ （3）如果溶液中只有 GDP 而没有 GTP，将会发生什么情况？ （4）如果溶液中存在不能被水解的 GTP 类似物，将会发生什么情况？","a":"（1）由于失去了 GTP 帽，即末端的微管蛋白亚基都以结合 GDP 的形式存在，微管因 而缩短。溶液中带有 GTP 的微管蛋白亚基仍会添加到末端，但是寿命很短，因为 GTP 可能 被水解，或者围绕着的微管解体使其脱落下来。但是如果足够的带有 GTP 的亚基以足够快 的速度添加上去并覆盖了微管末端带有 GDP 的微管蛋白亚基，   这时可产生一个新的 GTP 帽， 微管就可重新开始生长。 （2）当微管蛋白浓度较高时，GTP 亚基的添加速率会比较高，因而缩短微管转变为增长微 管的频率也会随微管蛋白浓度的升高而增加。这种调节机制使该系统达到自主平衡：较多微 管的缩短可造成高浓度的游离微管蛋白，转为增长的微管也就增多；反之，增长的微管多了， 游离微管蛋白浓度下降从而 GTP-亚基的添加速率也下降，在某些部位 GTP 水解的速率会超 过添加速率，造成 GTP 帽破坏，微管又开始进入缩短状态。 （3）如果只有 GDP 存在，微管会持续短缩，并最终消失，因为结合有 GDP 的微管蛋白二 聚体之间的亲和力十分低，不可能被稳定地添加到微管上。 （4）如果有 GTP 存在但不能被水解，那么微管将持续增长，直到所有游离的微管蛋白亚基 被消耗完为止。","kp":"ch06_s2_15"},{"id":"ch06_calc_4","modI":0,"q":"细胞中同时存在几种骨架体系有什么意义？是否是物质和能量的一种浪费？","a":"（1）细胞骨架是指细胞内以蛋白质纤维为主要成分的网络结构，细胞中同时存在的骨 架体系为微丝、微管和中间丝，这三种细胞骨架的意义在于它们在细胞的生命活动中各自的 功能。 ①微丝的功能主要有：肌细胞中参与肌原纤维收缩；非肌细胞中参与胞质分裂、胞质环流、 吞噬作用、细胞变形运动、膜泡运输、细胞黏着与连接（黏着带与黏着斑）、微绒毛的支撑 结构等。 ②微管的功能主要包括：支架作用，维持细胞形态、定位细胞器，作为细胞内物质运输通道， 作为纤毛、鞭毛的运动元件，构成纺锤体参与细胞分裂等。 ③中间丝的功能有：为细胞提供机械强度支持，参与细胞连接（桥粒与半桥粒），维持核膜 稳定等。 （2）三种骨架成分在细胞中同时存在不是物质和能量的一种浪费，理由如下： 三种骨架成分在细胞中同时存在，自成系统，但又互相联系，互不重合。微丝分布在靠近细 胞膜的部位，微管、中间丝从细胞核向细胞周缘放射状延伸。它们在功能上相互配合、相互 协调，缺乏任何一种骨架成分都会引起细胞生命活动的异常。因此细胞中同时存在几种骨架 体系并不是物质和能量的浪费。","kp":"ch06_s0_0"},{"id":"ch06_calc_5","modI":14,"q":"为什么说细胞骨架是细胞结构和功能的组织者？细胞内一些细胞器和生物大分子的不对 称分布有什么意义？","a":"（1）细胞骨架是细胞结构和功能的组织者的原因 ①细胞骨架形成了细胞的多种结构：微管能形成鞭毛、纤毛、基体和中心体等结构，微丝参 与微绒毛、收缩环、应力纤维、黏着斑和黏着带的形成，中间丝对维持细胞核的形态和形成 桥粒等具有重要的作用； ②细胞骨架在细胞形态发生和维持等方面具有重要的作用； ③细胞骨架在物质运输、信号传递、细胞运动、细胞分裂等活动中具有重要的作用。 （2）细胞内一些细胞器和生物大分子不对称分布的意义 ①细胞内一些细胞器和生物大分子的不对称分布与细胞不同结构或部分具有特定的功能是 相互联系的，这种不对称分布与细胞骨架的组织方式有关； ②神经细胞中的轴突和树突具有大量的胞质骨架，这与轴突和树突形态的维持及物质的定向 运输有关； ③桥粒、半桥粒、黏着斑和黏着带含有丰富的细胞质骨架结构，这与锚定连接的形成有关； ④细胞内一些细胞器和生物大分子的不对称分布特点是与细胞特定结构的功能相一致的。","kp":"ch06_s14_82"},{"id":"ch06_calc_6","modI":13,"q":"如何理解细胞骨架的动态不稳定性？这一现象与细胞生命活动过程有什么关系？","a":"（1）细胞骨架的动态不稳定性的理解 ①细胞骨架的动态不稳定性是指骨架纤维的持续组装与去组装，通过蛋白亚基的添加和解聚 实现骨架长度的延长或缩短。 ②细胞骨架是一种高度动态的结构体系，细胞的运动是通过肌动蛋白的聚合与解聚完成的。 ③在细胞周期的不同时相，细胞骨架具有完全不同的分布状态。间期微丝、微管分布在细胞 质中，中间丝在细胞质和细胞核均有分布。分裂期时，细胞质中的微管迅速解体，用于纺锤 体微管的延长，牵拉染色体运动；微丝解聚，在细胞赤道板分裂沟部位组装成胞质分裂环， 实现胞质分离；细胞内的中间丝解体，游离在细胞质中。分裂末期，这一过程逆向转变。 （2）细胞骨架的动态不稳定性与细胞生命活动过程的关系 ①在细胞周期中，细胞内的微管经历着动态组装和去组装，在间期和分裂期，其分布或组织 形式存在很大的差异； ②胞质环流和细胞的运动或迁移需要凝胶态与溶胶态的互变； ③细胞的分裂需要纺锤体的组装与解聚； ④细胞核的消失与重新形成也涉及核纤层结构的动态不稳定性； ⑤踏车行为改变了微管或微丝在细胞中分布的部位，可能与细胞的移动有关。","kp":"ch06_s13_70"}],"appcards":[{"front":"微管的主要功能有哪些？","back":"真核细胞内部是高度区域化的体系，微管与生物大分子、细胞器在细胞内的分布，以及 细胞形态的维持具有密切关系。 （1）支持细胞的功能，构成细胞内网状支架，维持细胞形状，固定与支持细胞器的位置。 （2）与细胞器位移和细胞运动有关，染色体的移动、纤毛、鞭毛的运动都是由微管聚合和 解聚产生的。 （3）参与运输，颗粒物质可沿微管移动。 （4）与某些信息的传递有关。","mod":4,"modName":"第一节 微管 · 1.3 MTOC and orienta","points":""},{"front":"试述纤毛和鞭毛的结构与功能。","back":"纤毛（flagella）和鞭毛（cilia）是真核细胞表面的具有运动功能特化结构。 （1）纤毛和鞭毛的结构：是细胞质膜所包被的细长突起，内部由微管构成轴丝结构。由基 体和纤毛轴丝两部分组成。纤毛轴轴丝为“9＋2”排列微管，即外周 9 组二联体微管＋中央鞘 包围的 2 根中央单体微管。外周二联体微管由 A，B 亚纤维组成，A 亚纤维为完全微管，B 亚纤维仅由 10 个亚基构成。中央微管均为完全微管。基体的微管组成为“9＋0”，无中央微 管。 （2）纤毛和鞭毛的运动机相关的滑动学说被普遍认可：纤毛运动由轴丝介导的相邻二联体 间相互滑动所致。由一个二联体的 A 管伸出的动力蛋白臂的马达结构域在相邻的二联体的 B 管上“行走”。","mod":4,"modName":"第一节 微管 · 1.3 MTOC and orienta","points":""},{"front":"叙述什么是微管的 GTP 帽和 GDP 帽，其对微管的动态性质有什么影响。","back":"微管的 GTP 或 GDP 帽就是微管正端αβ微管蛋白二聚体结合 GTP 或 GDP 的状态。 （1）如果微管正端结合的是由结合 GTP 的微管蛋白二聚体组成的 GTP 帽结构，微管就趋 于生长； （2）如果微管的正端结合的是由结合 GDP 的微管蛋白二聚体组成的 GDP 帽结构，这种微 管就趋于缩短。 决定微管正端是 GTP 帽还是 GDP 帽，又受两种因素影响：一是结合 GTP 的游离微管蛋白 二聚体的浓度；二是 GTP 帽中 GTP 水解的速度。当（＋）端形成 GTP 帽，而游离微管蛋 白二聚体的浓度又很高时，微管趋向于生长。由于结合 GTP 的游离微管蛋白二聚体的浓度 降低，使得微管延长的速度下降，随着 GTP 水解的不断进行最后 GTP 帽结构转变成 GDP， 逐渐使微管变得不稳定，趋于解聚。细胞内微管的这两种状态是不断发生的，因为细胞内不 断有微管解聚，又不断地有新微管的组装。","mod":2,"modName":"第一节 微管 · 一、微管","points":""},{"front":"如何用荧光显微镜研究细胞骨架?其基本原理是什么？","back":"用荧光显微镜研究细胞骨架主要是基于两方面的原理。 （1）组成细胞骨架的蛋白亚基能够同小分子的荧光染料共价结合，使细胞骨架带上荧光标 记，发出荧光。 （2）可以制备细胞骨架的荧光抗体，然后用荧光抗体进行细胞骨架的研究。借助于这两方 面原理，可用荧光显微镜研究细胞骨架的动力学。例如，用小分子的荧光染料标记细胞骨架 的蛋白亚基，就可以追踪细胞骨架蛋白在细胞活动中的作用，包括组装、去组装、物质运输 等。这种方法还有一个好处，就是在活细胞时就可以观察。 可用荧光抗体研究以很低浓度存在的蛋白质在细胞内的位置，因为标记的荧光抗体同特异的 蛋白质具有很高的亲和性，只要有相应的蛋白质存在，就一定会有反应。这种反应是特异的， 通过荧光显微镜观察就可确定。荧光抗体既可以直接注射活细胞进行反应，也可以加到固定 的细胞或组织切片中进行反应和分析。用这种方法可对微管、肌动蛋白纤维、中间纤维进行 定位。","mod":0,"modName":"第一节 微管 · 绪论 · 概览","points":""},{"front":"比较胞质骨架三种组分。","back":"胞质骨架三种组分比较如下： 表 10-1","mod":2,"modName":"第一节 微管 · 一、微管","points":""},{"front":"由神经冲动诱发的肌肉收缩基本过程分哪几步？","back":"由神经冲动诱发的肌肉收缩基本过程可以分为：（1）动作电位的产生；（2）Ca2 的释 ＋   放；（3）原肌球蛋白位移；（4）肌动蛋白丝与肌球蛋白丝的相对滑动；（5）Ca2 的回收。 ＋","mod":13,"modName":"第一节 微管 · 1.7.4 染色体运动","points":""},{"front":"如何证明染色体骨架的真实性？","back":"（1）银染法能选择性地显示染色体轴结构；（2）DNA 酶和 RNA 酶处理或用 0.4mol ／LH2sO4 处理去除组蛋白，对染色体轴没有影响，用胰蛋白酶消化则染色体轴破坏，说明 染色体轴是非组蛋白性的；（3）染色体骨架／放射环模型在分子水平上得到两个直接证据。","mod":1,"modName":"第一节 微管 · I 细胞骨架的基本组成及其结构","points":""},{"front":"比较细胞质动力蛋白与驱动蛋白。","back":"（1）两者都是将 ATP 的化学能转化为动能的大的发动机蛋白，都与微管结合在一起， 但只有动力蛋白存在于纤毛和鞭毛的微管之中。 （2）驱动蛋白是通过加末端方式来引导微管的运动，动力蛋白则通过减末端方式来引导微 管运动。 （3）虽然它们在功能上有相似之处，但不是同源蛋白，而且立体结构非常不同。它们并不 属于同一蛋白家族。","mod":7,"modName":"第一节 微管 · 1.6.1 驱动蛋白(kinesin)","points":""},{"front":"列举细菌与动物细胞之间的差别。这些差别很可能是由于在进化过程中出现的部分或所 有现代真核细胞具有的细胞骨架所造成的。","back":"（1）动物细胞相当大，形状多变，而且没有细胞壁，因而需要细胞骨架来支撑并保持 其形状。 （2）动物细胞及其他真核细胞都有细胞核，细胞核靠中间纤维在细胞中成形并维持在适当 的部位。核纤层附着于核被膜的内侧，支持核被膜并使之成形，中间纤维网络包围核并穿行 在细胞质中。 （3）动物细胞可通过改变细胞形状进行移动。这—过程需要肌动蛋白及肌球蛋白的参与。 （4）动物细胞的基因组比细菌大得多，分为许多染色体。细胞分裂时，染色体必须精确地 分配到两个子细胞中。这—过程需要形成有丝分裂纺锤体的微管系统参与。 （5）动物细胞具有胞内细胞器。细胞器在胞内的定位依赖于沿着微管移动的发动机蛋白。 显著的例子是从脊髓到脚部的神经轴突（该轴突可长达 1 m）中，胞内运输小泡（细胞器） 沿着微管的长距离运输。","mod":12,"modName":"第一节 微管 · 1.7.3 鞭毛(flagellae)、纤毛(cilia)运动","points":""},{"front":"什么叫凝胶-溶胶（gel-sol）和溶胶-凝胶（sol-gel）转变？","back":"原生动物中的变形虫，高等动物中的巨噬细胞和白细胞等没有鞭毛、纤毛等运动器官， 但能够依靠细胞体的变化进行移动，叫作变形运动。通常要靠胞质环流形成伪足，细胞沿着 伪足形成的方向前进。细胞内流动的细胞质叫作内质，从尾部流向前进中的伪足。当液流到 达伪足时，流动的细胞质分向细胞的两侧，并形成较硬的外质。其间，位于细胞后部的外质 被破坏并向前方提供新的内质，由此产生内质和外质的循环转变，并引起细胞向前移动。细 胞质由坚硬的凝质状态（外质）向可流动的液态（内质）转变的过程称为凝胶-溶胶转变， 相反的过程叫溶胶-凝胶转变。","mod":12,"modName":"第一节 微管 · 1.7.3 鞭毛(flagellae)、纤毛(cilia)运动","points":""},{"front":"用秋水仙素处理动物细胞，细胞内质网与高尔基体分布有什么改变，为什么？","back":"（1）秋水仙素处理动物细胞后内质网与高尔基体分布的改变 用秋水仙素处理动物细胞，内质网缩回到细胞核周围，高尔基体解体成小的膜泡样结构分散 在细胞质内，细胞内依赖于微管的物质运输系统全面瘫痪。 （2）发生改变的原因 真核细胞内部是高度区室化的结构，细胞中某些物质的合成部位与行使功能部位往往是不同 的。内膜系统把细胞质分割成一个个区室，将物质合成部位和功能行使部位分隔开，微管是 维持区室化的重要结构基础。秋水仙素是微管蛋白组装抑制剂，当用秋水仙素处理动物细胞 后，微管很快解聚，从而造成内质网和高尔基体凝聚化。","mod":4,"modName":"第一节 微管 · 1.3 MTOC and orienta","points":""},{"front":"何谓细胞骨架？如何理解细胞骨架是细胞内的一种动态结构？","back":"（1）细胞骨架的概念 细胞骨架是指由细胞内蛋白质成分组成的一个复合的网架系统，包括微管、微丝和中间丝。 与其他细胞结构相比，细胞骨架在形态结构上具有弥散性、整体性和变动性等特点，这些都 是与它们的功能相适应的。细胞骨架为真核细胞所特有，它不仅是活细胞的支撑结构，决定 了细胞的形状并赋予其强度，而且在细胞多种多样的生理活动（如细胞运动、膜泡运输和细 胞分裂等）中发挥着重要作用。 （2）细胞骨架是一种动态结构的理解 由于细胞骨架与细胞运动有关，在不同的功能状态、不同的细胞周期，细胞骨架是不断地组 装或去组装，因此细胞骨架是细胞内的一种动态结构。","mod":0,"modName":"第一节 微管 · 绪论 · 概览","points":""},{"front":"试分析纤毛不动症发生机制，并以此为例叙述纤毛和鞭毛的运动机制。","back":"（1）纤毛不动症发生机制 纤毛不动症即原发性纤毛运动障碍（PCD），是指纤毛超微结构具有特异的、先天性遗传缺 陷导致的一组疾病。目前认为 PCD 的纤毛异常与内、外动力蛋白臂的缺失或纤毛动力蛋白 臂中 ATP 酶缺乏或代谢异常有关，以致微管滑行缺乏能量，使纤毛摆动受阻。 （2）纤毛和鞭毛的运动机制 纤毛和鞭毛的运动本质是轴丝动力蛋白介导的相邻二联体微管之间的相互滑动。纤毛和鞭毛 摆动的特征是从基体产生滑动，沿着轴丝将弯曲传递到尾部，因此，二联管之间的滑动必须 转换为弯曲运动。当轴丝上任意两点的滑动速率不等时，滑动即可转换为弯曲。 ①滑动速率的差异主要来自维持轴丝结构的连接蛋白，它们在一定程度上限制了二联管的自 由滑动； ②在某一时间某一位置，只有部分动力蛋白臂被激活，激活一半的动力蛋白臂使轴丝朝一边 弯曲，激活另一半则朝另一边弯曲。二条动力蛋白臂的作用不同，内臂产生滑动，导致轴丝 弯曲，而外臂可以加快滑动的速度。","mod":8,"modName":"第一节 微管 · 1.7 微管的功能","points":""},{"front":"通过本章的学习，你对生命体的自组装原则有何认识？","back":"我对生命体自组装原则的认识如下： （1）细胞内的复杂结构可由简单的分子组装而成，其组装过程受到细胞本身的调节，这样 便于细胞在不同生理状态下调节细胞结构的组织形式，执行特定的功能。 （2）多种结构相互联系，共同完成细胞的生命活动。 （3）生命体在装配过程中受到多种因素影响。如影响微管组装的因素有秋水仙素、紫杉醇、 长春花碱；影响微丝组装的因素有细胞松弛素、鬼笔环肽。 （4）生命体自组装具有高度的时空顺序性。","mod":0,"modName":"第一节 微管 · 绪论 · 概览","points":""},{"front":"除支持作用和运动功能外，细胞骨架还有什么功能？怎样理解“骨架”的概念？","back":"（1）细胞骨架的其他功能 为物质运输提供轨道、参与肌肉收缩和细胞分化、介导染色体的移动和动物细胞胞质分裂、 形成细胞的特化结构等。 （2）“骨架”的理解 ①骨架是指真核细胞内一个复杂的由特异蛋白质组成的纤维网架结构，具有支持功能，在细 胞形态维持、膜性细胞器定位和移动过程中具有重要的作用。 ②理解骨架概念时的注意事项： a．细胞骨架是一种动态平衡的结构； b．具有多种功能； c．由蛋白质组装而成，组装的过程受到信号的调节。","mod":1,"modName":"第一节 微管 · I 细胞骨架的基本组成及其结构","points":""},{"front":"什么是分子马达？举例说明（至少 3 个）。","back":"分子马达（molecular motor），主要是指依赖于微管的驱动蛋白、动力蛋白和依赖于微 丝的肌球蛋白这三类蛋白超家族的成员。它们既能与微管或者微丝结合，又能与一些细胞器 或膜状小泡特异性结合，并利用水解 ATP 所产生的能量有规则地沿微管或微丝等细胞骨架 纤维运输所携带的“货物”。 （1）肌球蛋白是与微丝相关的一类分子马达。其共同特征是都含有一个作为马达结构域的 头部。其马达结构域包含一个微丝结合位点和一个具有 ATP 酶活性的 ATP 结合位点。 ①Ⅱ型肌球蛋白存在于多种细胞，包含 2 条重链和 4 条轻链。头部即马达结构域，尾部主要 起结构作用。Ⅱ型肌球蛋白尾尾相接所构成的双极纤维能介导相邻的微丝相互滑动。 ②Ⅰ型肌球蛋白头部亦为马达结构域，在 ATP 存在时可沿微丝运动。其尾部结构域具有多 样性，能与多种细胞组分结合，通过头部驱动或细胞质膜作相对于微丝的运动。V 型肌球蛋 白是二聚体马达蛋白，具有两个头部，交替与微丝结合可以确保整个分子以及所运载的“货 物”始终不与微丝脱离。 （2）驱动蛋白是一类蛋白质超家族，与微管相关。通常由 2 条重链和 2 条轻链组成，它们 共有保守的“马达”域，内有 ATP 结合位点和微管结合位点。马达结构域在重链的 N 端，介 导物质向微管的正极运动；而另一些少数驱动蛋白的马达结构域在重链的 C 端，介导物质 向微管的负极运动。 驱动蛋白的马达结构域具有两个重要的功能位点： ①ATP 结合位点； ②微管结合位点。 有关驱动蛋白沿微管运动的分子模型有两种：步行模型和尺蠖爬行模型。大多数学者承认步 行模型：驱动蛋白的两个球状头部交替向前，每水解一分子 ATP，落在后面的那个马达结 构域将移动两部的距离，即 16nm，并循环该过程。 （3）动力蛋白是马达蛋白中最大、移动速度最快的成员： ①轴丝动力蛋白，在纤毛与鞭毛中发现，与纤毛和鞭毛的运动相关； ②胞质动力蛋白，在真核细胞胞质内发现，与细胞内介导微管从正极向负极端的膜泡运输以 及有丝分裂动粒和纺锤体的共定位有关。 动力蛋白由 2 条或 3 条重链，多条轻链及中间链组成。其马达结构域位于重链 C 端，轴丝 动力蛋白有 3 个马达结构域，胞质动力蛋白有 2 个马达结构域。","mod":0,"modName":"第一节 微管 · 绪论 · 概览","points":""},{"front":"试述三种胞质细胞骨架的主要成分、形态结构、功能及特异性药物。","back":"细胞骨架（cytoskeleton）是指真核细胞中复杂的蛋白纤维网架体系。广义的细胞骨架包 括细胞核骨架，细胞质骨架，细胞膜骨架和细胞外基质。狭义的细胞骨架是指细胞质骨架， 包括微丝（microfilament，MF）、微管（microtubule，MT）、中间纤维（inter- mediated filament， IF）。 （1）微管的形态结构：中空圆柱状，直径 15nm，一般长几微米，微管蛋白是与肌动蛋白相 似的一种酸性蛋白质，常常以二聚体存在（αβ-微管蛋白）。 微管的功能：①支架作用：维持细胞形态、固定细胞器。②细胞收缩，伪足运动；如纤毛、 鞭毛。③细胞器位移、染色体分裂与位移。④胞质内物质运输。 特异性药物：紫杉酚：抗肿瘤药物，研究表明它对微管的作用与传统的抗癌药长春花碱和秋 水仙碱等相反，它能促进微管的聚合、抑制微管的解聚。是微管的特异性稳定剂。 （2）微丝的形态结构：微丝存在很普遍，具有可变结构，直径 6 μm，由肌动蛋白组成，与 微管共同构成细胞支架。 微丝的功能：①与微管共同形成细胞支架，以维持细胞形状。②具有运动功能，与细胞质的 运动紧密相关。③与细胞器关系密切。④细胞内信号传递、蛋白质合成支架。 特异性药物：鬼笔环肽：特异性与微丝侧面结合，增强其稳定性，抑制微丝解聚，对微丝具 有稳定作用。荧光标记的鬼笔环肽可特异性的显示微丝。是微丝的特异性稳定剂。 细胞松弛素：可以切断微丝，并结合在微丝正极阻抑肌动蛋白聚合，因而可以破坏微丝的三 维网络，特异性的抑制微丝的装配。是微丝的特异性抑制剂。 （3）中间纤维：大小介于微管和微丝之间，结构复杂。中间纤维具有严格的组织特异性， 不同类型细胞含有不同 IF。按其组织来源及免疫原性可分为 5 类：①角蛋白纤维：为上皮 细胞特有，具有α和β两类，β角蛋白存在于体表、体腔的上皮细胞中，α角蛋白形成头发、 指甲等坚韧结构；②波形纤维：存在于间充质细胞及中胚层来源的细胞中；③神经胶质纤维： 存在于星形神经胶质细胞；④结蛋白纤维：存在于肌肉细胞；⑤神经元纤维：存在于神经元 中。 此外细胞核中的核纤层蛋白（lamin）也是一种中间纤维。 肿瘤细胞转移后仍保留源细胞的 IF，因此可用 IF 抗体来鉴定肿瘤的来源。如乳腺癌和胃肠 道癌，含有角蛋白，因此可断定它来源于上皮组织。而且大多数细胞中只含有一种中间纤维 （少数细胞含有两种以上，如骨骼肌细胞含有结蛋白和波形蛋白）。中间纤维这种严格的组 织特异性，就被应用于肿瘤临床鉴别诊断，以鉴别肿瘤细胞。 至今尚未发信中间纤维的特异性药物。","mod":1,"modName":"第一节 微管 · I 细胞骨架的基本组成及其结构","points":""},{"front":"动态不稳定性造成微管迅速伸长或缩短。设想一条单一的处于缩短状态的微管： （1）如果要停止缩短并进入伸长状态，其末端必须发生什么变化？ （2）发生这一转换后微管蛋白的浓度有什么变化？ （3）如果溶液中只有 GDP 而没有 GTP，将会发生什么情况？ （4）如果溶液中存在不能被水解的 GTP 类似物，将会发生什么情况？","back":"（1）由于失去了 GTP 帽，即末端的微管蛋白亚基都以结合 GDP 的形式存在，微管因 而缩短。溶液中带有 GTP 的微管蛋白亚基仍会添加到末端，但是寿命很短，因为 GTP 可能 被水解，或者围绕着的微管解体使其脱落下来。但是如果足够的带有 GTP 的亚基以足够快 的速度添加上去并覆盖了微管末端带有 GDP 的微管蛋白亚基，   这时可产生一个新的 GTP 帽， 微管就可重新开始生长。 （2）当微管蛋白浓度较高时，GTP 亚基的添加速率会比较高，因而缩短微管转变为增长微 管的频率也会随微管蛋白浓度的升高而增加。这种调节机制使该系统达到自主平衡：较多微 管的缩短可造成高浓度的游离微管蛋白，转为增长的微管也就增多；反之，增长的微管多了， 游离微管蛋白浓度下降从而 GTP-亚基的添加速率也下降，在某些部位 GTP 水解的速率会超 过添加速率，造成 GTP 帽破坏，微管又开始进入缩短状态。 （3）如果只有 GDP 存在，微管会持续短缩，并最终消失，因为结合有 GDP 的微管蛋白二 聚体之间的亲和力十分低，不可能被稳定地添加到微管上。 （4）如果有 GTP 存在但不能被水解，那么微管将持续增长，直到所有游离的微管蛋白亚基 被消耗完为止。","mod":2,"modName":"第一节 微管 · 一、微管","points":""},{"front":"细胞中同时存在几种骨架体系有什么意义？是否是物质和能量的一种浪费？","back":"（1）细胞骨架是指细胞内以蛋白质纤维为主要成分的网络结构，细胞中同时存在的骨 架体系为微丝、微管和中间丝，这三种细胞骨架的意义在于它们在细胞的生命活动中各自的 功能。 ①微丝的功能主要有：肌细胞中参与肌原纤维收缩；非肌细胞中参与胞质分裂、胞质环流、 吞噬作用、细胞变形运动、膜泡运输、细胞黏着与连接（黏着带与黏着斑）、微绒毛的支撑 结构等。 ②微管的功能主要包括：支架作用，维持细胞形态、定位细胞器，作为细胞内物质运输通道， 作为纤毛、鞭毛的运动元件，构成纺锤体参与细胞分裂等。 ③中间丝的功能有：为细胞提供机械强度支持，参与细胞连接（桥粒与半桥粒），维持核膜 稳定等。 （2）三种骨架成分在细胞中同时存在不是物质和能量的一种浪费，理由如下： 三种骨架成分在细胞中同时存在，自成系统，但又互相联系，互不重合。微丝分布在靠近细 胞膜的部位，微管、中间丝从细胞核向细胞周缘放射状延伸。它们在功能上相互配合、相互 协调，缺乏任何一种骨架成分都会引起细胞生命活动的异常。因此细胞中同时存在几种骨架 体系并不是物质和能量的浪费。","mod":0,"modName":"第一节 微管 · 绪论 · 概览","points":""},{"front":"为什么说细胞骨架是细胞结构和功能的组织者？细胞内一些细胞器和生物大分子的不对 称分布有什么意义？","back":"（1）细胞骨架是细胞结构和功能的组织者的原因 ①细胞骨架形成了细胞的多种结构：微管能形成鞭毛、纤毛、基体和中心体等结构，微丝参 与微绒毛、收缩环、应力纤维、黏着斑和黏着带的形成，中间丝对维持细胞核的形态和形成 桥粒等具有重要的作用； ②细胞骨架在细胞形态发生和维持等方面具有重要的作用； ③细胞骨架在物质运输、信号传递、细胞运动、细胞分裂等活动中具有重要的作用。 （2）细胞内一些细胞器和生物大分子不对称分布的意义 ①细胞内一些细胞器和生物大分子的不对称分布与细胞不同结构或部分具有特定的功能是 相互联系的，这种不对称分布与细胞骨架的组织方式有关； ②神经细胞中的轴突和树突具有大量的胞质骨架，这与轴突和树突形态的维持及物质的定向 运输有关； ③桥粒、半桥粒、黏着斑和黏着带含有丰富的细胞质骨架结构，这与锚定连接的形成有关； ④细胞内一些细胞器和生物大分子的不对称分布特点是与细胞特定结构的功能相一致的。","mod":14,"modName":"第一节 微管 · 1.7.5 细胞信号转导","points":""},{"front":"如何理解细胞骨架的动态不稳定性？这一现象与细胞生命活动过程有什么关系？","back":"（1）细胞骨架的动态不稳定性的理解 ①细胞骨架的动态不稳定性是指骨架纤维的持续组装与去组装，通过蛋白亚基的添加和解聚 实现骨架长度的延长或缩短。 ②细胞骨架是一种高度动态的结构体系，细胞的运动是通过肌动蛋白的聚合与解聚完成的。 ③在细胞周期的不同时相，细胞骨架具有完全不同的分布状态。间期微丝、微管分布在细胞 质中，中间丝在细胞质和细胞核均有分布。分裂期时，细胞质中的微管迅速解体，用于纺锤 体微管的延长，牵拉染色体运动；微丝解聚，在细胞赤道板分裂沟部位组装成胞质分裂环， 实现胞质分离；细胞内的中间丝解体，游离在细胞质中。分裂末期，这一过程逆向转变。 （2）细胞骨架的动态不稳定性与细胞生命活动过程的关系 ①在细胞周期中，细胞内的微管经历着动态组装和去组装，在间期和分裂期，其分布或组织 形式存在很大的差异； ②胞质环流和细胞的运动或迁移需要凝胶态与溶胶态的互变； ③细胞的分裂需要纺锤体的组装与解聚； ④细胞核的消失与重新形成也涉及核纤层结构的动态不稳定性； ⑤踏车行为改变了微管或微丝在细胞中分布的部位，可能与细胞的移动有关。","mod":13,"modName":"第一节 微管 · 1.7.4 染色体运动","points":""}]};